/* 全库分片 7/43，共 1000 首（chinese-gushiwen / chinese-poetry）*/
window.QUAN_KU_PART_6 = [
  {"t":"吊柳司马祠二首 其一","p":"","d":"明代","a":"邓云霄","c":["长沙卑湿贾生悲，司马投荒远过之。万里瘴乡怜逐客，千秋风雅是吾师。", "愚溪草长无遗宅，钴鉧潭空有断碑。愁作招魂裁楚调，浅斟明水荐江蓠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿汤总领 其一","p":"","d":"宋代","a":"郭印","c":["春色平分又六宵，天生良弼佐皇朝。豸冠凛凛周行肃，虎节煌煌蜀地饶。", "已喜月卿还旧物，更看斗极转高标。仁人自合超诸数，鹤算龟龄未是遥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山中即事","p":"","d":"宋代","a":"文天祥","c":["携壶藉草醉斜阳，白鹤飞来月下双。", "芦叶西风惊别浦，芭蕉夜雨隔疏窗。", "千年帝子朱帘梦，一曲仙人铁笛腔。", "若问山翁还瘦否，手持渔竹下寒江。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题王仲序墨客诗卷","p":"","d":"明代","a":"胡奎","c":["王郎酒酣当墨池，五云飞落天孙机。河东美人织不得，仿佛八茧吴蚕丝。", "亲王召见蓬莱殿，天门白日飞龙见。中官传旨赐奚囊，王郎佩服生辉光。", "绛州陈玄最奇绝，落手麟胶三日香。梁园赋客邹枚老，爱尔尊前一倾倒。", "挥毫为写锦囊歌，愿尔千年赞王道。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水调歌头 和张大经赋盆荷","p":"","d":"元代","a":"赵孟＊","c":["江湖渺何许，归兴浩无边。忽闻数声水调，令我意悠然。莫笑盆池咫尺，移得风烟万顷，来傍小窗前。稀疏淡红翠，特地向人妍。华峰头，花十丈，藕如船。那知此中佳趣，别是小壶天。倒挽碧筒酾酒，醉卧绿云深处，云影自田田。梦中呼一叶，散发看书眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汉玉秋蝉有雕檀木为蕉叶以承之者朅尔触兴率成是诗","p":"","d":"清代","a":"弘历","c":["谁制玉为蝉，谁刻木为叶。玉人与木工，本两不相涉。", "二物偶付托，讵是精神接。新蜩鸣绿阴，视此孰庄蝶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答黄用砺明府","p":"","d":"明代","a":"卢龙云","c":["倦游敢道息图南，白社诗篇癖自耽。天地风尘元易厌，渔樵生计也曾谙。", "五湖新水供垂钓，三径閒云引盍簪。知尔玄言今既就，问奇谁复似桓谭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀","p":"","d":"清代","a":"张自超","c":["大道自坦夷，于中生荆棘。扩清有古人，所贵无遗力。", "尧舜至今存，孔孟教不熄。世运或迁移，日月亦食昃。", "遁非圣贤心，剥犹天地德。霜风洗长林，群木涵新色。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玲珑四犯","p":"","d":"宋代","a":"陈允平","c":["金屋春深，似灼灼娉婷，真真娇艳。洗净铅华，依旧曲眉丰脸。犹记舞歇凉州，渐缥缈、碧云缭乱。自玉环、宝镜偷换。别后甚时重见。", "鸾帏凤席鸳鸯荐。但空余、蕙芳兰蒨。天涯柳色青青恨，不入东风眼。惆账二十四桥，任落絮、飞花乱点。奈翠屏、一枕云雨梦，谁惊散。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李沔阳自大梁经裕州因赠三首 其一","p":"","d":"明代","a":"王廷陈","c":["雪夜梁王宴，霜秋宋玉愁。回瞻嵩岳峙，去逐楚江流。", "少室三花树，沧浪一叶舟。南行正摇落，知尔忆林丘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪夜山行","p":"","d":"明代","a":"斯学","c":["孤舟疑入剡，夜绕乱山行。雪与月俱白，江因人更清。", "岚深寒气重，岸断冻痕平。况复人烟少，空闻落雁声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戒事魔十诗 其四","p":"","d":"宋代","a":"李兼","c":["莫念双宗二会经，官中条令至分明。罪流更溢三千里，白佛安能救尔生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丙申元日五绝 其二","p":"","d":"宋代","a":"方回","c":["五更春雨细无声，石路溅泥齿屐鸣。后饮屠苏懒奔走，可能也喜鹁鸠晴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答简夫","p":"","d":"宋代","a":"孙应时","c":["不怪年来万事非，聊须把酒赋新诗。", "乾坤正自无今昔，草木何妨有变衰。", "白发我甘投老去，红颜君惜卧春时。", "古人不朽终何事，此段工夫可浪施。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和朱尉见招","p":"","d":"宋代","a":"韦骧","c":["作尉由来本仙局，况能投隙会僚朋。开怀自适人须美，治具虽疏客不憎。", "雨意初收天爽快，田工将毕岁丰登。高吟大饮无羞涩，祗恐秋风苦不胜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大资政张公挽词四首 其四","p":"","d":"宋代","a":"孙觌","c":["辇路追高躅，联翩接两驺。犹蟠倚天剑，尚舣济川舟。", "元帅俄分阃，羁臣亦首邱。一抔相属地，回首涕交流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"幽怀十二首 其六","p":"","d":"宋代","a":"冯山","c":["高架环四壁，古书浩万卷。腐儒坐相守，大义老不断。", "群言几可用，吾道一能贯。巨贤已经世，博士方浩叹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十三日夜山斋玩月","p":"","d":"宋代","a":"舒岳祥","c":["月傍细细水波云，绣撚金描孔翠纹。夜半冰轮悬净碧，太空不动扫魔群。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送诸乡人赴试南宫","p":"","d":"宋代","a":"吴芾","c":["闻道诸君上玉京，一杯聊复话离情。青钱既中三年选，黄鹄须看万里程。", "欲向他时成远器，要从今日立修名。吾君锐意图兴复，好把嘉言对集英。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻命有感 其一","p":"","d":"明代","a":"王世贞","c":["还留上宰翊皇朝，天阔春风处处饶。自是清时宽去就，百年兄弟好渔樵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王郎中妓席五咏。舞","p":"","d":"唐代","a":"顾况","c":["汗浥新装画不成，丝催急节舞衣轻。", "落花绕树疑无影，回雪从风暗有情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"本意","p":"荷叶杯","d":"清代","a":"曾廉","c":["几幅珠帘翠箔，笙歌声拥白头翁。海霞色映一杯红。", "衰老发春容。无限荷花荷叶，池中百子已成空。只今曲岸已梧桐。", "叶叶向秋风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"师子颂贺新住持","p":"","d":"明代","a":"成鹫","c":["大哉大法王，出为众生父。大哉大师王，生为百兽主。", "法王师子王，不隔毛头许。谛观法王法，请听师子语。", "师子初生时，周行方七步。师子学语时，嚬呻振威怒。", "师子转身时，返掷还超距。师子独行时，彳亍无伴侣。", "师子出山时，鬼神默诃护。狮子奋迅时，波旬生恐怖。", "师子踞座时，龙象如环堵。师子蹴踏时，野干神气沮。", "有耳闻未闻，有目睹未睹。咸聆师子吼，快观师子舞。", "师子舞若何，神力庄严具。一舞入法界，再舞净法土。", "三舞转法轮，四舞酬法乳。五舞吹法螺，六舞击法鼓。", "七舞布法云，八舞施法雨。九舞转法灯，十舞弘法绪。", "师子慧命长，师子法身固。宝山大好山，午天正亭午。", "徽猷振古今，威光耀寰宇。师子复师子，记莂生补处。", "千秋巩化城，天龙领八部。万古演法音，频伽及鹦鹉。", "顽牛老更顽，头角无所取。长歌寄法筵，灯笼触露柱。", "应作如是观，应作如是举。要识师子真，须明向上句。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题妙高峰","p":"","d":"明代","a":"冷士嵋","c":["天拔一峰起，波空四面开。江光浮岛屿，潭影浸楼台。", "折苇番僧渡，乘槎海客来。何须更壶峤，此地即蓬莱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"除夕李伯襄陈集生崔芝林过余守岁拈银烛朝天紫陌长用四平声 其一","p":"","d":"明代","a":"何吾驺","c":["河光寒影渐生新，更傍今宵酌故人。梦去还疑居木石，望来宁复辨金银。", "异时踪迹吾多懒，同调知交尔任真。约略敝衣堪卒岁，十千酤酒候明春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送太守李公","p":"","d":"宋代","a":"陈天麟","c":["乱花翻阵雨，飞絮转轻球。", "别思昏如醉，征鞍挽不留。", "职循今列郡，秩视古诸侯。", "当代人争仰，惟公政最优。", "洋川佳景物，胜迹旧经游。", "未定中原扰，犹怀傍塞忧。", "九重爰锡命，千里藉承流。", "德逐祥云偃，恩随瑞霭浮。", "带刀还陇亩，挟纩动貔貅。", "烽柝开边月，犁锄庆麦秋。", "二天舒士气，五裤沸民讴。", "虞氏三年考，河南第一州。", "霜台方荐墨，黼座想凝旒。", "早晚颁纶綍，东西走置邮。", "迟迟姑去鲁，几几定归周。", "明月湖光远，凌云气象幽。", "烟波浮画鷁，雪浪绕乌牛。", "好逐桃花涨，轻飞竹叶舟。", "径归调玉铉，莫待覆金瓯。", "贱吏伤萍梗，终年仰庇休。", "龙门曾御李，骥坂会依刘。", "不作痴儿女，孜孜话别愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"踏莎行三首 其二","p":"","d":"当代","a":"程滨","c":["一地残花，满枝禁果。卅年踽踽吾将跛。黑貂裘敝夜风寒，人间岂有真天火。", "无可如何，如何不可。镜中万象无非我。自由无过我灵魂，灵魂长向微躯锁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苦旱 其三","p":"","d":"宋代","a":"韩淲","c":["孤坐焦心气不苏，炎风畏景逼头颅。涧流已断无萍实，园圃俱荒失芋区。", "絺绤纵施衣复汗，简编虽近墨难濡。人嘲褦襶交游绝，头白昏昏发懒梳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄怀东林寺匡白监寺","p":"","d":"唐代","a":"齐己","c":["南岳别来无约后，东林归住有前缘。闲搜好句题红叶，", "静敛霜眉对白莲。雁塔影分疏桧月，虎溪声合几峰泉。", "修心若似伊耶舍，传记须添十九贤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"积素","p":"","d":"清代","a":"弘历","c":["积素龙楼晓景澄，霓鸾振迅月娥仍。练光破腊披鸿鹊，线晷回春映绢㲪。", "冻结钉头珠复密，霤垂瓦齿滴还凝。氤氲未肯全消日，为扣重檐玉几层。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"葑门水亭观荷四章 其三","p":"","d":"清代","a":"姚燮","c":["一镜晴漪漾软罗，倾脂莫问旧时河。横桥断处沽帘出，画阁明边鬓影多。", "可惜鸳鸯无次第，尽渠杨柳自婆娑。罗裳窣窣谁家子，置簟蘋阴枕绿哦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绿岛怀古","p":"","d":"当代","a":"张海鸥","c":["绿岛夜朦胧，寒鸦绕碧丛。徘徊思汉土，惆怅觅蓑翁。", "兴废千秋事，沧桑一令中。当时池畔月，仍照旧亭东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送太平路同知王庭珍","p":"","d":"明代","a":"陶安","c":["隔江尘起动边声，采石波涛夜不惊。台鼎调元延世赏，倅车佐守厚民生。", "近来壁垒添烽火，未见天河洗甲兵。月满空船归思切，望中桑梓是东平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和陈允崇登定山","p":"","d":"明代","a":"庄昶","c":["万里风光散远林，晚峰羸马正千寻。手中日月丸天地，眼底风云变古今。", "几笔化工山水趣，五经尼父圣贤心。可堪白首犹多病，老凤西周意自深。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陪祀山陵二首 其一","p":"","d":"明代","a":"宗臣","c":["阊阖门重启，星辰地一隅。寂寥群籁动，惨淡百灵趋。", "剑佩当风乱，松楸上月孤。他年神武气，或恐未荒芜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再送左辖吴公十绝句 其二","p":"","d":"明代","a":"胡应麟","c":["白头徒自新，倾盖俨如故。蔽芾越东西，棠阴十万户。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"来青轩和玉溪韵","p":"","d":"明代","a":"陆深","c":["磴转峰回年复年，古藤乔木暗流泉。西天正在西窗外，一片青青落照前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居 其二","p":"","d":"明代","a":"张家珍","c":["危峰削壁翠千寻，一啸遥传空谷音。天地正当戎马日，声名何与蕨薇心。", "溪桥曲折随山势，松树参差碍日阴。归去西林馀兴在，洞门萝月照弹琴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵和子思舅","p":"","d":"宋代","a":"毕仲游","c":["闻说幽居傍北溪，莫将归思作新诗。未为野客随翁去，应被山僧笑我痴。", "近日病中为酒敌，他年物外得禅师。林泉漫有花开约，借马相从能几时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄郭筠仙浙江四首","p":"","d":"清代","a":"曾国藩","c":["向晚严需破屋寒，娟娟纤月倚檐端。", "自给行箧殷勤觅，苦索家书展转看。", "宦海情怀蝉翼薄，离人心绪茧丝团。", "更怜吴会飘零客，纸帐孤灯坐夜阑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"诫后学","p":"","d":"宋代","a":"释智圆","c":["对食须思稼穑劳，为僧安用事雄豪，", "剃头本意求成佛，不为齐筵坐位高。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"昭君","p":"","d":"当代","a":"崔荣江","c":["大漠关山隔一涯，肯教箫笛换胡笳。兹心犹系沧浪水，汉月明时许浣纱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"钟子建才美而文有怀高云白之作社中人为和章余亦步韵二律代高子赋答二首 其一","p":"","d":"明代","a":"何巩道","c":["芳树亭亭玉不如，思君何事久离居。岂怜蝴蝶迷庄子，难得蒹葭倚太初。", "对镜远山朝霭霭，入弦流水夜徐徐。不须帝子临湘渚，别有愁怀渺矣余。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈一百二十首 其三十九","p":"","d":"宋代","a":"释怀深","c":["十一月二十，唤做大冬日。张三贺郑婆，李四拜王七。", "早辰到夜，费尽平生力。唯有衲僧家，不打者鼓笛。", "铁额昆崙儿，通身黑如漆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂咏 烛","p":"","d":"南北朝","a":"谢朓","c":["杏梁宾未散。", "桂宫明欲沉。", "暧色轻帏里。", "低光照宝琴。", "徘徊云髻影。", "的烁绮疏金。", "恨君秋月夜。", "遗我洞房阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"茶磨山","p":"","d":"清代","a":"潘曾莹","c":["系缆行春桥，策杖茶磨岭。烟鬟浸湖渌，开奁晓妆靓。", "飞鸟没何处，了了见帆影。秀色接楞伽，窅然异尘境。", "杂花不知名，香气幽且静。微风淡疏襟，斜阳恋余景。", "徘徊松桂阴，翠泼秋衫冷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十六罗汉赞","p":"","d":"宋代","a":"释心月","c":["飞锡五天云冉冉，泛杯南海浪悠悠。", "一毫头上轻收拾，不是冤家不聚头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送陈天卿兄弟归豫章","p":"","d":"明代","a":"卢龙云","c":["千里冲寒访旧劳，片帆南望趁江涛。雌雄斗下皆龙气，颉颃云间总凤毛。", "归路不辞乡国远，德星重聚里门高。传家清白真无忝，赠尔谁方范叔袍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵雨丝云鹤二首 其二","p":"","d":"宋代","a":"黄庭坚","c":["几片云如薛公鹤，精神态度不曾齐。安知陇鸟樊笼密，便觉南鹏羽翼低。", "风散又成千里去，夜寒应上九天栖。坐来改变如苍狗，试欲挥毫意自迷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"定风波 其一 潜山驿寄答佟艾生方伯","p":"","d":"清代","a":"周之琦","c":["飏鞭丝、几阵西风，人烟小市吹暝。古驿延秋，虚堂款客，暂得羁魂定。", "翠云深，玉沙净。恰好灊庐秀眉映。幽兴。负松乔旧约，携琴萝径。", "素襟漫整。任缁尘、黯澹残痕凝。向银笺，拂处寒香袖裛，岁晚心期订。", "倚清吟，背窗影。缥晕灯摇半花冷。还省。一声新雁、江南谁听。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"明月入我牖","p":"","d":"宋代","a":"李复","c":["明月入我牖，娟娟满衣裳。", "惊风飘疏竹，凌乱舞清光。", "静坐不能眠，稍知秋夜长。", "却思古人书，探编开缥囊。", "一读三四反，人远心茫茫。", "投编出庭宇，回步影徜徉。", "长空散白露，暗落点青黄。", "肃肃晨气动，满地自为霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长干寺同刘宫苑浴 其一","p":"","d":"宋代","a":"张舜民","c":["人看浴出如枯木，我自无心类死灰。在处秋风吹鬓发，不堪更上雨花台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梦中麓子","p":"","d":"明代","a":"康海","c":["积雨晦皋陆，我车不可前。徘徊望北墅，迤逦横云烟。", "退坐草堂下，篱菊灿且妍。节物忽将改，引杯吟太元。", "微醉体亦倦，梦谒九华天。仙人中麓子，揖予出素编。", "云是广成撰，孰能叩其筌。忆昔魏伯阳，谓我骨当仙。", "苦逐世人好，落魄武亭川。缘业殆将满，数命或有然。", "始思饮刀圭，却老觅长年。语既执我手，欢笑极周旋。", "振袖出两药，光如朝日鲜。挹彼松露下，同吞各一圆。", "五内倏清爽，神采非昔焉。我居太白下，君庐太山颠。", "采芝拾瑶草，餐玉茹井莲。欲会但瞬息，跨鹤何翩翩。", "赤松作参伍，玉女侍几筵。翛然万物表，世网安可牵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜芾奎二侄延师教子","p":"","d":"明代","a":"沈周","c":["俗习务浅鄙，养子多昩教。且云粗识姓，便是学之要。", "学岂止识字，要在知人道。人道重纲常，文艺稍加膏。", "爱子若不教，护病不医疗。往往岁月后，历历见狠傲。", "孝悌莽无知，礼义蔑循蹈。辱父辱门第，至此徒悔懊。", "此过不在子，在父长其暴。能教始为爱，教成自有效。", "不可吝鞭挞，不可恕幼少。今年贺美事，二侄改俗调。", "令子从师儒，诗书发蒙冒。此举足高尚，先绪喜可绍。", "譬谷既历舂，白粲脱黄糙。又譬金溷沙，披汰金乃耀。", "愿言勿中画，进进有远到。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答无可","p":"","d":"清代","a":"马之瑛","c":["军府迎降先署状，仰视飞鸿剧惆怅。彦回名士寿偏多，子卿足下归无恙。", "故国千峰可寄家，兜鍪原不妒袈裟。金陵旧恨空沈锁，宰相新堤自筑沙。", "国成谁秉邦离析，党祸亦由君子激。林宗何必独仙舟，宾硕谁能共复壁。", "烽烟几载历江湖，万死全凭佛力扶。游子尚堪依母隐，仇人俱己伏天诛。", "素心自指井中水，任是波澜风不起。入社何妨有白衣，误人不信皆青史。", "我亦云林学驾车，风流翻令业因加。为语山灵休见拒，从君还一转莲花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小阑干 其一 国历除夕","p":"","d":"当代","a":"章士钊","c":["长安城里一家家。阑夜阒无哗。何氏山林，却来招惹，火树一园花。", "江南相识趁蜂衙。坐久不回车。堂上簸钱，房中度曲，年时劣堪夸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"娟娟昨夜月今宵看已圆待得明宵见宿昔定殊观月明有圆𡙇世事杂悲欢良时那可掷徘徊清夜阑","p":"","d":"明代","a":"朱浙","c":["攀折河边柳，还渡柳边桥。短发不堪把，月明影潇潇。", "穷居远城市，残生付渔樵。翘首望八荒，天宇高寥寥。", "狂歌自成章，聊以娱今宵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"野史口号碑四十四首 其十六","p":"","d":"元代","a":"刘鹗","c":["贼兵欲向翁源洞，纠合官陂来打韶。此策若行诚可虑，南雄唾手可能招。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"啮指题壁","p":"","d":"元代","a":"胡妙端","c":["弱质空怀漆室忧，搜山千骑入深幽。旌旗影乱天同惨，金鼓声淫鬼亦愁。", "父母劬劳何日报，夫妻恩爱此时休。九泉有路还归去，那个云边是越州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送吴亚卿复致政归螺江","p":"","d":"明代","a":"陈炜","c":["五十馀年任畏途，尔来归兴逐莼鲈。风摇双佩辞三殿，云引孤帆入五湖。", "荔酒醉眠花下榻，茶烟吹起竹边厨。白头富贵人间少，况复身閒一事无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登姑苏台怀古","p":"","d":"元代","a":"张羽","c":["荒台独上故城西，辇路凄凉草树迷。废冢已无金虎踞，坏墙时有夜乌啼。", "采香径断来麋鹿，响屟廊空变蒺藜。欲吊伍员何处是，淡烟斜日不堪题。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"白发","p":"","d":"唐代","a":"白居易","c":["雪发随梳落，霜毛绕鬓垂。加添老气味，改变旧容仪。", "不肯长如漆，无过总作丝。最憎明镜里，黑白半头时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上山","p":"","d":"明代","a":"刘崧","c":["上山望大河，旗帜十馀里。不知何处村，但见青烟起。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送朗公讲解还越","p":"","d":"明代","a":"皇甫汸","c":["开教逢鸠什，谈经得马鸣。坐中窥有相，言下了无生。", "法雨和香气，天花落梵声。归时多宝就，刊石为垂名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戏成白发二首","p":"","d":"宋代","a":"张镃","c":["怕见人言老，梳头夜二更。", "谁知灯烛夜，漏逗愈分明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"河津观龙门歌","p":"","d":"清代","a":"冯敏昌","c":["惊涛殷地声如雷，濒河路折听喧豗。连天烟雾不知数，西望一气连峰开。", "峰如连牛亦奇哉，岂谓河自峰腰来。骑危路转峰还回，地穷转石蹶斯下，天成巨闬高何嵬。", "仰看铁壁形如隤，俯积云气容如灰。想像昆仑万里导源至此偪拶不得出，丰隆列缺乃驱应龙画地鼓翼掉尾扬其颏。", "厓开巘豁奚迟回，山口一石门还阂。谁令千丈势忽断，真见当时指麾万众雷辊电激轰钳锤。", "河流怒喷风回埃，建瓴一泻无垠垓。长澜千里更东下，高掌万仞从西摧。", "吁嗟神功安可能，云雷合赖经纶才。试观千秋万古山童水不竭，于中禹迹令人慨想心徘徊。", "山前古庙临危台，降神拜奠倾云罍。云松绕屋鸣作籁，龙蛇满壁昏成煤。", "一从洒澹诸沈灾，何意逝水还相催。淇园竹竿下不尽，宣房瓠子空悲哀。", "我愿元气深滋培，权衡迭运兼公台。济川舟喜盛世见，清河颂许诗人裁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"折花赠内并代答二首 其二","p":"","d":"明代","a":"杨基","c":["一朵折春风，花浓意更浓。而今映花面，不似向时红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"我质本瑚琏，宗庙供频蘩。一朝婴祸难，失身","p":"","d":"宋代","a":"韩希孟","c":["宁当血刃死，不作衽席完。", "汉上有王猛，江南无谢安。", "长号赴洪水，激烈摧心肝。", "宋夫有天下，坚正臣礼秉。", "开国百战功，每阵惟雄整。", "及侍周幼主，臣主常炯炯。", "帝曰卿北伐，山戎今有警。", "死狗莫系尾，此行当系颈。", "即日辞陛下，尽敌心欲逞。", "陈桥忽兵变，不得守箕颍。", "禅让法尧舜，民物普安静。", "有国三百年，仁义道驰骋。", "未改祖宗法，天胡肆大眚。", "细思天地理，中有幸不幸。", "天果丧中原，大似裂冠衽。", "君诚不独活，臣实无魏丙。", "失人焉得人，垂戒尝耿耿。", "江南无谢安，塞北有王猛。", "所以戎马来，飞渡巴陵境。", "大江限南北，今此一舴艋。", "本期固封疆，谁谓如画饼。", "烈火燎昆冈，不辩金玉矿。", "妾本良家子，性僻守孤梗。", "嫁与尚书儿，衔署紫兰省。", "直以才德合，不弃宿瘤瘿。", "初结合欢带，誓比日月昺。", "鸳鸯会双飞，比目愿长并。", "岂期金石坚，化作桑榆景。", "旄头势正然，蚩尤气先屏。", "不意风马牛，复及此燕郢。", "一方遭劫虏，六族死俄顷。", "退鹢落迅风，孤鸾吊空影。", "簪坚折白玉，瓶沉断青绠。", "一死空冥府，忧心长炳炳。", "意坚志不移，改邑不改井。", "我本瑚琏器，安肯作溺皿。", "志节匪转石，气噎如吞鲠。", "不作爝火燃，愿为死灰冷。", "贪生念麹蛾，乞邻羞虎穽。", "借此清江水，葬我全首邻领。", "皇天如有知，定作血面请。", "愿魂化精卫，填海使成岭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乳燕飞（次徐斯远韵寄稼轩）","p":"","d":"宋代","a":"黄机","c":["兴泼元同宇。唤君来、浮君大白，为君起舞。满袖斑斑功名泪，百岁风吹急雨。愁与恨、凭谁分付。醉里狂歌空漫触，且休歌、只倩琵琶诉。人不语，弦自语。", "诗成更将君自赋。渺楼头、烟迷碧草，云连芳树。草树那能知人意，怅望关河梦阻。有心事、笺天天许。绣帽轻裘真男子，政何须、纸上分今古。未办得，赋归去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七歌效杜陵体 其一","p":"","d":"宋代","a":"丘葵","c":["景炎元年北人至，撒花初令豪家备。谁梯祸乱敷我民，敲朴日烦无处避。", "富者有银犹可苏，贫者无银卖田地。呜呼一歌兮歌已衰，天日不见惟阴霾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠故乡人","p":"","d":"宋代","a":"沈括","c":["我家已破出他乡，如连如卓方阜昌。岂料囊金随后散，一齐开铺鬻文章。", "我今滨死秪如许，二友犹堪望轩翥。从头借问向来谁，十室九人非旧主。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵全希言学士","p":"","d":"明代","a":"董纪","c":["慎言玷可磨，学道坚可钻。垩尽鼻不伤，唇亡齿先寒。", "得丧本前定，居俟何后患。终南径虽捷，蜀道行转难。", "至理岂云远，在人方寸间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鼓山颂法眼语在里即求出云大家合眼跳黄河戏成四韵奉答","p":"","d":"宋代","a":"吕本中","c":["合眼跳黄河，未有过得者。岂惟不得过，身亦须判舍。", "告君过河妙，止要具船筏。乘时等风去，过此无别法。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春意渐深送客至山麓田舍来往道中复逢法上人","p":"","d":"宋代","a":"释正觉","c":["华蹊归来鸟啼幕，庖舍炊烟卧风缕。", "西窗旧有竹肋床，伸足曲肱成栩栩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽张正甫二首","p":"","d":"宋代","a":"陈著","c":["别来倏忽一周星，君住家林我泛萍。", "到处逢人问梅坦，有时见梦说兰亭。", "自怜倦翼归迟暮，已报清魂入杳冥。", "多少微言今已矣，义难辞处写为铭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哭黄后峰大理次伍松月韵四首 其二","p":"","d":"明代","a":"王缜","c":["希声高举似鸣岐，棘寺平反未几时。忽尔庄鹏成羽化，伤哉贾鵩促神思。", "衣冠寂寂魂归土，风雨萧萧旐引輀。恐是玉楼成得早，天公命召有程期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古柏行","p":"","d":"当代","a":"傅义","c":["马祖寺中二株柏，祖师开山手亲植。人间风雨越千年，楼宇废兴几经历。", "今惟巨柱撑晴空，旧诚易破新难立。古柏巍然俯残棋，默无一语暗太息。", "菩提空羡了无踪，中华良种永犹龙。龙钟不改淩云势，神力不及造化功。", "伟干凝重如崇阜，高枝摇碧傲东风。三生因果思维外，八极风云指顾中。", "香叶久无鸾凤宿，古遗犹令人肃穆。一株中空沃泥浆，不许风霜侵大腹。", "一株鞠躬若朝参，钢架扶持添劲足。吾儒自昔爱甘棠，心向往之目未瞩。", "我向伟材三顶礼，庆幸崚嶒今犹矗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与定华步行至学海书楼","p":"","d":"近代","a":"佟绍弼","c":["拾阶石磴前，强行不知倦。路从艰苦来，才得平易转。", "忽如置绝顶，胸次纳万变。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李侯新作秋水亭可望松萝诸山客有遗之沈石田画者正会此意","p":"","d":"明代","a":"程敏政","c":["蓦地萝山为写真，石田毫素妙通神。閒来秋水亭中坐，便是丹青个里人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"阿克苏","p":"","d":"清代","a":"王曾翼","c":["锁钥两城连，佳哉望郁然。岩疆望乌什，间道走和田。", "地扼襟喉要，人夸贸易便。商多三晋客，货溢百间廛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冬夜閒吟","p":"","d":"清代","a":"弘历","c":["良夜渐添长，斗杓亦旋北。旌门笳吹奏，大野人声息。", "归辔辞沈阳，乘舆指京国。毡庐坐閒窗，可爱新月色。", "差无尘念萦，微觉轻寒逼。关山巡阅多，历历皆堪忆。", "扬鸾和铃中，玉律忽已易。悠悠今古人，趁此驹过隙。", "百年讵云久，寸阴实可惜。际兹清宵佳，况对寒蟾碧。", "金鸭已结篆，银檠半折堲。却似去冬夜，梅香递宣席。", "所志嗟无成，所学曾何得。惟馀此初心，时时自兢惕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荷池夏雨","p":"","d":"明代","a":"吕渊","c":["新凿荷池引水通，雨深花满趣无穷。盘倾珠颗齐翻翠，衣露霞绡半折红。", "四座凉生风细细，一帘香沁雾濛濛。此中清景真堪赏，何必移家住瀼东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春兴 其一","p":"","d":"明代","a":"朱诚泳","c":["满眼春云合又开，名园处处锦城堆。丁宁好为张油幕，恐有游人冒雨来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿陈松师相公 其二","p":"","d":"明代","a":"王弘诲","c":["铜龙紫气浮朱绂，金阙祥光隐碧纱。笃行汉庭推石氏，雄文西蜀迈苏家。", "蟠桃露缀丹盘冷，玉树风垂彩袖斜。燮理万方同寿域，蓬壶冰月湛流霞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郊庙歌辞。太清宫乐章。第二奏","p":"","d":"唐代","a":"佚名","c":["虚极仙宗本，希夷象帝先。百灵朝太上，万法祖重圆。", "善贷惟冲德，功成谓自然。云门达和气，思用合钧天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莆阳郡斋观物有感 其三","p":"","d":"明代","a":"岳正","c":["石泓近日小鱼游，云起风生水更幽。抛饭饲时争出没，胡僧过说是灵湫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋风何冽冽","p":"杂诗","d":"魏晋","a":"左思","c":["秋风何冽冽，白露为朝霜。", "柔条旦夕劲，绿叶日夜黄。", "明月出云崖，皦皦流素光。", "披轩临前庭，嗷嗷晨雁翔。", "高志局四海，块然守空堂。", "壮齿不恒居，岁暮常慨慷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自咏十律 其五","p":"","d":"元代","a":"丁鹤年","c":["堂堂至正最多才，万国同文寿域开。漠北诸生登第去，越南计吏进贤来。", "凤《韶》九奏黄金殿，鹤驾三朝白玉台。回首黄尘扬碧海，五云无处觅蓬莱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"隋书十首 其八 柳䛒","p":"","d":"明代","a":"郑学醇","c":["麟阁曾闻尽世臣，柳䛒恩宠更无伦。内庭夜宴虚明月，不见词人见偶人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"脩竹二首 其一","p":"","d":"宋代","a":"晁公溯","c":["虚窗倚脩竹，阴晴见佳景。雨隙落馀滋，风棂乱疏影。", "室幽境自閒，心远地愈静。丁宁护云根，留伴岁寒永。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪夜思南山禅友","p":"","d":"明代","a":"德祥","c":["夕雪洒虚堂，禅身懒下床。楮衾清不暖，蜡烛冷无光。", "宿鸟争枝响，寒花上路香。南山有兄弟，岁晚不能忘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"锦缠道 初度","p":"","d":"明代","a":"梁清标","c":["冰雪柴门，寂寞岁寒时候。跳双丸、悬弧今又。风尘澒洞人非旧。", "剩得闲身，浪逐烟波叟。叹种种颠毛，不堪回首。春酿熟、好烹羔剪韭。", "佳人翠袖殷勤，且主盟花月，漫说经纶手。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王倅成老挽诗二首","p":"","d":"宋代","a":"王炎","c":["珠玉山渊润，仁人久里居。", "低徊尝结绶，强健即垂车。", "长厚皆堪法，循良亦可书。", "惜哉怀远业，小试只题舆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"踏莎行 观昆曲牡丹亭","p":"","d":"当代","a":"程滨","c":["一地秋阳，满堂春醉。乱花深处飘长袂。多情挽住美人腰，芳心贮得书生泪。", "四百年前，梦中相对。今生邂逅偏无寐。人间又是一千年，可能重向花间睡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过涧","p":"","d":"宋代","a":"华镇","c":["两山分处水横流，渡水登山趣更幽。却忆当年谢康乐，等閒羁束为封侯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"溪行","p":"","d":"宋代","a":"韩淲","c":["突兀荒荒漫挈瓶，泓澄窈窈且扬舲。隔山鸡犬三家聚，近水鱼虾一岸腥。", "说梦休誇巫峡赋，移文何愧草堂灵。交游少得亲相识，临眺多为旧所经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋得临池柳","p":"","d":"明代","a":"梁有誉","c":["拂岸青阴合，萦堤翠色稠。声从笛里听，影傍镜中浮。", "水与柔情漾，波将舞态留。腰肢怜楚细，眉黛学孙愁。", "濯濯恒笼雾，依依讵奈秋。堪怜张绪去，谁复拟风流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"表叔萧二尹诞日","p":"","d":"明代","a":"符锡","c":["采采东篱菊，时序忽巳遒。翳翳丹枫日，云屋蔽且幽。", "命盒道西家，振衣由东陬。丈人息虑久，兹晨聊共酬。", "壶悬动星彩，钥启祥光浮。中有绿发翁，烱烱方双眸。", "起酌为君寿，祝君寿千秋。千秋亦何有，造物终与游。", "猥予蓬室士，眷此难力求。逝将叩去虚，策驾迷丹丘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚步独至西三首","p":"","d":"宋代","a":"李弥逊","c":["我来点检春踪迹，山北山南绿暗丛。", "留与骚人做秋本，花根一点著泥红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送吕光禄","p":"","d":"宋代","a":"刘敞","c":["泛滥诚易挹，俊贤噬肯留。愧君殊邂逅，卒岁能优游。", "会心到稽吕，访古穷嬴刘。谁令春风来，翩翩动归舟。", "千里在明发，一樽成献酬。江湖望魏阙，离思空悠悠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风雨","p":"","d":"宋代","a":"施枢","c":["入夏惟忧旱，秋来却浸霪。", "风声连海响，山气与云深。", "望岁丹心切，忧时白发侵。", "旅中无别事，隐几自长吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"缪瑜","c":["有客去游丞相阁，无人来问孝廉船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朱上舍自天读予悼耕岩未葬诗而蹙然请以明年任之喜而有作","p":"","d":"清代","a":"全祖望","c":["徵君未死日，破戒受兼金。为葬钟山骨，馀投濑水阴。", "清芬犹未泯，高谊更谁寻。一诸来孤凤，微生慰素心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"张家湾东遇王参政德华","p":"","d":"明代","a":"邵宝","c":["晋溪北上我南游，潞水东头半日留。何处可忘君父念，此行须为庙堂谋。", "百年雅颂知能夏，千里歌讴望有秋。指日王师收战绩，勿言江左旧风流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"𨹁山顶上度重阳节 其二","p":"","d":"清代","a":"吕师濂","c":["吴越如今霜桕肥，炎方且得缓寒衣。但违吾土登楼倦，欲笑参军落帽非。", "客重屠沽投臭味，秋谁瘦健向庭闱。东来一片伤心雁，恐有乡书莫即飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"即席赋得梨分韵无字","p":"","d":"明代","a":"王世贞","c":["汉广偶萍实，南中饶木奴。上林还见品，大谷未全无。", "高露屑金掌，寒冰飞玉壶。长卿故游倦，消渴暂应苏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感遇 其三","p":"","d":"明代","a":"郑梦周","c":["淳风去已远，世道日幽昧。征伐降殷周，祥麟竟遇害。", "凤凰化鸡鹜，兰蕙为萧艾。嗟哉孔与孟，天意屡颠沛。", "时运既如此，生民复何赖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"楮衾用贯酸斋芦花被韵","p":"","d":"明代","a":"邓雅","c":["楮衾如雪绝纤尘，稳卧还须藉布茵。一片白云松下榻，五更明月梦中身。", "惟应纸帐堪同调，祗恐梅花亦笑贫。赢得素风含混沌，夜寒一煦便回春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"广宗寺","p":"","d":"明代","a":"孙传庭","c":["灵鹫峰南半麓高，护持曾此荷宸褒。残碑漫讶沈苔藓，功德元逾铜瓦牢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寓兴十首 其九","p":"","d":"宋代","a":"张至龙","c":["夏月灌鞠根，见花在秋日。先时不施工，临花已何及。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再题避暑山庄三十六景诗 其一 丽正门","p":"","d":"清代","a":"弘历","c":["岩城埤堄固金汤，詄荡门开向午阳。两字新题标丽正，车书恒此会遐方。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋日喜吴光卿孝廉至招同李伯襄太史曾元鲁比部黎有道山人小集 其三","p":"","d":"明代","a":"韩日缵","c":["木叶萧萧下，庭阶事事幽。自公多暇日，久客不禁秋。", "寂寞元吾分，过从得旧游。披襟谈夙昔，竟夕为淹留。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"扬州慢 萤苑怀古","p":"","d":"清代","a":"黄燮清","c":["疏柳摇愁，夕阳催暝，可怜梦里芜城。自琼花谢后，早粉黛飘零。", "叹当日、河边士女，断燐衰焰，都化流萤。问凄凉、谁吊黄昏，犹有箫声。", "翠桡暂倚，玉钩斜、荒草青青。算艳冢秋深，离宫夜老，留得残星。", "不照画眉帘子，无聊处、雨灭还明。诉兴亡遗恨，招凉人语疏灯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"祷雨报恩因到翟园四首 其四","p":"","d":"宋代","a":"杨万里","c":["未必钱园似翟园，翟园窠木最宜看。茂松亭下偏明眼，矮桧平铺翡翠盘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"减字木兰花 题墨兰","p":"","d":"当代","a":"张崇光","c":["墨浓春暖。写布清芬人意远。下笔沉吟。花更随人展素心。", "同心吾与。索赠兰言花解语。萧艾方荣。为道怀香莫与争。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"城中赴范纯甫酒有感","p":"","d":"宋代","a":"陈著","c":["杜鹃啼断洛阳桥，心与萍流絮与飘。", "风雨故都同死梦，山林晚景十年饶。", "相逢得醉有今日，万事忘言付落潮。", "见说隐居归我里，尚堪鸡黍狎招邀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"踏莎行","p":"","d":"清代","a":"袁克文","c":["小语轻圆，微嫣娇腻，珠帘玉烛深深地。嫩愁都趁柳丝飞，柔欢任被炉烟系。", "梦与云迟，眉教月坠，几回春色撩人醉。夜寒应遣酒长温，香浓知是花无睡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题吴仲圭墨竹 其一","p":"","d":"明代","a":"张萱","c":["梅花道人何太奇，墨戏往往秋淋漓。成竹胸中已十丈，萧萧只写两三枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿华严寺","p":"","d":"宋代","a":"陆游","c":["夜宿华严寺，人扶到上方。", "唤僧同看画，避佛旋移床。", "小雨不成雪，烈风还作霜。", "锺残灯渐暗，趺坐默焚香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日 其二","p":"","d":"元代","a":"蓝仁","c":["草木消冰雪，林园换岁时。病传方士剂，閒咏古人诗。", "兄弟飘零恨，儿孙懒钝姿。一杯春日酒，无奈醒愁悲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送文佶归庐岳","p":"","d":"宋代","a":"释重显","c":["春色未深，兴无迟早。瓶谢九江，峰寻五老。到日攀萝独上时，依依莫忘海山脑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"锡杖歌送明楚上人归佛川","p":"","d":"唐代","a":"权德舆","c":["上人远自西天竺，头陀行遍国朝寺。口翻贝叶古字经，", "手持金策声泠泠。护法护身唯振锡，石濑云溪深寂寂。", "乍来松径风更寒，遥映霜天月成魄。后夜空山禅诵时，", "寥寥挂在枯树枝。真法常传心不住，东西南北随缘路。", "佛川此去何时回，应真莫便游天台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"瑞洪","p":"","d":"明代","a":"霍与瑕","c":["鸣桡过瑞洪，微月下西岛。别有泛湖歌，歌声良自好。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水调歌头 赠宝蟾子","p":"","d":"元代","a":"李道纯","c":["学佛学仙要，玄妙在中诚。真铅真汞无非，只是性和情。但得情来归性，便见铅来投汞，二物自交并。日用了无间，大药自然成。识抽添，明进退，要持盈。坤炉乾坤，阴符阳火慢调停。一穷玄关透了，八片顶门裂破，迸出宝蟾明。功行两圆备，谈笑谒三清。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"话旧（亭中对兄姊话兰陵崇贤怀真已来故事，泫然而作）","p":"","d":"唐代","a":"韦应物","c":["存亡三十载，事过悉成空。不惜沾衣泪，并话一宵中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夕次郫县和画壮","p":"","d":"清代","a":"顾光旭","c":["万马今归凯，前宵雨洗兵。花开石犀浦，月上杜鹃城。", "飞盖村笳动，疏林骑火明。艰难经五载，郫酒为君倾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望云图为张掌科季升题","p":"","d":"明代","a":"潘希曾","c":["东华尘土红作堆，生绡咫尺青山开。山头秋气洗天碧，惟有白云閒往来。", "临风引领者谁子，思亲梁公无乃似。谏议平生忠孝心，依稀写出丹青里。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绝句","p":"","d":"唐代","a":"佚名","c":["绿杨阴转画桥斜，舟有笙歌岸有花。", "尽日会稽山色里，蓬莱清浅水仙家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉酬卢端公饮后赠诸公见示之作","p":"","d":"唐代","a":"戴叔伦","c":["佐幕临戎旌旆间，五营无事万家闲。风吹杨柳渐拂地，", "日映楼台欲下山。绮席昼开留上客，朱门半掩拟重关。", "当时不敢辞先醉，误逐群公倒载还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"理故书二首","p":"","d":"宋代","a":"刘克庄","c":["轴犹插高架，檠已弃低墙。", "可惜亡三箧，安能读一箱。", "自惭伯仁退，不及阿宜长。", "但忆初强记，谁知晚健忘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏井诗","p":"","d":"南北朝","a":"范云","c":["乃鉴长林时。", "有浚广庭前。", "即源已为浪。", "因方自成圆。", "兼冬积温水。", "叠暑泌寒泉。", "不甘未应竭。", "既涸断来翾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"遣行十首 其二","p":"","d":"唐代","a":"元稹","c":["十五年前事，恓惶无限情。病僮更借出，羸马共驰声。", "射叶杨才破，闻弓雁已惊。小年辛苦学，求得苦辛行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"卢岩上次韵二首 其一","p":"","d":"明代","a":"卢宁","c":["法门长不二，仙洞窈藏真。顾影依池洁，洗心期日新。", "云明虚阁午，林霁故山春。幽赏兼良会，清樽酌绿筠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题义门胡氏华林书院","p":"","d":"宋代","a":"赵赴","c":["家隐西山下，华林地绝尘。", "门旌千古义，学聚四方人。", "道致清云富，名随白日新。", "他年应许我，猿鹤一相亲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"潭口寻仙洞 其一","p":"","d":"明代","a":"释今无","c":["亦是翛然地，停舟恰受风。水源黎母出，地脉扶桑穷。", "怪鸟藤花杂，嘉葩椰叶重。棋枰不可见，伫立上洪濛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古风其五十一","p":"","d":"唐代","a":"李白","c":["殷後乱天纪。", "楚怀亦已昏。", "夷羊满中野。", "菉葹盈高门。", "比干谏而死。", "屈平窜湘源。", "虎口何婉娈。", "女媭空婵媛。", "彭咸久沦没。", "此意与谁论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀临江寓居","p":"","d":"元代","a":"范梈","c":["石霜峰北淦西头，寄住林塘数亩幽。比及到家犹是客，对人强自说乡愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早起","p":"","d":"明代","a":"李贤（原德）","c":["霜横玉宇旅怀清，候馆鸡鸣月四更。绿酒自供吟处兴，黄花偏动客中情。", "天边孤雁拖秋色，城上群鸦送晚声。莫道高人甘寂寞，尘寰富贵果然轻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"瑞鹤仙 其二","p":"","d":"宋代","a":"葛长庚","c":["赋情多懒率。每醉后疏狂，醒来飘忽。无心恋簪绂。", "漫才高子建，韵欺王勃。胸中绝物。所容者、诗兵酒卒。", "一两时，调发将来，扫尽闷妖愁孽。", "莫说。杀人一万，自损三千，到底臲亶。悬河口讷。非夙世，无灵骨。", "把湖山牌印，莺花权柄，牒过清风朗月。且束之、高阁休休，这回更不。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登庐山诗二首 其二","p":"","d":"南北朝","a":"鲍照","c":["访世失隐沦，从山异灵士。明发振云冠，升峤远栖趾。", "高岑隔半天，长崖断千里。氛雾承星辰，潭壑洞江汜。", "崭绝类虎牙，巑岏象熊耳。埋冰或百年，韬树必千祀。", "鸡鸣清涧中，猿啸白云里。瑶波逐穴开，霞石触峰起。", "回互非一形，参差悉相似。倾听凤管宾，缅望钓龙子。", "松桂盈膝前，如何秽城市。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杏庄游春次前韵呈雪湖","p":"","d":"明代","a":"谢迁","c":["雨霁山庄趣不稀，阴森梧竹款重扉。峰凝宿霭千重秀，日射流光万丈辉。", "新涨接天舟稳坐，游丝惹地手频挥。柳塘曲处鱼歌动，惊起群凫出翠围。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄善画葛君","p":"","d":"明代","a":"徐渭","c":["展箑不尽规，墨色鲜于洗。细图万壑云，寄我青山里。", "感之不能忘，聊寄短篇耳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀文衡山待诏二首 其二","p":"","d":"明代","a":"卢宁","c":["自尔姑苏胤，机坊无锦章。人皆矜墨妙，吾独爱圭芳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"斋居感兴二十首 其十八","p":"","d":"明代","a":"林光","c":["炎蒸一似洗，商令肃金方。单衣理木棉，时易气自凉。", "闭门谢尘鞅，掩卷坐虚堂。大宾虽未接，安敢忘斋庄。", "铭盘启时省，千载怀殷汤。小学教事上，临下或未详。", "颓龄百无成，岁月去何忙。仰羡天边鸿，随阳又南翔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清尊黄菊红萸佩","p":"虞美人","d":"宋代","a":"卢祖皋","c":["清尊黄菊红萸佩。两度云岩醉。帽檐今日更清狂。冷雨疏风、著意过重阳。故宫历历遗烟树。往事知何处。漫山秋色好题诗。吟罢阑干、独自立多时。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"四时为农 其三","p":"","d":"近代","a":"吴未淳","c":["为农岂不好，卜筑水西涯。碧稻酣朝雨，红莲醉晚霞。", "傍堤养鸡鹜，掩径种葵麻。未止安生理，风光亦可夸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题金陵杂兴诗后八首 其二","p":"","d":"宋代","a":"薛师董","c":["刘郎之后更苏郎，不枉随人入建康。秦水钟山几相识，前年忽识好文章。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早泊江城三首 其二","p":"","d":"宋代","a":"董嗣杲","c":["下江逢好春，入城赏新霁。千花春有机，四望天无际。", "老篙不语还，晦迹得少憩。登览且穷探，岂顾跋涉滞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大司徒毕堂翁老年伯蒙恩予告敬赋","p":"","d":"明代","a":"赵嗣芳","c":["勇退初衣遂，孤标夐绝尘。风云扶正气，海岱毓名臣。", "有念皆谋国，无营但致身。贤声蜚李郡，起草动枫宸。", "网释苏凋瘵，波宽纵涸鳞。豸绣关河遍，恩威电露匀。", "圣朝资弼亮，百辟藉陶甄。鹊印清戎索，鹓班领缙绅。", "津门擎一柱，社稷倚□□。喉舌阶愈峻，度支绩转新。", "中外抢多务，南北共忧贫。大都商铢两，岂有粟红陈。", "简括匠心计，节缩总眉颦。叫阍杜鼠雀，握算廪军民。", "何以念松菊，□□想鲈莼。引年非洛社，高卧巳沧滨。", "岩云生佩剑，海月伴垂纶。徙倚丹经在，行吟绿绮亲。", "紫芝餐作饵，黄绮结为邻。野水横舟舰，物望属松筠。", "愿言高赤舄，珍重待蒲轮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寒宵叹","p":"","d":"宋代","a":"贺铸","c":["可怜明月光，委曲照空床。", "自是元无梦，更悲今夜长。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"嘉陵","p":"","d":"唐代","a":"郑谷","c":["细雨湿萋萋，人稀江日西。春愁肠已断，不在子规啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟唐人五言八韵 其四 诸葛丞相渡泸","p":"","d":"清代","a":"顾炎武","c":["火山横日幕，铜涧亘天徼。乱树云南国，交绳僰外桥。", "枕戈穿偪仄，带甲上岧峣。地汁生淫雾，流烟入斗杓。", "七擒依算略，一战定蛮苗。信洽炎荒永，恩宣益部遥。", "深思危大业，隆眷切先朝。更有亲贤表，宫廷告百僚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"田家","p":"","d":"宋代","a":"赵崇嶓","c":["鸡豚白酒乐丰年，饱即高眠不问天。", "少长有恩相尔汝，淳风应似伏羲前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六月十六日夜南溪望月","p":"","d":"宋代","a":"杨万里","c":["溪水留我住，溪月愁我皈。", "望後月更佳，昨宵未为奇。", "大都月色好，一岁能几时。", "人散长是早，月来长是迟。", "初出如大瓮，才露金半规。", "不知独何急，下如有人推。", "忽然脱岭尖，行空安不危。", "似爱溪水净，下浴青琉璃。", "明珠径余尺，沈在千顷陂。", "我欲剌双手，就溪取团晖。", "白小忽乱跳，碎作万金徽。", "须臾波痕定，化为水银池。", "夜久看未足，风露欺病肌。", "我能尚小留，瘦藤歌式微。", "一笑顾群从，来夕肯集兹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"真如庵","p":"","d":"近代","a":"沙曾达","c":["庵寻东外号真如，径曲门幽古佛居。数亩竹林尘不到，杨公文定喜攻书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李商隐学仙","p":"","d":"元代","a":"张雨","c":["谁云有分不关情，沦谪千年为底名。消得权儿羊浣布，诗中唯数玉溪生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六月十四次韵樊武仲喜雨","p":"","d":"宋代","a":"魏了翁","c":["谁信夔夔解感神，嘤嘤赤子母心熏。", "为将一滴翻瓢水，散作千家举臿云。", "大化无端长寂寂，众形有欲自芸芸。", "更须尽挽天河水，亟与三边洗恶氛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"老子婆娑","p":"烛影摇红","d":"宋代","a":"刘辰翁","c":["老子婆娑，那回也上南楼去。素娥有恨隐云屏，元是娇痴故。惊扇徘徊未许。耿多情、为谁堪诉。使君愁绝，独倚阑干，後期无据。有酒如船，片云扫尽霓裳露。他时与客更携鱼，犹记临皋路。因念南羁北旅。醉乌乌、凭君楚舞。问君不见，璧月词成，楼西沉处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄修职雨中送芍药五枝","p":"","d":"宋代","a":"陈与义","c":["微雨湿清晓，老夫门未开。", "煌煌五仙子，并拥翠蕤来。", "烟脂洗尽不自惜，为雨归来更无力。", "老夫五十尚可痴，凭轩一赋会真诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"兹蒙圣恩追录先德当赠诰涣颁之日适余生初度之辰悲喜交中辄形咏叹是用录呈同志共作荣观","p":"","d":"明代","a":"王绅","c":["弱龄志家学，黾勉事讨论。显扬恨无术，恻恻长抱辛。", "今岁倏四十，劬劳在兹辰。宠光适下贲，沛及没与存。", "易名锡美谥，赠诰颁紫宸。片言重山岳，卓彼云汉文。", "悲喜集中怀，庆慰来上宾。匪徒事夸耀，大节从此伸。", "鞠躬谢苍旻，何以酬明恩。君亲两毋忘，不负六尺身。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"海安所 其一","p":"","d":"清代","a":"许南英","c":["一城围一海安营，营外茅房半就倾。十丈红尘风起处，松声入耳杂车声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪晴野望","p":"","d":"宋代","a":"张耒","c":["萧萧空谷隐山云，渡水人归何处村。", "樵径雪迷唐苑路，鸟声寒集汉祠门。", "公堂吏散惟修竹，近岭林疏见饮猿。", "客坐无毡君莫笑，陶潜亦有酒盈樽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"榆关","p":"","d":"当代","a":"张文胜","c":["三月榆关正寒苦，小梅窗下雪深深。瓶笙花影愔愔梦，翰海神京历历心。", "一种寂寥劳玉想，十分冷淡要清吟。江南春色浓如酒，瞻望斗杓谁与斟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百二十三首","p":"","d":"宋代","a":"释崇岳","c":["弥勒真弥勒，分身千百亿。", "时时示时人，时人皆不识。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋蝉","p":"","d":"清代","a":"林以宁","c":["昨夜凉风届节初，园亭景物渐萧疏。高枝坠露堪承饮，深树微云可卜居。", "秦女支砧秋半急，卫娘小鬓夜来梳。遐情自足传霄汉，不逐金梧下玉除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闲中口占数绝 联","p":"","d":"宋代","a":"郑清之","c":["雨多愁麦又忧苗，不雨还忧旱火骄。忧国浪愁端自苦，老天那肯病汤尧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄越南王诗","p":"","d":"清代","a":"李鸿章","c":["河山表里本天成，寄语贤王建树宏。朝汉尉佗犹有志，帝秦新衍竟何名。", "雕题部落三关控，尝胆君臣奄虑生。垂老伏波犹矍铄，五溪南去不胜情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽周侍郎二首 其二","p":"","d":"宋代","a":"朱熹","c":["忆昔趋丹阙，看公上玉除。民饥深献纳，主圣极欷歔。", "解手寒江阔，惊心夜壑虚。朅来空老泪，无地别輀车。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵子封先生答山中僧","p":"","d":"元代","a":"善住","c":["名山不肯住，自欲老深云。凿翠通虚牖，锄荒出坏坟。", "花开留客醉，果熟与猿分。更莫逃幽隐，音书难重闻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留题鉴远楼 其三","p":"","d":"宋代","a":"李弥逊","c":["霜天晓日鉴中新，眼力由来未见真。万古茫茫一尘迹，碧山无际水无垠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哭亡侄孙士铨","p":"","d":"清代","a":"汪嫈","c":["三岁抚汝大，十八弃我去。经年泪眼枯，魂魄归何处。", "汝母托我日，跪床泣告语。侄妇死如归，伤心惟稚孺。", "侄身当中年，妇死必再娶。悯子饥且寒，莫免芦花絮。", "成立岂易言，不肖尤堪惧。怆绝辞未终，双手亲交付。", "■我忍泪听，抱汝曲劝谕。一痛忽剪决，生死判急遽。", "抚汝从兹始，性命相依附。到今十五年，苦心向谁诉。", "冻馁固可虞，温饱益增虑。疴痒最关怀，焦劳夜复曙。", "曾记一医来，目我为乳妪。四岁教识字，解诵唐人句。", "送汝入塾中，督责不汝恕。恐汝德不修，恐汝学不裕。", "历择名师从，璞质勤磨铝。喜汝尚好学，光阴弗自误。", "学业渐可观，长者咸称誉。勉然品行修，立身得依据。", "爱敬根性天，事叔如事父。谓叔性豪侠，轻财略无度。", "负累日益深，积重病成痼。胡不归里闾，资斧从容措。", "侄善事大母，叔无忧内顾。门内百事宜，未可倚厕庶。", "万一值艰难，吾师堪借箸。汝叔闻汝言，意决任驰骛。", "去去倏两年，家书盈尺素。师教汝秉承，读书明世务。", "家事无钜纤，若马能驾驭。一一体我心，假手挥仆御。", "叔母爱汝挚，恩慈多煦煦。叔父寄书来，称汝有才具。", "云儿年卅六，得子望虚屡。侄辈幸得人，吾家本根固。", "我阅汝叔信，悚然增觉寤。慎重加汝餐，汝好希光祚。", "胡天不右汝，一病即物故。悲哉我何堪，惊怆瞥僵仆。", "祸及太无端，痛哭将天吁。我自究我心，何事干天怒。", "即论汝为人，亦应得天助。年少笃天伦，醇悫本畀赋。", "处事虽精明，浑厚随■寓。往往律己严，待人气和煦。", "古谊交朋侪，肝胆每倾吐。岂无富家子，膏粱与纨裤。", "媮薄无性情，汝心最深恶。天真汝未漓，见义力争赴。", "先达与乡贤，见汝翻忻慕。依依我膝前，相离未寸步。", "祷我寿而康，晨昏香一炷。偶逢我疾作，汝心辄惊怖。", "汤药汝亲尝，悉心为调护。侍奉竭欢娱，片言莫我忤。", "诣力进竿头，经史渐镕铸。指顾青云霄，毛丰卜腾翥。", "意此鑫席才，应到玉堂署。祖德扬清风，君恩承湛露。", "而我衰迈年，绵弱难吹呴。得见汝成名，我志聊堪足。", "今乃大不然，逆境来错愕。匪云天作孽，于事何抵捂。", "明知冥漠中，修短关定数。奈我心枯寂，兀坐若泥塑。", "往事一回首，默然神瞿瞿。汝父久赋閒，守株空待兔。", "更抱西河痛，岂复有生趣。汝叔犹远游，飘零悲客路。", "望汝心殷殷，那堪闻此讣。痛汝盼叔归，病中神远注。", "叔归汝长逝，一散遂难聚。日夕恸不忘，涕泪无所住。", "六洲三岛间，闻有返魂树。汝魂招不来，我目已如瞀。", "古寺风潇潇，灵輀且安厝。期汝送我死，今反展汝墓。", "问天天无言，此理终不悟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古十七首 其十七","p":"","d":"宋代","a":"释道行","c":["江南江北勿同伦，疑了还疑笑杀人。谁信一盘油煠底，古今塞断是非门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山行","p":"","d":"宋代","a":"方岳","c":["住世间须出世间，世情何事苦牵攀。", "蟠胸自作三分国，觌面相悬两戒山。", "大好闭门赢得睡，不多识字煞妨閒。", "长须赤脚顽於我，未必淳风不再还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"淮阴叹","p":"","d":"明代","a":"李东阳","c":["营门昼开齐犬吠，蒯生相人先相背。", "古来鸟尽良弓藏，近时刎颈陈与张。", "功成四海身无地，归楚楚疑归汉忌。", "极知犹豫成祸胎，时乎时乎不再来。", "君王恩深辩士走，淮阴胸中血一斗。", "妇人手执生杀机，赤族不待君王归。", "君王归，神为恻。", "独不念秋毫皆信力，舍人一嗾彭王殂。", "淮阴之辞真有无？噫吁?！淮阴之辞真有无？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"【中吕】醉高歌过红绣鞋_看别人鞍马","p":"","d":"元代","a":"贯云石","c":["看别人鞍马上胡颜，叹自己如尘世污眼。英雄谁识男儿汉，岂肯向人行诉难？", "阳气盛冰消北岸，暮云遮日落西山，四时天气尚轮还。秦甘罗疾发禄，姜吕", "望晚登坛，迟和疾时运里趱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南乡子","p":"","d":"宋代","a":"赵葵","c":["束发颂西藩。百万雄掌握间，召到庙堂无一事，遭弹。昨日公卿今日间。", "拂晓出长安。莫待西风割面寒。羞见钱塘江上柳，何颜。瘦仆牵驴过远山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"公馀八景 其八 雪霁寒梅","p":"","d":"明代","a":"徐庸","c":["绛苇青枝□倚墙，六花□□早封香。共知结就累累实，鼎鼐调羹入庙廊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朱华塔成三首","p":"","d":"明代","a":"卢宁","c":["竖塔障江涟，吾民种福田。孤高周石室，明远汉通天。", "金紫千家丽，仪章六代贤。平川成乐土，长世祝皇年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"采石吊李太白","p":"","d":"明代","a":"张诩","c":["一江风雨浪纷披，鼓枻长过采石矶。千载斯人疑不死，一生豪气尚争辉。", "夜郎天阔冥鸿去，五老峰高白鹤飞。吟罢小诗天忽霁，醉呼明月满船归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"无题","p":"","d":"当代","a":"吴金水","c":["渺渺溪村没野禽，嶙峋翠嶂起烟浔。青山菊酒红莲米，紫陌桃花绿绮琴。", "梦不由人难再续，楼堪纵目且重临。嚣尘十载情怀减，如许风光只一吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风雨中寻李十一，因题船上","p":"","d":"唐代","a":"白居易","c":["匹马来郊外，扁舟在水滨。可怜冲雨客，来访阻风人。", "小榼酤清醑，行厨煮白鳞。停杯看柳色，各忆故园春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古十首 其三","p":"","d":"宋代","a":"释昙华","c":["出得出不得，满面是埃尘。愁人莫向愁人说，说向愁人愁杀人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又题白鹭洲江鸥送陈君","p":"","d":"唐代","a":"徐铉","c":["白鹭洲边江路斜，轻鸥接翼满平沙。吾徒来送远行客，", "停舟为尔长叹息。酒旗渔艇两无猜，月影芦花镇相得。", "离筵一曲怨复清，满座销魂鸟不惊。人生不及水禽乐，", "安用虚名上麟阁。同心携手今如此，金鼎丹砂何寂寞。", "天涯后会眇难期，从此又应添白髭。愿君不忘分飞处，", "长保翩翩洁白姿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郊庙歌辞。梁太庙乐舞辞。来仪舞","p":"","d":"唐代","a":"佚名","c":["於赫帝命，应天顺人。亭育品汇，宾礼百神。", "洪基永固，景命惟新。肃恭孝享，祚我生民。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暮年即事","p":"","d":"宋代","a":"姜特立","c":["八十衰翁如小儿，爱餐梨栗作儿嬉。", "有时淡饮三杯酒，无事閒吟两首诗。", "还丹却老吾不知，头童齿豁一听之。", "但愿造物相扶持，寿考或可登期赜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答杨教见和","p":"","d":"宋代","a":"王质","c":["饭鼓逢逢睡起时，先生弟子总关扉。不妨堂下轻骑马，切莫江头浪典衣。", "且对灯花随雨落，任从苜蓿列盘稀。杜陵郑老襟期在，今昨那能定是非。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"复见官军诗","p":"","d":"宋代","a":"楼钥","c":["元帅平京邑，声声夹道闻。", "不图当此日，复得见官军。", "将钺来何莫，壶浆意已勤。", "重瞻貔虎士，尽扫犬羊群。", "王旅方驰电，民心极望云。", "长安十万户，拭目待吾君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"贺秀岩李工侍七首 其四","p":"","d":"宋代","a":"程公许","c":["封章三上意拳拳，却恨归无一壑专。商略浮生皆寄耳，直须勘破劫空前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答四弟贺添仲孙之作","p":"","d":"明代","a":"张嗣纲","c":["蹠掌青云当户开，再逢维岳降祥来。莲峰翠耸金牛渡，珠海光投玉燕怀。", "但愿门前垂五柳，敢誇日后应三槐。积书幸得儿孙读，可有文章接上台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重九和韵","p":"","d":"清代","a":"费墨娟","c":["登高纵览蹑龙岗，到此开怀万虑忘。胜地清游嫌日短，芳辰雅会寄情长。", "千林红叶堪描画，三径黄花可泛觞。愧我才疏如袜线，强承佳韵报诗囊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送陇州使君刘仲仪左藏赴治","p":"","d":"宋代","a":"强至","c":["夹道浓香数里焚，随车和气一城薰。", "兵民如见古循吏，文武兼能今使君。", "冷射祠堂汧水月，晴飞郡阁陇山云。", "幕中知有才从事，樽俎清谈定喜闻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登大伊山望海慨然有作","p":"","d":"清代","a":"谢元淮","c":["童男帅女觅蓬壶，却笑秦皇作计粗。采药楼船何日返，登山筇屐此时俱。", "江河入海涵清浊，齐鲁连云望有无。谁信凫夷来地底，一挥长剑扫天吴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送尹商衡都黄门出狱","p":"","d":"明代","a":"杨爵","c":["需极乘时起，文明及早开。经猷小自预，功业大期来。", "气运机方动，人谋预可回。两肩刚骨上，□□□三才。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"写竹题寄华叔端","p":"","d":"明代","a":"王绂","c":["我昔寻君扣竹扉，醉中曾写竹间诗。别来几度空相忆，多在青灯听雨时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水调歌头","p":"","d":"近代","a":"俞律","c":["物我有深谛，六月梦花天。当年花国曾隐，一度学神仙。", "十万杨妃新浴，醉弄丰肌玉骨，拥我夕阳船。记得凌波步，尘外听珊珊。", "云是纸，风是笔，染田田。丹青难写，别后明月照无眠。", "依旧年华虚度，十载光阴何速，回首尽云烟。何日还归去，花里悟通圆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆江南","p":"","d":"当代","a":"魏新河","c":["都太晚，风雨忍相催。问影问声寻片玉，隔云隔水惜残梅。", "谁说一生陪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词 其四十九","p":"","d":"明代","a":"江源","c":["心绪纷纭懒出门，出门何处望金根。鹍弦欲拨无愁曲，只恐愁多更断魂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送袁景宗之荆渚宁觐","p":"","d":"宋代","a":"魏野","c":["荆渚北堂宁圣善，棠阴东阁别严君。", "雪村山馆思亲梦，二十馀宵两处分。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"训士吟 其四","p":"","d":"清代","a":"戴亨","c":["猗嗟此一生，生难尽慧识。幸不堕顽蠢，造物岂我啬。", "况藉古初人，阐微先我力。得每不践机，失亦难伪饰。", "用转欺慊机，慎哉勿自贼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠余德甫奉使两浙四首 其一","p":"","d":"明代","a":"宗臣","c":["天风匹马向西湖，明月千家醉白榆。莫上钓台听夜笛，霜华吹破客星孤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宜春再访芳公言公幽斋写怀叙事，因赋长言","p":"","d":"唐代","a":"郑谷","c":["入门长恐先师在，香印纱灯似昔年，涧路萦回斋处远，", "松堂虚豁讲声圆。顷为弟子曾同社，今忝星郎更契缘。", "顾渚一瓯春有味，中林话旧亦潸然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓","p":"","d":"清代","a":"弘历","c":["晓色侵罗幌，初晴景色和。轩墀饶润秀，书史足吟哦。", "竹里风兼爽，花间露渐多。畴咨勤问政，何以秩南讹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其一","p":"","d":"宋代","a":"梁安世","c":["更说此州异特事，寇公归后二苏来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古意","p":"","d":"明代","a":"李时行","c":["花落春愁暗，莺啼晓梦醒。柳丝长若许，难系别离情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"还过他里雾","p":"","d":"清代","a":"孙元衡","c":["林黑涧逾响，天青山更高。诸蕃能跽拜，前队肃弓刀。", "卧簟惟功狗，喧枝尽伯劳。不因程计日，待猎看风毛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九月五日具草酌同彦博审知成父集于普宁山半","p":"","d":"宋代","a":"赵蕃","c":["平生羞狗监，何啻失羊斟。", "与子风期尚，相要林壑深。", "分甘驹在谷，宁事鹤鸣阴。", "此日胡为乐，诗成改又吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"献寿戏作","p":"","d":"宋代","a":"苏轼","c":["终须跨个玉麒麟，方丈蓬莱走一巡。", "敢献些儿长寿物，蟠桃核里有双仁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"宋太宗","c":["二三千客里成事，七十四人中少年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小池观鱼","p":"","d":"宋代","a":"姜特立","c":["戏投饼饵方塘上，无限鱼儿翻翠浪。", "向来瓠瑟听遗音，今日梅山识清唱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"草屦","p":"","d":"宋代","a":"易士达","c":["崎岖只惯识羁情，足下忙穿子更轻。", "近世宦途如纸薄，当知险处不须行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九月八日桐川道中二绝 其二","p":"","d":"宋代","a":"岳珂","c":["依稀九日明朝是，三径情知不到家。随分秋光关节物，桐川道上看黄花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋","p":"","d":"当代","a":"陈忠平","c":["何独怜今夜，一年容易秋。雁都为过客，月只照离忧。", "珠露洗檐白，心潮到海休。清风扶薄醉，倚断小洋楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登封大酺歌四首","p":"","d":"唐代","a":"卢照邻","c":["明君封禅日重光，天子垂衣历数长。", "九州四海常无事，万岁千秋乐未央。", "日观仙云随凤辇，天门瑞雪照龙衣。", "繁弦绮席方终夜，妙舞清歌欢未归。", "翠凤逶迤登介丘，仙鹤裴回天上游。", "借问乾封何所乐，人皆寿命得千秋。", "千年圣主应昌期，万国淳风王化基。", "请比上古无为代，何如今日太平时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丁酉新正访疏影渝州并与喜英先生饮于楼船次无欲斋元玉","p":"","d":"当代","a":"邱登成","c":["筵开画船上，恰过月初三。杯酒催诗兴，江风助茗谈。", "水流山未醒，情转意微酣。灯火昨宵处，依稀见碧岚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中岳庙投龙简","p":"","d":"元代","a":"吴全节","c":["阳城天地中，坤灵奠神岳。积翠千层霄，元气远盘礴。", "降神生申甫，形势控伊洛。谽谺虎豹蹲，偃蹇蛟龙跃。", "猛士横戈矛，奇阵出帏幄。簇簇罗旌旗，巍巍耸台阁。", "玉镜为谁开，金匮为谁钥。远近列画图，周遭峙郛郭。", "万状不可名，起伏互连络。皇皇圣帝居，历代重封爵。", "老柏浮苍烟，古殿蚀丹雘。天朝混华夏，秩礼特优渥。", "皇庆二载春，宵旰轸民瘼。有旨醮长春，玉简命新琢。", "诏臣走登封，香币致虔恪。邃洞藏宝符，琼音降笙鹤。", "三呼今复闻，祥风度天乐。小臣奉明祀，三使陟云崿。", "箕山胜可家，颍水清可涿。遐想饮牛人，高风动寥廓。", "赐玦知何时，分我云半壑。歌诗勒嵩珉，用赞圣人作。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王承恩侍讲参政四川","p":"","d":"明代","a":"文徵明","c":["鸟道巇㠊万里赊，从臣分省向三巴。中朝声望云山重，内史文章锦水华。", "烂熳新恩苍玉节，依然旧署紫薇花。只应未忘论思地，翘首金銮北斗斜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"墨君十咏 其九 夜","p":"","d":"宋代","a":"王铚","c":["倚竹佳人生暮愁，那知情伴夜蝉幽。一山风月龙吟罢，声入江云袅袅秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天","p":"","d":"近代","a":"吴世昌","c":["暖日疏林照渌波，游人长见影婆娑。谁家种得痴情树，粒粒枝头醉欲酡。", "呼女伴，挽轻箩。相思共拾不嫌多。春风一夜吹红豆，遍地相思奈尔何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词三十三首","p":"","d":"宋代","a":"曹勋","c":["宽恤从来只陆沉，丁宁今始慰人心。", "圣情更欲民孚信，亲御云章下诏音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"紫瑞香三首","p":"","d":"宋代","a":"陈藻","c":["无数枝头簇簇葩，大枝直上细枝斜。", "商量开尽商量落，全要前花见后花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清源夫人赵氏挽词 其一","p":"","d":"宋代","a":"王十朋","c":["全节忠臣配，崇宁宰相家。哀能变国俗，贵不御铅华。", "学佛穷三昧，然松教五车。遗芳载彤管，名寿两俱遐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春暮","p":"","d":"清代","a":"王诒寿","c":["野桃无力点晴波，寒食清明次第过。酒价渐低春酿熟，笋船初到市声多。", "东风芳草人盘马，小雨杨花客渡河。却忆江南好时节，画桡衫影水如罗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄何叔毗礼部","p":"","d":"明代","a":"文徵明","c":["为爱君家好弟兄，列官同在凤凰城。迟迟宫漏薇垣静，浥浥垆香画省清。", "风雨夜堂联榻处，池塘春草看诗成。相逢相别还相忆，白发江湖无限情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵吕元钧给事嘉川驿来诗","p":"","d":"宋代","a":"李复","c":["相逢莫厌重留连，邂逅浮云只偶然。前日一樽穷乐事，今朝千里感流年。", "尘侵遗迹留漳水，风入高吟动蜀鞭。锦鲤往来出江浦，应传秀句满嘉川。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"季子守宅观音莲","p":"","d":"明代","a":"徐渭","c":["昔闻火里莲能长，今见莲从陆地栽。广叶祗冯圆性转，粗花全借法身开。", "丛摇宝鬘风中去，气绕梅檀雨后来。试问集观谁具眼，解将真见听飞埃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"一字百题示商君祥 其八十二 舞","p":"","d":"金朝","a":"李俊民","c":["野鹤闻琴态，孤鸾对镜妍。为君小垂手，无地可回旋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"行乞从化宿李某石峰堂因赠","p":"","d":"明代","a":"释今沼","c":["新堂筑几年，奇石复巍然。座客乐时满，架书经乱全。", "城阴篱落下，山色屋隅边。相对已如梦，况忆十年前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"劳山纪游百咏选七十九首 其五十六","p":"","d":"近代","a":"黄公渚","c":["独立云端见似人，頫看沧海几扬尘。幕云崮与凌烟崮，争及金刚不坏身。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观张中乐书大字","p":"","d":"宋代","a":"梅尧臣","c":["芝旭驰名世有孙，大书如晓过秋原。", "长松怪柏皆成炭，豫氏观傍不解吞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与邵莫二子游七真诸洞一首","p":"","d":"明代","a":"黄省曾","c":["驻马翠微中，山萝漾夕风。言探七子躅，因蹑五城宫。", "洞草徒看绿，丹炉巳罢红。飙轮不可见，吾欲母禽通。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日直秘阁","p":"","d":"宋代","a":"李至","c":["蓬阁清虚称野情，华阳巾稳葛衣轻。", "垂帘不见喧嚣事，尽日唯闻禽鸟声。", "小桧影中铺砚席，矮槐阴下著茶铛。", "却愁穷巷晚归去，尘土满街冲热行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百零二首 其十七","p":"","d":"宋代","a":"释绍昙","c":["横该竖抹，古路封苔。圣凡情尽，马腹驴胎。不用闭门防俗客，爱闲能有几人来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观物","p":"","d":"宋代","a":"林希逸","c":["天旋底背东西日，月正河平昼夜潮。空里华生空里灭，静中声起静中消。", "移舟远浦疑山走，汲水清溪觉岸摇。人世自迷颠倒见，达观何事不逍遥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢彭大夫惠寒山诗三首","p":"","d":"宋代","a":"曹勋","c":["平生为物役，年纪积渐老。", "不省这个意，老得越颠倒。", "自读二诗来，迷云扫空照。", "我为谢彭翁，且喜无烦恼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题苏庄洞神观楼","p":"","d":"元代","a":"王翰","c":["万叠青山百尺楼，倚栏空翠泼双眸。波澄碧簟铺沙际，霜重红绡剪树头。", "玉洞月明丹火冷，宝坛风细剑光流。平生作客多秋兴，便拟登临赋远游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"石湖十二咏 其九 楞伽塔","p":"","d":"元代","a":"郑元祐","c":["危峰耸浮屠，七级雕阑曲。影落湖波心，鱼龙骇常伏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古意","p":"","d":"明代","a":"詹同","c":["君家兰泽西，妾家兰泽东。兰泽多芳草，相去各春风。", "君今行陇右，妾思在闺中。天寒绣袂薄，泪下玉屏空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"禅人并化主写真求赞 其二三七","p":"","d":"宋代","a":"释正觉","c":["须发衰残，空山雪寒。眉目清淡，野水秋还。一念万年了尘劫，十方三世同正观。", "翡翠天晴而清虚廓彻，珊瑚海月而光焰波澜。现形说法应机感，笑指俱胝百草端。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百一十七首 其七十七","p":"","d":"宋代","a":"释绍昙","c":["雨足龙闲，年丰民乐。袖出刈禾镰，大地全收却。归来十二峰前，别甑炊香，明玑满钵。", "喂饱活衲僧，曲肱酣睡著。佛法身心烂似泥，哑，医无药。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别程女","p":"","d":"元代","a":"元好问","c":["芸斋淅淅掩霜寒，别酒青灯语夜阑。", "生女便知聊寄托，中年尤觉感悲欢。", "松间小草栽培稳，掌上明珠弃掷难。", "明日缑山东畔路，野夫怀抱若为宽？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄史君实 其一","p":"","d":"明代","a":"郑真","c":["月湖公子泮池深，老却平生富贵心。宝铗歌残星斗落，紫箫吹断凤鸾吟。", "秫香樽蚁杯频泛，烛剪钗虫夜向深。若幸广文归去早，午风花下定相寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次王得淦韵","p":"","d":"宋代","a":"陈著","c":["浴出矮檐阴，披襟小雨侵。", "坐凉三鼓漏，和梦一镫吟。", "自分死中活，谁知升与沈。", "明朝书局事，奔走岂初心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"悼具三","p":"","d":"明代","a":"释函是","c":["早年避乱投泉石，因病辞家渡海云。白社尚存居士笔，青山添作苾刍坟。", "泪泠松埠新霜露，梦绕萝龛旧见闻。借汝再来吾已老，不堪孤雁唳斜曛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"居厚弟和七十四吟再赋","p":"","d":"宋代","a":"刘克庄","c":["占断溪山不纪年，俗开谤道是呆仙。", "马迟甘殿他人后，棋劣常输敌手先。", "饥咬菜根美熊掌，穷烧柏子当龙涎。", "可怜陈窦无精识，欲以绳维大厦颠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆萝月（寓清平乐客盱江，秋夜鼓琴，思故山作）","p":"","d":"宋代","a":"张辑","c":["新凉窗户。闲对琴言语。弹到无人知得处。两袖五湖烟雨。", "坐中斗转参横。珠躔碎落瑶觥。忆著故山萝月，今宵应为谁明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"植灵寿木","p":"","d":"唐代","a":"柳宗元","c":["白华鉴寒水，怡我适野情。", "前趋问长老，重复欣嘉名。", "蹇连易衰朽，方刚谢经菅。", "敢期齿杖赐？聊且移孤茎。", "丛萼中竞秀，分房处舒英。", "柔条乍反植，劲节常对生。", "循玩足忘疲，稍觉步武轻。", "安能事翦伐，持用资徒行。"],"tags":["植物"],"z":"","y":"","s":"","k":"诗"},
  {"t":"禅人并化主写真求赞","p":"","d":"宋代","a":"释正觉","c":["老态垂垂，岁月浸欺。", "半头生白发，瘦骨裹黄皮。", "情闲用而活，句妙默而知。", "河阔斗寒云静夜，天无四壁风披披。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"由弯崎至罗汉门杂咏 其四","p":"","d":"清代","a":"郑兼才","c":["海外青山入版图，红毛遗迹属模糊。峰头雨暗怨鸯岭，有客来寻打鹿埔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"治宅诗","p":"","d":"南北朝","a":"谢朓","c":["结宇夕阴街，荒幽横九曲。迢递南川阳，迤逦西山足。", "辟馆临秋风，敞窗望寒旭。风碎池中荷，霜剪江南菉。", "既无东都金，且税东皋粟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答赵尉","p":"","d":"宋代","a":"陈宓","c":["亲友乡闾恨少逢，多因游宦得从容。", "他年傥过鸣珂里，只恐飞翰不许从。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"采采歌","p":"","d":"宋代","a":"胡仲弓","c":["朝采畹中兰，暮采篱下菊。", "采采复采采，终日不盈掬。", "为怜芳洁姿，忍受红尘触。", "采兰杀风味，采菊盈芬馥。", "落英固可飧，何发饮藜藿。", "秋香亦可纫，保如鸣佩玉。", "俾尔全其天，得志在岩谷。", "所以山中人，终身抱幽独。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"添春色","p":"","d":"宋代","a":"秦观","c":["唤起一声人悄。衾冷梦寒窗晓。瘴雨过，海棠晴，春色又添多少。社瓮酿成微笑。半缺癭瓢共舀。觉健倒，急投床，醉乡广大人间小。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同罗季能章成父张子直登樊城制胜楼","p":"","d":"宋代","a":"李曾伯","c":["避愁聊复上层楼，上到层楼转更愁。", "杳杳青烟榆夹塞，鳞鳞翠浪麦平畴。", "山连楚甸三千里，地隔中原四百州。", "立尽栏干夜领会，沧波渺处起沙鸥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"纪事 其四","p":"","d":"宋代","a":"文天祥","c":["百色无厌不可支，甘心卖国问为谁。豺狼尚畏忠臣在，相戒勿令丞相知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沙塞子（咏梅）","p":"","d":"宋代","a":"葛立方","c":["天生玉骨冰肌。瘦损也、知他为谁。□寒底、傲霜凌雪。", "不教春知。高楼横笛试轻吹。要一片、花飞酒卮。拚沈醉、帽帘斜插，折取南枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绍兴祀太社太稷十七首 太社位酌献用《嘉安》。春社太稷、土正、后稷通用。","p":"","d":"宋代","a":"郊庙朝会歌辞","c":["封土崇祀，有烈在民。千载不昧，福此人群。洗爵奠斝，有酒其芬。", "神具醉止，恺乐欣欣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郊庙歌辞。享龙池乐章。第二章","p":"","d":"唐代","a":"蔡孚","c":["帝宅王家大道边，神马龙龟涌圣泉。昔日昔时经此地，", "看来看去渐成川。歌台舞榭宜正月，柳岸梅洲胜往年。", "莫言波上春云少，只为从龙直上天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书房杂书","p":"","d":"宋代","a":"陆游","c":["敛版一何久，悬车已後时。", "狂酲醒始悔，穷独老方知。", "世外乾坤大，林间日月迟。", "犹须采药去，不媿鹿门期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题明秀楼 其二","p":"","d":"明代","a":"胡俨","c":["紫霞碧树绕沧洲，满目江山入画楼。想得楼中宾客散，携琴还载木兰舟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词 其十二","p":"","d":"宋代","a":"赵佶","c":["乐章依韵俯成编，欲听新词禁宇传。曲里字难相借问，随时切脚注花笺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"无题十月二作","p":"","d":"当代","a":"卢青山","c":["露老红鹃柳老烟。记曾两次过塘沿。而今应有啼衣鸟，自在风中向蟋眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"祠颜范二公","p":"","d":"宋代","a":"王十朋","c":["鄱江善政九贤人，文正文忠更绝伦。桃李旧邦千里爱，丹青遗像两朝臣。", "不同赤土祠刘阮，端胜睢阳庙远巡。安得神仙返魂药，九原唤起静边尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题洋菊四十四种 其二十八 海红莲","p":"","d":"清代","a":"弘历","c":["团毬簇稠叠，卷筒舒蓓蕾。韎韐殊赩然，原出大红海。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"顷尝梦至善生院赋诗一联己丑七月十三日因游","p":"","d":"宋代","a":"周必大","c":["门外千竿竹绕墙，清风终日注回廊。", "五年未续梦中梦，得得来追三伏凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵何符山人二首","p":"","d":"宋代","a":"陈造","c":["晓看明玑下网丝，物华俱属喜晴诗。", "一词不措重呈拙，七字鼎来富更奇。", "喜鹊啅人真作意，蜗牛屏迹似知时。", "湖山好处长谣去，拟赴苏堤胜日期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大江东去 美人","p":"","d":"元代","a":"王寂","c":["破瓜年纪，黛螺垂、双髻珍珠罗抹。娅?吴音娇滴滴，风里啼莺声怯。飞燕精神，惊鸿标致，初按梁州彻。舞裙微褪，汗香融透春雪。少陵词客多情，当年曾烂赏，湖州风月。自恨寻春来已暮，子满芳枝空结。湘佩轻抛，韩香偷许，空想凌波袜。章台杨柳，可堪容易攀折。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长街","p":"","d":"当代","a":"胡云飞","c":["长街无背景，存在无烙记。街中千万人，纷其生老死。", "各怀一玉匣，投赠于彼此。斯匣如太古，浑圆不可启。", "斯匣如太古，暗黑不可视。但见主人替，往来无穷已。", "辗转复辗转，迢递复迢递。", "我居在长街，我思在匣中。匣中何所有，或者谓时钟。", "或者谓面孔，或者本来空。路人皆不问，衣冠自从容。", "投之复报之，往来两匆匆。长街无背景，演出无始终。", "长街我所居，玉匣思所托。我思如秋花，寂然开且落。", "我思如流星，一瞬光灼灼。何用斯匣为？弃之如敝屩。", "虽弃终相随，风中影绰约。安得仙之人，赐我以玉钥。", "仙人不可见，追思亦不禁。匣中竟何有，或者竟本心。", "辗转复辗转，谁心在我襟？迢递复迢递，我心何处寻？", "路人皆不知，往来各骎骎。长街无背景，存在自消沉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"得覃韵","p":"","d":"明代","a":"李孙宸","c":["文酒经时事事谙，西山还共访名蓝。盟同泉石宁终负，歌到骊驹便不堪。", "谁以去天誇尺五，繇来赋芋总朝三。扶摇九万鹏程在，六月从君暂徙南。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"生查子","p":"","d":"现代","a":"顾随","c":["身如入定僧，心似随风草。", "心自甚时愁，身比年时老。", "空悲眼界高，敢怨人间小。", "越不爱人间，越觉人间好。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖上送家兄入都","p":"","d":"清代","a":"朱荃","c":["幽鸟唤春春又阑，六桥烟柳簇征鞍。客途再到悲欢异，樽酒相逢去住难。", "五夜鸡声惊昨梦，连朝花信破轻寒。停鞭不尽蝉联语，回首高城夕照残。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙 其四 四时闺词","p":"","d":"清代","a":"顾太清","c":["六出花飞冬日寒。金炉拨火炷沉檀。一杯清茗啜龙团。", "梅蕊迎风香细细，竹稍压雪叶攒攒。阿谁忍冻卷帘看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题半月岩","p":"","d":"宋代","a":"吴文震","c":["□灵通一窍，如月未全盈。", "外□山河界，中涵蚌蛤精。", "银潢斜□断，玉斧半修成。", "莫讶平分破，难亏半体明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三峡闻猿","p":"","d":"唐代","a":"贯休","c":["历历数声猿，寥寥渡白烟。应栖多月树，况是下霜天。", "万里客危坐，千山境悄然。更深仍不住，使我欲移船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送杨士宪之云南佥事","p":"","d":"明代","a":"杨士奇","c":["万里滇南候绣衣，炎州十月凛霜飞。丰城古剑神光动，一道澄清属有威。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自君之出矣八首 其八","p":"","d":"明代","a":"刘琏","c":["自君之出矣，芳香销玉体。思君如河冰，坚凝直到底。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"除夕四首 其三","p":"","d":"明代","a":"谢元汴","c":["今夕家园宴，慈亲杖履轻。弟兄别后梦，儿女岁时情。", "念我高楼上，辛勤白发生。小亭方筑就，编竹待而成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三山林教谕先生挽诗","p":"","d":"明代","a":"黄仲昭","c":["蚤际风云登月窟，旋承雨露下天除。棘闱多士推衡鉴，芹泮诸生仰范模。", "浮世功名归一梦，朝阳文彩见三雏。褒封况有双鸾诰，万丈龙光照故墟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶成三首 其二","p":"","d":"宋代","a":"邓肃","c":["梦破南窗袅水沉，卧看素壁挂瑶琴。丝丝细雨晚烟合，阁阁鸣蛙蔓草深。", "但得瓮边眠吏部，不妨跨下辱淮阴。何时楼上登晴景，一醉聊舒万里心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病题桐江","p":"","d":"宋代","a":"彭汝砺","c":["叹息医工拙，矜嗟旧疾牢。衰容虽冻雀，烈气尚惊涛。", "羁旅双尘鬓，尘埃一布袍。远乡滋味恶，空益梦魂劳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"主簿陈元矩署中畜鹅","p":"","d":"宋代","a":"赵公豫","c":["素羽称修洁，苍音听不禁。田间宜养育，官舍莫栖侵。", "博爱儒生量，矜全物性心。从今传韵事，谁谓擅山阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"家舅和前韵示余因再用韵奉寄","p":"","d":"明代","a":"邓雅","c":["南郊庙前溪水流，紫盖峰下梧桐秋。片云相隔不可会，两屩未閒何所求。", "荒城厌见豺虎乱，深谷喜同麋鹿游。吾舅安居莫叹息，杜陵多难留鄜州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莲","p":"","d":"清代","a":"弘历","c":["承晖扬素质，冒沼弄幽馨。朅对怀今昔，坐令空色形。", "展新芳意足，依旧晚桡停。堪以方清淑，非关比尹邢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三贞篇寄纳麟哈刺参政幕下僚友","p":"","d":"元代","a":"王逢","c":["梧西女陈氏，颜色绝胜玉。阿耶灯窗下，古传常暗读。", "义须嫁官人，麻枲心所足。兵麾忽东指，烽火蔓平陆。", "鱼鳖遭颠连，鸡狗同迫逐。猰貐哆其口，反噬机上肉。", "母子泣相誓，宁死不汝辱。春辉黯门楣，寒日照鬼录。", "皇天实鉴临，家庙为惨肃。髽妇亦在难，自判受命独。", "臂血溅贼衽，贼叹为敛缩。差差白刃间，伟节惊耳目。", "荒野云雪暮，缅想会深竹。水流风悲鸣，星迸万羽镞。", "回首陷没地，何限委沟渎。大参行当来，恤典具简椟。", "前湖百世祀，明妆俨车服。从以双素鸾，配享畴敢黩。", "孤蓬任漂转，馀齿寄草木。倡兹三贞篇，庶用矫浮俗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠林处士逋","p":"","d":"宋代","a":"潘阆","c":["云剪乌纱雾剪衣，存神养气语还稀。人人尽唤孙思邈，只恐身轻白日飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄杨高士","p":"","d":"宋代","a":"释慧远","c":["富有十年别，贫无一觉眠。", "好来同夜话，相共酌清泉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游慈云分韵得是字","p":"","d":"宋代","a":"陈著","c":["僧关可人心，况此晴色美。", "蹈藓滑路多，访菊香处是。", "引饮吞山光，清啸落松子。", "我有即事诗，就扫石壁纪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"衡岳感怀二首 其二","p":"","d":"明代","a":"胡直","c":["恭闻夏后圣，秉志切元元。洪波荡中土，隐若裂肺肝。", "不辞排决力，宁论胼胝艰。去家七八载，三过不入门。", "诚精格玄昊，金书下层峦。禹拜受此书，治水识其端。", "鞭挞蛟与螭，疏凿江与汉。江汉故汤汤，河淮无溢湍。", "九州一以平，四隩罄欢颜。上启重华帝，巡狩驻瑶幡。", "玄冕照林阿，韶韵播江潭。爰以上公秩，望兹南维尊。", "秩秩虞夏文，郁郁夔龙班。缅思此盛际，千岁不可攀。", "测知圣哲心，匪恣一身安。顾予道未至，愿言归山樊。", "山樊有故侣，终焉击壤欢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风入松","p":"","d":"宋代","a":"张鎡","c":["芳丛簇簇水滨生。勾起午风清。六花大似天边雪，又几时、雪有三层。明艳射回蜂翅，净香薰透蝉声。", "晚檐人共月同行。疏影动银屏。指尖轻捻都如玉，听画栏、高啭流莺。道是花枝比得，不成花也多情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"河满子 闻雁","p":"","d":"清代","a":"易顺鼎","c":["太液何时雪尽，洞庭此日波荒。水碧沙明苔两岸，湖天古怨微茫。", "枫叶蓼花多处，勾留半在红乡。", "一路冲开雨密，数声拖得秋长。只有渔翁浑不管，中流自起鸣榔。", "几处高楼怕听，谁教错住潇湘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄闾卫之同府二首 其二","p":"","d":"明代","a":"边贡","c":["江上逢君感昔年，往来相见陆陵前。那知宦迹如萍梗，犹得相依一水边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登多景楼分楼高天一握为韵得一字楼非旧址惟东面可眺三隅暗甚时方改作榜称米元章书盖伪也语寺僧当易之","p":"","d":"宋代","a":"周孚","c":["往时百仞山，丹楼丽朝日。江天富佳致，收揽不遗一。", "匆匆熙丰事，电往那可诘。故基谁为徙，胜槩从此失。", "如窥一面网，反随三凌室。幽怀郁尘雾，老眼暗髹漆。", "虽云一牛鸣，每至辄悔出。使君改筑意，正欲名称实。", "丁丁斤斧功，趁此玄月毕。扁榜照华榱，仍须此翁笔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李孝先之蕲州扶其先大夫相如先生旅榇归粤三首 其三","p":"","d":"明代","a":"陈恭尹","c":["惜汝风尘早，艰虞及弱龄。诵诗悲陟岵，闻礼梦趋庭。", "剥极终来复，蓝深或出青。蕲黄张楚地，早愿返松扃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再赠月蓬道人六言二首 其一","p":"","d":"宋代","a":"刘克庄","c":["谢公早有远志，陶子晚知昨非。帝允我乞骸疏，汝见吾衡气机。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉蝴蝶","p":"","d":"明代","a":"夏完淳","c":["春日恼人花鸟，香车宝马，陌上成行。相思满地，芳草绿到西江。", "旧衣香。留他荀令，新曲误，顾了周郎。枉思量。金壶滴博，银箭丁当。", "茫茫。玉人何处，寻伊消息，瘦了容光。只剩些些，影儿作对梦儿双。", "恨多情、雁传银字，愁不语、花落纱窗。对斜阳。珠帘卷起，又是昏黄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"文徵仲画老子见赠旧寄观音像并此奉谢","p":"","d":"明代","a":"薛蕙","c":["本家楚濑乡，远师周柱史。流沙竟长往，谷神应不死。", "真源古县近西原，祠宇荒凉旧宅存。不见犹龙写生色，秪同摸象解空言。", "衡山先生今顾陆，赠我真人真一幅。天机渊默藏根柢，日角分明辨眉目。", "先生高士非画师，一纸千金难易之。四方求者苦不得，我未往求先见遗。", "往年曾寄圆通像，髣髴白衣来海上。今者挥毫图伯阳，恍惚青牛归故乡。", "老夫家居贫转剧，偶然富与公侯敌。箪瓢匮乏无斗储，箧椟缄縢有双璧。", "平生嗜好释与仙，幸遭同病还相怜。已将彩绘作佛事，更拟形似传灵筌。", "学通二氏我何有，画备六法谁能先。不惭俚调酬妙品，往来聊结三生缘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宝月台夜坐","p":"","d":"明代","a":"谭胜祖","c":["一楼岩畔月，竹石倚相将。天地真容懒，湖山恕酒狂。", "淡云随树影，薄露出花光。偶尔逢僧话，茶烟起竹房。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽龙图待制徐良能墓","p":"","d":"宋代","a":"范端臣","c":["少日蜚声竦白袍，暮年策足上青霄。", "功名略已追前辈，事业真堪托后凋。", "谏草半焚烟寂寂，琐窗一梦夜寥寥。", "古塘原上谁行路，只有哀笳引葬箫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送危教谕之桐乡","p":"","d":"明代","a":"徐溥","c":["寒毡元不较勋阶，吾道东南育俊才。晏岁关河劳跋涉，春风桃李费栽培。", "五经洞彻文光夐，万骑纵横笔阵开。最是诸生承教益，短亭衰柳惜馀杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟古诗二十首 其十三 拟燕赵多佳人","p":"","d":"清代","a":"弘历","c":["燕姝宁台舞，赵女邯郸步。阎易美服饰，曼睩工盼顾。", "不丰亦不约，宜喜复宜怒。古来巳称绝，汉武寄馀慕。", "当户理瑶琴，能谱相如赋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送刘明远客和州","p":"","d":"宋代","a":"徐玑","c":["十载知心友，文才尔独兼。", "病谙孤寐乐，贫识茹蔬甜。", "冬暖梅花早，年丰酒价廉。", "不愁无远信，佳句日应添。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄友","p":"","d":"明代","a":"史鉴","c":["与君倾盖二毛初，别后无由数寄书。江上无人问消息，红庄随马射游鱼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重赴京师留别山中亲友","p":"","d":"明代","a":"李英","c":["结束事行役，扁舟欲问津。祇因游侠去，不为住山贫。", "飘泊凭孤剑，驱驰愧此身。别君多慷慨，相忆白纶巾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪叹二绝","p":"","d":"宋代","a":"洪咨夔","c":["唐时三月十八雪，况复今年多一旬。", "万紫千红浑过尽，荼蘼满架与争春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次郭羲仲韵柬玉山人","p":"","d":"明代","a":"张师贤","c":["故人一隔红云岛，相见银屏七夕前。", "花近小山当鹤广，溪深嘉树覆书船。", "参差清吹流银汉，餮殄文彝散玉烟。", "更拟此君亭子上，醉欹纱帽会群贤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"盛别驾还自叙州","p":"","d":"明代","a":"邵宝","c":["蜀道归与鬓未皤，叙州功比汉州多。金鱼初拜明廷赐，彤管还收野老歌。", "嘉客可人来只尺，大夫能赋兴如何。相逢且问东皋子，泽被横江尚有波。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"一萼红五首 其四 桃花夫人庙","p":"","d":"清代","a":"史承谦","c":["楚江边。旧苔痕玉座，灵迹自何年？香冷虚坛，尘生宝靥，千秋难释烦冤。", "指芳丛、飘残清泪，为一生、颜色误蝉娟。恩怨前期，兴亡闲梦，回首凄然。", "似此伤心能几？叹诗人一例，轻薄流传。雨飒云昏，无言有恨，凭栏罢鼓神弦。", "更休题、章台何处，伴湘波、花木暗啼鹃。惆怅明珠翠羽，断础荒烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"旅次朔方 / 渡桑干","p":"","d":"唐代","a":"刘皂","c":["客舍并州已十霜，归心日夜忆咸阳。", "无端更渡桑干水，却望并州是故乡。"],"tags":["思乡"],"z":"旅：旅行。次：临时住宿。朔方：古都名，自西汉始建，至唐代，辖区多变，治所不一。桑干河以北，属朔方地区。\n舍：居住。并州：即今太原一带。十霜：一年一霜，故称十年为“十霜”。\n咸阳：陕西咸阳是作者故乡。\n无端：没有缘由，不知为什么。桑乾水：即桑干河，源出西北部管涔山，向东北流入河北官厅水库。相传，在每年桑椹成熟时干涸，故有此名。","y":"离开家乡后客宿在并州这个地方已经有十年，我回归的心日日夜夜在思念着故乡咸阳。\n当初为了博取功名图谋出路，千里迢迢渡过桑乾河，现在并州已经成了我的第二家乡。","s":"在许多诗集中，这首诗都归在贾岛名下，其实是错误的。因为贾岛是范阳（今北京市大兴县）人，不是咸阳（今陕西省咸阳市）人，而在贾岛自己的作品以及有关这位诗人生平的文献中，从无他在并州作客十年的记载。又此诗风格沉郁，与贾诗之以清奇僻苦见长者很不相类。《元和御览诗集》认为它出于贞元间诗人刘皂之手。虽然今天对刘皂的生平也不详知，但元和与贞元时代相接，《元和御览诗集》的记载应当是可信的。因此定其为刘作。\n\n  此诗题目，或作《渡桑乾》，或作《旅次朔方》。前者无须说明，后者却要解释一下。朔方始见《尚书·尧典》，即北方。但同时又是一个地名，始见《诗经。小雅。出车》。西汉置朔方刺史部（当今内蒙古自治区及陕西省的一部分，所辖有朔方郡），与并州刺史部（当今山西省）相邻。桑乾河并不流经朔方刺史部或朔方郡，所以和朔方之地无关。并州在唐时是河东道，桑乾河由东北而西南，流经河东道北部，横贯蔚州北部，云、朔等州南部。这些州，当今雁北地区。由此可见，诗题朔方，乃系泛称，用法和曹植《送应氏》“我友之朔方，亲昵并集送”一样。而刘皂客舍十年之并州，具体地说，乃是并州北部桑乾河以北之地。\n\n  诗的前半写久客并州的思乡之情。十年是一个很久的时间，十年积累起的乡愁，对于旅人来说，显然是一个沉重的负担。所以每天每夜，无时无刻不想回去。无名氏《杂诗》云：“浙江轻浪去悠悠，望海楼吹望海愁。莫怪乡心随魄断，十年为客在他州。”虽地理上有西北与东南之异，但情绪相同，可以互证。后半写久客回乡的中途所感。诗人由山西北部（并州、朔方）返回咸阳，取道桑乾流域。无端，即没来由。更渡，即再渡。这“无端更渡”四字，乃是关键，要细细体会。十年以前，初渡桑乾，远赴并州，是为的什么呢？诗中没有说。而十年以后，更渡桑乾，回到家乡，又是为的什么呢？诗中说了，说是没来由，也就是自己也弄不清楚是怎么一回事。果真如此吗？不过是极其含蓄地流露出当初为了博取功名，图谋出路，只好千里迢迢，跑到并州作客，而十年过去，一事无成，终于仍然不得不返回咸阳家乡这种极其抑郁难堪之情罢了。但是，出乎诗人意外的是，过去只感到十年的怀乡之情，对于自己来说，是一个沉重的负担，而万万没有想到，由于在并州住了十年，在这久客之中，又不知不觉地对并州也同样有了感情。事实上，它已经成为诗人心中第二故乡，所以当再渡桑乾，而回头望着东边愈去愈远的并州的时候，另外一种思乡情绪，即怀念并州的情绪，竟然出人意外地、强烈地涌上心头，从而形成了另外一个沉重的负担。前一矛盾本来似乎是惟一的，而“无端更渡”以后，后一矛盾就突了出来。这时，作者和读者才同样感到，“忆咸阳”不仅不是唯一的矛盾，而且“忆咸阳”和“望并州”在作者心里，究竟哪一边更有分量，也难于断言了。以空间上的并州与咸阳，和时间上的过去与将来交织在一处，而又以现在桑乾河畔中途所感穿插其中，互相映衬，宛转关情，表达了诗人心中对故乡的怀念。","k":"诗"},
  {"t":"响水关","p":"","d":"明代","a":"皇甫汸","c":["飞泉来断壑，声咽不堪流。何以函关客，遥心寄陇头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和赵季行用兰花韵三首 其一","p":"","d":"宋代","a":"刘宰","c":["破除百卉发孤芳，造化工夫有抑扬。平易堂中无个事，一枝相对吐清香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"胡元之提刑寺丞迂涂相过宠示二诗次韵为谢兼","p":"","d":"宋代","a":"周必大","c":["惠政郡州楷，清名万口传。", "南交需按察，北阙正详延。", "契分元重复，封疆互接连。", "劳归知有日，还伫楚江边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜雨不寐","p":"","d":"宋代","a":"杨万里","c":["雨急点不疏，瓦乾声可数。", "滴破江湖梦，合眼无後补。", "更长酒力短，睡甜诗思苦。", "已自不成眠，如何更遭许。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感遇 其三","p":"","d":"近代","a":"佟绍弼","c":["死去馀何憾，生还各有思。固应离可念，未觉遇俱迟。", "回首空梁换，重澜古井悲。转怜来日永，不必怨当时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"放夜","p":"","d":"宋代","a":"方回","c":["深夜楼前笑语哗，禁街钟鼓暂停挝。冶游谑浪非吾事，富足欢娱有几家。", "春酒可能融鬓雪，书灯独自照梅花。黄柑犹见升平物，四十年前客永嘉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄内弟赵叔平","p":"","d":"明代","a":"王绂","c":["别来不觉又秋风，历想君家在眼中。稚子情娇初学语，慈亲年老近加聋。", "新居每对千竿竹，先陇应添几尺松。世业喜闻能复旧，休将百万一枭空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感事 其二","p":"","d":"近代","a":"陈顺彬","c":["去就机宜本未谙，操刀制锦又何惭。群中半是依阿态，局外偏持慷慨谈。", "莫笑驽骀誇冀北，也随鸡犬到淮南。翻空多少疑团事，解作黄粱梦正酣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"紫阳真人歌","p":"","d":"唐代","a":"卢象","c":["君不见先生耳鼻有仙骨，自号狂生中有物。金华侍讲三十年，儿戏公卿与簪笏。", "青门抗行谢客儿，健笔连羁王献之。长安素绢书欲遍，主人爱惜常保持。", "每叹二疏不足道，复言四皓常枯槁。去年寝疾弥数旬，神鬼盈庭谋一老。", "长男泣血求司命，少女颦眉诵《灵宝》。还如简子复归来，更与洪崖同寿考。", "上书北阙言授箓。税驾东州愿修道。初闻行路犹未信，果达吾君谓之好。", "山阴旧宅作仙坛，湖上闲田种芝草。镜湖之水含杳冥，会稽仙洞多精灵。", "须乘赤鲤游沧海，当以群鹅写道经。皇恩赠诗四十字，明主赐金三十镒。", "供帐倾朝一送归，双童驷马从兹出。回看紫绶若轻尘，远别青门嗟故人。", "鸳鹭差池攀羽盖，虹霓夭矫翊车轮。田田列侍浮丘伯，曾子荣过朱买臣。", "余高若是有先觉，灭迹归根从大朴。千载悠悠等令威，十洲漫漫思方朔。", "归去来，青牛顿足少迟回。忽然云雾不相见，唯有飘飘香气来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄俞君任府判","p":"送严上舍并寄诸公十首","d":"宋代","a":"陈造","c":["忆访俞夫子，频烦挽袖留。", "酒边无俗物，尘外有高楼。", "未醉催歌扇，言归听漏筹。", "此欢谁与继，怊帐岁时遒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"桑乾岭","p":"","d":"元代","a":"陈孚","c":["昔闻桑乾名，今日登桑乾。桑乾是否不必问，但觉两耳天风寒。", "大峰小峰屹相向，空际谽谺一千丈。燕云回首夕阳间，长川历历平于掌。", "人家如蛎粘石壁，白土堆檐高半尺。门外毡车风雨来，平地轰轰惊霹雳。", "汉唐百战场，绿草今满碛。野夫耕田间，犹有旧铁戟。", "道傍谁欤三叹息，古袍古帽江南客。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古三十三首 其二十六","p":"","d":"宋代","a":"释师观","c":["堕落眉须不得塔，三文使尽见分疏。无端大岭重饶舌，数丈龟毛举世无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"好事近 素描","p":"","d":"当代","a":"黄绮","c":["日暖奈何春，村外横山亦惰。阡陌往来都识，有亲朋几个。", "白鸥不起占池塘，打水儿童裸。正是肌肤如乳，惹柳丝缠裹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"监郡吴殿丞惠以笔墨建茶各吟一绝谢之 茶","p":"","d":"宋代","a":"林逋","c":["石辗轻飞瑟瑟尘，乳花烹出建溪春。世间绝品人难识，閒对茶经忆古人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忧阕诣台先寄献臣天休二学士","p":"","d":"宋代","a":"宋庠","c":["去国三年恨，还台九死馀。凄凉曾釜粟，感咽晏楹书。", "鲋勺怀穷辙，鸡栖整故车。惟当亲益友，叙阔费涟如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天辰","p":"","d":"宋代","a":"欧阳修","c":["天形如车轮，昼夜常不息。", "三辰随出没，曾不差分刻。", "北辰居其所，帝座严尊极。", "众星拱而环，大小各有职。", "不动以临之，任德不任力。", "天辰主下土，万物由生殖。", "一动与一静，同功而异域。", "惟王知法此，所以治万国。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"端石砚","p":"","d":"宋代","a":"李纲","c":["端溪出砚材，最贵下岩石。珍物乃卵生，孕此马肝色。", "世传鸲鹆眼，通透盖其脉。颇同阮步兵，见客作青白。", "我来岩中游，幽探偶有获。温然一片玉，秀润满书宅。", "断成蛟龙池，涩滑宜笔墨。当观管城翁，沐发散简策。", "嗟余好陶泓，收拾积圭璧。得此馀可忘，一生能几屐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山庄杂兴十首 其四","p":"","d":"明代","a":"王廷陈","c":["计拙堪时弃，谋生托野人。莺花无约束，木石有比邻。", "溪上思龙蛰，林间学鸟伸。逢人无一面，语契即情亲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿整庵罗太宰先生八十诗 其三","p":"","d":"明代","a":"尹台","c":["周道中陵夷，奇邪互哓诟。狭步窘周行，曲蹊争躏蹂。", "仲尼振微言，百家废荒谬。浸淫拂朱翟，轲书劳堤救。", "嬴秦溃土崩，汉氏承蚁漏。梵语译流沙，倏焉惑群瞀。", "净智启高禅，妄儒私牖窦。慧悟述心性，训言遭掩糅。", "伟欤困知辨，攘斥功何厚。谁哉挹北斗，酌公千龄寿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读史杂咏十首 其四","p":"","d":"清代","a":"王士元","c":["少岁读诗书，齿斤齿斤恣诋訾。续经颇怪文中子，论易颇轻王辅嗣。", "两人死时犹少年，著述煌煌已如是。男儿一事无成身已老，试问何者可人意。", "古之人，勿轻议。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"示张仲原秀才二首 其一","p":"","d":"宋代","a":"晁补之","c":["去年钜野张狂澜，黄河水不到鱼山。焦城有屋仲子筑，它日能来相往还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送张子公","p":"","d":"宋代","a":"吕陶","c":["康定用兵日，府谷尤孤危。属当治安久，多事尽废隳。", "三面枕贼境，平易如通逵。重城辄议葺，浮论多背驰。", "贤哉光禄公，定虑先本基。百堵大兴作，据险成藩篱。", "城完贼已至，善守莫敢窥。泉源众所汲，公为亲解围。", "兵势弱不振，公能屡张威。贼退城可处，生聚始有归。", "于今三十年，功勋书鼎彝。边人每记忆，言者感涕挥。", "近日羽书至，讨伐加羌夷。庙算出帷幄，王师整熊罴。", "壮夫思报国，志士窃忧时。寒日朝惨淡，凄风夜号悲。", "昔人何卓荦，往事可追维。夫君实贤嗣，仕宦图奋飞。", "家声贵不坠，儒学当有为。归欤自磨砺，门阀增光辉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别赵子（赵子名德，潮州人）","p":"","d":"唐代","a":"韩愈","c":["我迁于揭阳，君先揭阳居。揭阳去京华，其里万有馀。", "不谓小郭中，有子可与娱。心平而行高，两通诗与书。", "婆娑海水南，簸弄明月珠。及我迁宜春，意欲携以俱。", "摆头笑且言，我岂不足欤。又奚为于北，往来以纷如。", "海中诸山中，幽子颇不无。相期风涛观，已久不可渝。", "又尝疑龙虾，果谁雄牙须。蚌蠃鱼鳖虫，瞿瞿以狙狙。", "识一已忘十，大同细自殊。欲一穷究之，时岁屡谢除。", "今子南且北，岂非亦有图。人心未尝同，不可一理区。", "宜各从所务，未用相贤愚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"月当厅","p":"","d":"宋代","a":"史达祖","c":["白璧旧带秦城梦，因谁拜下，杨柳楼心。正是夜分，鱼钥不动香深。", "时有露萤自照，占风裳、可喜影麸金。坐来久，都将凉意，尽付沈吟。", "残云事绪无人舍，恨匆匆、药娥归去难寻。缀取雾窗，会唱几拍清音。", "犹有老来印愁处，冷光应念雪翻簪。空独对、西风紧，弄一片桐阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"塞翁吟（黄园感事）","p":"","d":"宋代","a":"赵文","c":["又海棠开後，楼上倍觉春寒。绿叶润，雨初乾。爱远树团团。当时胜买名花种，那信付与谁看。十载事，土花漫。但青得阑干。", "悲欢。思人世、真如一梦，留不住、城头日残。看眼底、西湖过了，又还见、赵舞燕歌，抹粉涂丹。凭君更酌，後日重来，直是睛难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和杜中书九日","p":"","d":"宋代","a":"史浩","c":["佳人通夕赏重阳，醉尽楼边白玉缸。莫遣飞霜到丛菊，恐惊宿蝶去双双。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寓宝相有作","p":"","d":"宋代","a":"陆游","c":["扫地镜面清，烧香云气润。", "道人敬爱客，危坐目不瞬。", "童子髡两髦，经襌亦精进。", "我来愿同龛，欢喜无少吝。", "临堂坐夜分，佛灯看堕烬。", "清晨爽如秋，摄衣相问讯。", "道在氛埃表，此语其殆信。", "永愧小阮高，超然弃须鬓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和诸庵花光十梅颂","p":"","d":"宋代","a":"王柏","c":["推出突栾本相，雨肥叶底清黄。", "熟后何曾酸涩，舌根自不寻常。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病起二首","p":"","d":"宋代","a":"陈造","c":["即病偷闲却自怡，坐凭竹几独多时。", "铜炉烟畔熏风度，药臼声中昼漏迟。", "政自腐肠严酒戒，不应了事悔儿痴。", "净名文惠谁优劣，为问沾沾造化儿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"阎太守复任西安","p":"","d":"明代","a":"顾清","c":["好去西安守，还乘五马车。封疆参井旧，民物汉唐馀。", "会府人咸喜，铨曹最已书。儿童候公久，归驾莫纾徐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈","p":"","d":"宋代","a":"释景元","c":["有时候，有时喜，", "有时观音面，有时夜叉觜。", "或现鼠尾龙头，或现鼠头龙尾。", "偏要检非，不要检是。", "是金不博金，是水不博水。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病起谩书","p":"","d":"明代","a":"翟德方","c":["平生愿望出流尘，一病奄奄困此身。三十始成从政事，两恩俱未报君亲。", "已知得失非由我，始信乾坤不负人。馈药时来拜康子，病根拔去满胸春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新晴行郪水上与涪江相近","p":"","d":"宋代","a":"范成大","c":["涂泥初乾雨不落，日色未出暑光薄。畏途得晴天复凉，真是腰钱更骑鹤。", "浑浑郪水流未平，悄悄涪江如镜清。过尽江沙穿麦垄，忽有青蜩扶叶鸣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戏题江心寺僧房壁","p":"","d":"宋代","a":"陆游","c":["史君千骑驻霜天，主簿孤舟冷不眠。", "也与史君同快意，卧听鼓角大江边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汝忠宅待月同望之","p":"","d":"明代","a":"何景明","c":["空堂浊酒三人醉，万里清光迥未开。深夜西邻还鼓吹，碧天东望有楼台。", "虚疑星汉城边照，实怕风云海上来。坐对孤灯各愁思，九关哀角更相催。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"壬午秋事六章 其三 窥天","p":"","d":"当代","a":"添雪斋","c":["暗色秋深由梦说，窥天之事我之拙。结风偃息或为哀，明日萍浮甚于决。", "四野从来阴曀盈，微光只向虚空缀。听然而笑处无言，憀栗千年韶乐彻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和子厚弟九日登魏文振亭园七首","p":"","d":"宋代","a":"王之道","c":["雨余东北望银屏，一带寒山映骨清。", "谁道西风能换物，染红枫树亦多情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 贺友新婚","p":"","d":"明代","a":"沈家恒","c":["莫道好春无处讨，岭上琼花，开向金闺早。酒醒香浓天未晓，一丸璧月窥窗悄。", "初整晨妆眉样巧，笑问檀奴，秀色餐多少。更喜今年春色好，阶前渐绿宜男草。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"立春寄梅坛梅逸老","p":"","d":"宋代","a":"范太中","c":["仕路蹉跎又见春，区区深厌走红尘。", "未能解脱无穷事，长忆逍遥自在人。", "瓦缶汲泉朝灌药，羽衣蒙露夜朝真。", "洒然物外清虚境，呼吸淳元养气神。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"月季花","p":"","d":"宋代","a":"董嗣杲","c":["谢了还开肯悟空，一年三十六旬中。", "相看谁有长春艳，莫道花无百日红。", "酡脸倚娇承舞雪，瘦枝扶力借柔风。", "四时常吐芳姿媚，人老那能与此同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"兰蕙曲 其三","p":"","d":"明代","a":"屈大均","c":["为蕙不为兰，是侬甘自贱。祗恐花虽多，馨香有时变。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"腊月十七夜月同峻伯助甫席上赋 其二 得上字","p":"","d":"明代","a":"宗臣","c":["西风裂天荒，银河翻巨浪。残月东海头，至今不敢上。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅州喜晤梁辑五光禄 其三","p":"","d":"清代","a":"丘逢甲","c":["一笑全输此局棋，神州苍莽欲何之？虬髯红拂无消息，身愧三原李药师。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过武昌","p":"","d":"清代","a":"李敬","c":["四时常不极，一棹况无涯。击汰天疑路，停桡水是家。", "危洲行处直，远郭望中斜。沙势衔山影，波光荡日华。", "芦明空岸雪，叶乱晚陂霞。稍辨武昌树，初飞梦泽鸦。", "客愁增湍驶，楚色满蒹葭。欲访河干叟，林端见古槎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东湖","p":"","d":"宋代","a":"陶弼","c":["宁越佳山水，东湖带郡城。", "月天高寺影，春雨一桥声。", "石上青蒲合，沙中白鸟横。", "天涯睚寥落，独往若为情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九月二日登高","p":"","d":"明代","a":"王鏊","c":["重阳未到便登高，万里天风触锦袍。山色湖光兼雨暝，诗怀酒思入秋豪。", "丹砂漫贮千年药，白雪先尝九月糕。北雁联翩音信杳，怀人无语首频搔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鲍山","p":"","d":"清代","a":"缪沅","c":["鲍山山色如眉绿，螺黛挽烟青簇簇。洞中闻有丫髻童，手把铜盂挹银瀑。", "金仙真诰落荒厓，猛虎道旁时慑伏。五色肉芝供客啖，驻景无劳更辟谷。", "朅来山下悄无人，间凭一杖桃枝竹。不逢羽客佩方符，但见归农驾短犊。", "山中居人留我住，地垆火暖新篘熟。我懒寻仙思采隐，径来就汝山斋宿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"独游","p":"","d":"唐代","a":"王昌龄","c":["林卧情每閒，独游景常晏。时从灞陵下，垂钓往南涧。", "手携双鲤鱼，目送千里雁。悟彼飞有适，知此罹忧患。", "放之清冷泉，因得省疏慢。永怀青岑客，回首白云间。", "神超物无违，岂系名与宦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄中书洪益中梦菊先生四首 其三","p":"","d":"明代","a":"曹义","c":["望入天台客路长，江云野树思茫茫。别来每叹光阴速，屈指于今巳十霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同胡原仲吴公路游清湍亭赋诗得流字","p":"","d":"宋代","a":"刘子翚","c":["出山曾几时，桂露飒已秋。", "兴来任两屐，散此默默忧。", "岚光近仍灭，鸟语静忽流。", "新亭迥临危，急润循岩陬。", "上有独树荫，下有鸣湍幽。", "长飙一振荡，俯仰闻飕飕。", "平生尘累心，净尽迥此游。", "徘徊啸咏发，瞻眺穷林丘。", "天寒云已归，山好客自留，", "悠然百不知，日月过则休。", "人生乐在我，何必遂所求。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏徐氏竹溪之景八首 其七 石坞潭","p":"","d":"元代","a":"许有壬","c":["郿坞金多竟不存，清坚输与老云根。潭中鳣鲔知多少，已有飞腾过禹门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"余秋初离庭闱冬至犹未得归夜读宛丘先生秋日忆家诗辄次韵以述旅怀","p":"","d":"宋代","a":"虞俦","c":["屈指西风阅岁华，半年行役苦思家。綵衣归去亲闱好，画角吹残客梦赊。", "病里中秋慵见月，醉中九日强簪花。朅来又过书云候，节物催人一可嗟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"念奴娇 其二 题叶癯仙明府翠交阁二调","p":"","d":"清代","a":"曹尔堪","c":["百城民社，却等闲抛去，故园归早。旧识黄莺双白鹭，重赴主人林岛。", "活水拖蓝，修林染碧，托出银蟾皎。蛮姬捧砚，两弯眉如扫。", "频向槛外澄观，伍塘帆远，只比寒鸦小。麦浪交风闻雉雊，北郭青青未了。", "十万兵藏，五千轻授，丙夜凭搜讨。渔歌唱和，一场春梦方晓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再赋 其一","p":"","d":"宋代","a":"李正民","c":["寒威逗晓入帘栊，乱雨天花帝释宫。皓皓易污休拥彗，纷纷何似祗从风。", "能文谁复延枚叟，乘兴真宜访戴公。老去映书无眼力，夜阑惟喜月当空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花铺","p":"","d":"明代","a":"郭登","c":["绿树冬深不怕霜，怪来风上说南方。", "人经蛮寨愁蛇蛊，客聚盘江趁虎场。", "翠黛插云山似戟，潢流蒸气水如汤。", "王师到处沾恩泽，甘雨随车洗瘴乡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙","p":"","d":"宋代","a":"王采","c":["珠箔随檐一桁垂。绣屏遮枕四边移。春归人懒日迟迟。", "旧事只将云入梦，新欢重借月为期。晚来花动隔墙枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望大梅欲回雪窦路险而止口占示同行","p":"","d":"宋代","a":"王铚","c":["起晓寻幽意气豪，冥冥重雾溼征袍。", "天扶宝势千山拱，海助寒声万籁高。", "休数兴衰两蜗角，从来忧乐一鸿毛。", "了知终老林泉是，渡水穿云久亦劳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"食鱠","p":"","d":"宋代","a":"李处权","c":["设网机关密，磨刀意气麄。", "令人思洛鲤，愧客问江鲈。", "豆麴偏相与，橙虀未可无。", "相从频莫厌，乘兴不烦呼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郑德予同游桃花山次韵 其一","p":"","d":"宋代","a":"朱槔","c":["江村卜筑路斜斜，模写癯仙四壁家。闻道读书忘肉味，不缘避世宿桃花。", "青山自作千年调，白眼空惊一望赊。欲买鸡豚投近社，烟蓑雨笠寄生涯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小剑山","p":"","d":"近代","a":"陈湋","c":["磨刀割云去，屏风张镜奁。砚头九华秀，剑外一峰尖。", "苦李龙飞耳，香枫鬼有髯。奇情画不到，只许达摩潜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有感","p":"","d":"清代","a":"刘汝藻","c":["身世茫茫万事非，歌残黄鹄泪频挥。休题旧恨添眉皱，莫放新愁减带围。", "荒院小猧迎客吠，空仓饥雀避人飞。韶光瞥眼春如梦，怕检箱中金缕衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋江","p":"","d":"宋代","a":"释道潜","c":["赤叶枫林落酒旗，白沙洲渚夕阳微。数声柔橹苍茫外，何处江村人夜归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"越州歌","p":"","d":"宋代","a":"汪元量","c":["师相平章误我朝，千秋万古恨难消。", "萧墙祸起非今日，不赏军功在断桥！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"太上皇后阁","p":"端午帖子","d":"宋代","a":"周必大","c":["午节人传百药良，三千玉女斗群芳。", "销忧萱草名空美，长乐宫中乐更长。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留别友人吴春洲六首 其六","p":"","d":"明代","a":"孙承恩","c":["把臂相看惊白头，乡心日逐水东流。故园松竹闻无恙，迟子相归续旧游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和赵国兴访萧氏草堂","p":"","d":"宋代","a":"陈文蔚","c":["四野山围面面屏，何人结屋趣方成。", "好风吹过半湖碧，白鸟飞边一点明。", "乘举半春携酒约，隔山遥夜读书声。", "买邻为爱茅斋近，试倩诗人状此情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋帖子词十叠前韵 其一","p":"","d":"清代","a":"弘历","c":["创成帖子值几閒，九度吟情瞥眼删。今夕又逢清籞里，可孤宝月上屏山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刘山驿","p":"","d":"元代","a":"贡师泰","c":["开窗坐看千峰顶，对酒还思万里程。飞雨远随松子落，湿云近向树头生。", "正愁绝壁乌鸢背，忽听半空鸡犬声。安得身骑辽海鹤，遍游八极醉吹笙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汴中元夕五首 其二","p":"","d":"明代","a":"李梦阳","c":["玉馆朱城柳陌斜，宋京灯月散烟花。门外香车若流水，不知青鸟向谁家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与道卿鸣阳辈同游法海寺循平岭涉杨家坞还饮偃月冈","p":"","d":"明代","a":"王鏊","c":["忽忽春归不可攀，且乘高兴看湖山。回旋翠壑丹厓里，小憩青松白石间。", "为爱韶华连日醉，历观宦海几人还。风尘楚蜀干戈地，举酒何缘一破颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日杂题六首 其六","p":"","d":"宋代","a":"陆游","c":["一叶两叶病木霣，一点两点疏萤流。水底星河秋脉脉，发根风露夜飕飕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鸳鸯湖棹歌　之九十一","p":"","d":"清代","a":"朱彝尊","c":["江市鱼同海市鲜，南湖菱胜北湖偏。", "四更枕上歌声起，泊遍冬瓜堰外船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"静老容安庵二首 其一","p":"","d":"宋代","a":"孙觌","c":["离离风中花，深落任所之。泛泛水中萍，流转复在兹。", "静公湖海士，世网那得縻。独有铁石心，不与燥湿移。", "巢肩统灵鹊，支床馀老龟。区区了官事，应解笑儿痴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五月十一日夜且半梦从大驾亲征尽复汉唐故地","p":"","d":"宋代","a":"陆游","c":["天宝胡兵陷两京，北庭安西无汉营。", "五百年间置不问，圣主下诏初亲征。", "熊罴百万从銮驾，故地不劳传檄下。", "筑城绝塞进新图，排仗行宫宣大赦。", "冈峦极目汉山川，文书初用淳熙年。", "驾前六军错锦锈，秋风鼓角声满天。", "苜蓿峰前尽亭障，平安火在交河上。", "凉州女儿满高楼，梳头已学京都样。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"于报端读太夷先生壬戌重阳诗有叹其登高北望之意适炎造兄以新刊海藏楼诗本见赠作此并奉怀","p":"","d":"近代","a":"黄浚","c":["后山死后无重九，留句千年待郑公。南菊自知徵士意，北风犹想大王雄。", "公诗王道真难学，臣笔传人两未穷。我亦逢辰工感赋，恨无健气敌秋嵩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辰溪二首 其一","p":"","d":"明代","a":"薛瑄","c":["分司门外大江横，怪石参差岸不平。眼底秋山无限好，坐中凉吹有馀清。", "枣垂翠叶丹砂重，蜡满青林素练明。莫道蛮荒少题咏，龙标诗有五溪名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"襄阳二首 其一","p":"","d":"宋代","a":"陈造","c":["自怜薄宦走红尘，相见山灵厌俗氛。咫尺岘山无计到，祇应飞雨是移文。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"首春感怀","p":"","d":"明代","a":"高启","c":["初春风日自妍华，客意登临只感嗟。", "陌上惊尘随去马，城边遗柳断栖鸦。", "乱来未觅无兵地，愁在空思有酒家。", "咫尺苑西谁解问，早梅还发去年花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沁源山中","p":"","d":"金朝","a":"王特起","c":["野夫不识武城宰，问之无言色微改。但说今年秋雨多，黄芪满谷无人采。", "踏遍西城锦石盘，莫投佛屋解征鞍。隔林依约见灯火，山谷人家初夜寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古二十九首 其十二","p":"","d":"宋代","a":"释师体","c":["万里无云银汉横，大方玄路等闲行。阿爷智量世希有，女子圆光顶𩕳生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵答东嵎云巢二宪伯七首 其五","p":"","d":"明代","a":"黄衷","c":["狂爱童儿画纸文，离离关眼暗相分。双奁若许当长日，合筑棋坛拜冠军。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感怀","p":"","d":"清代","a":"张逢尧","c":["秋老霜飞夜奈何，乌衣旧燕痛无多。武陵花识秦渔父，曲水觞迷晋永和。", "声断蟪蛄窥上古，阵空蝼蚁闭南柯。昨宵宴罢麻姑酒，遥听蓬莱起棹歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"竟夜示伯承弟","p":"","d":"明代","a":"何吾驺","c":["竟夜沾花雨，无言对伯承。扣门深似海，永夕坐如冰。", "鼠戏频窥阁，蛾狂屡拂灯。遥怀寒雪里，欲枕不胜肱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮 其七","p":"","d":"当代","a":"黄绮","c":["红楼隔雨相望冷。青袍似草年年定。疑误有新知。帘疏燕误飞。", "柔情终不远。莫叹佳期晚。来去发春慵。仙衣尽带风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶题","p":"","d":"宋代","a":"叶茵","c":["曲肱玩味圣贤书，识破人间总畏途。", "盛欲对君言所以，又应诮我爱之乎。", "百年役役雁来去，一梦昏昏鹿有无。", "堪笑季鹰犹左计，求归何必待莼鲈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十八坊诗 介福","p":"","d":"宋代","a":"王十朋","c":["兹地有神宇，人人来荐羞。神虽能介福，福亦自须求。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辋川钓者图","p":"","d":"明代","a":"练子宁","c":["家住黄溪上，金川似辋川。凉风垂钓坐，明月棹歌还。", "绿水雕胡饭，金鳞缩项鳊。鉴湖如可乞，相与诵尧天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宋中遇陈二","p":"","d":"唐代","a":"高适","c":["常忝鲍叔义，所期王佐才。如何守苦节，独此无良媒。", "离别十年外，飘飖千里来。安知罢官后，惟见柴门开。", "穷巷隐东郭，高堂咏南陔。篱根长花草，井上生莓苔。", "伊昔望霄汉，于今倦蒿莱。男儿命未达，且尽手中杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"集句拟刘文纲少参悼亡 其二十五","p":"","d":"明代","a":"朱诚泳","c":["隐几无言有所思，惨烟悽雨不胜悲。梧桐叶上偏萧索，始是思君肠断时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题张宗苍云栖图","p":"","d":"清代","a":"弘历","c":["心爱云栖未恝忘，为图佳概命宗苍。江边宛识山村路，竹下曾吟水月房。", "泉箔岩扉相掩映，笠檐笏地足徜徉。香光妙迹留题在，长共烟霞护法王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郑敬常求题画像因用同姓八事赞之","p":"","d":"元代","a":"凌云翰","c":["清白传家古所难，门名通德又开端。履声未近星辰听，早带还经岁月看。", "五色云中知姓氏，七株松下具衣冠。毂推驿置非无意，谷口先须赋考槃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自睢宁至下邳道中杂诗六绝句 其三","p":"","d":"清代","a":"姚燮","c":["笋石当坡翠有棱，高丫四出罥风藤。萧疏一幅倪迂画，添个看云古衲僧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留别故城士民四首 其一","p":"","d":"清代","a":"夏诒垣","c":["甘陵古郡卫河滨，承乏匆匆两度春。新喻原为公仆职，旧箴还凛宰官身。", "此邦俗此唐风俭，作吏名惭汉代循。差喜萑苻今渐靖，寸心安慰别吾民。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题草堂寺","p":"","d":"元代","a":"黄复圭","c":["草堂禅寺北山陲，想见鸣驺入谷时。猿鹤如怀海盐令，鱼龙犹护绍兴碑。", "排岩树老秋来早，上殿僧稀晓散迟。我亦于今抗尘土，临风惭读孔璋移。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"入道诗十九首 其九","p":"","d":"宋代","a":"王庆升","c":["时节因缘不偶然，既由人事亦关天。功深德厚天孚祐，玉籍标名骨自仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"孝宗皇帝挽词二首","p":"","d":"宋代","a":"叶适","c":["伦德加文景，雄才自武宣。", "道终遗万乘，丧制尽三年。", "暂乞狂胡命，常持复汉权。", "全将一孝字，高谥百王前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"入直左掖中贵乞诗有作","p":"","d":"明代","a":"屠隆","c":["两朝出入有辉光，五夜疏钟漏未央。", "万树宫花歌宝扇，千门御柳映明珰。", "心如碧草生金辇，身是红云近玉皇。", "一样人间明月色，惯于天上听《霓裳》。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆西坡梅","p":"","d":"宋代","a":"仇远","c":["杖藜久不到西坡，苔上梅花积渐多。", "野屋荒凉谁管领，酒尊期会竟蹉跎。", "韶光二月已强半，乐事一生能几何。", "赖有邻园春可折，洗瓶斜插在行窝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"从蜀后主幸秦川上梓潼山","p":"","d":"唐代","a":"王仁裕","c":["彩仗拂寒烟，鸣驺在半天。黄云生马足，白日下松巅。", "盛德安疲俗，仁风扇极边。前程问成纪，此去尚三千。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄严州刘太守","p":"","d":"明代","a":"吴与弼","c":["我爱霜松托趣深，慇勤特表岁寒心。当年缟纻休相讶，遥寄新诗咏断金。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再赋","p":"","d":"宋代","a":"陈与义","c":["堂堂李杜坛，谁敢蹑其址。", "先生坐坛上，持钺令余子。", "由来文字伯，不但表奏伟。", "高怀淡无嗜，寓兴或留此。", "平生上林手，避谤淹二始。", "登临意超然，笔落风雨似。", "事异柳司马，辛苦记山水。", "乐哉邦无事，那待猛政理。", "驾言慰吾民，不愧城门轨。", "看山笑邹湛，句外寄深旨。", "岩树阅几客，尚余尧时髓。", "抚板歌公诗，未暇知余事。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"茅屋","p":"","d":"宋代","a":"薛嵎","c":["茅舍竹椽短，不劳朱恶施。", "高无神鬼瞰，贫与子孙宜。", "近古意全朴，当风势亦危。", "梅花有幽致，一树隔疎篱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"久不雨","p":"","d":"宋代","a":"陈淳","c":["草庐卧龙目未开。岩溪作霖手未抬。", "苍生望望亦劳尔，滂霈甘泽从何来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再和 其六","p":"","d":"宋代","a":"项安世","c":["丰年官事无何，梅月诗情最多。白水暗添沤界，青苔乱长松科。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望京府赏红梅","p":"","d":"元代","a":"郝经","c":["汴梁宫中绛绡梅，移向汴河堤上栽。青条团掿杏花颗，琐细向阳才半开。", "张公小队呼我饮，风色偃髯寒气凛。玉衔径踏黄河冰，貂帽飒檐掀紫锦。", "金鞍细马歌舞人，雪压小桥不动尘。入门下马簇花宴，红莲旧府花正新。", "玉川金波碧香酒，折花遍插分素手。春透寒梢未全绽，风流正要胭脂瘦。", "赏梅不用歌落梅，缓歌却著银笙催。爱香细撷生霞蕊，浮动云腴嚼一杯。", "本是前村冷澹花，不称王侯将相家。明朝会散更向明月底，藉雪冻吟疏影里。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次啸云师韵感时","p":"","d":"当代","a":"汪茂荣","c":["金瓯新奠泰山安，盈耳纶音拨置难。挟纩殊怜三伏暖，吟诗尚怯五更寒。", "齐家无处室虚白，蠹国有人颜渥丹。领略牵丝游戏意，莫成轻命倚危栏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢钖铭兄赠字","p":"","d":"当代","a":"陈振家","c":["故郡书家细琢磨，端庄妍秀见无多。而今恍得黄庭帖，不用山阴道士鹅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄林大参允吉","p":"","d":"明代","a":"祁顺","c":["地署同官早见知，十年重会楚天涯。升沉宦迹怜今日，尔汝交情似昔时。", "问讯恍疑身是梦，相看都觉鬓如丝。无端又动停云思，谩拂焦桐候子期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沁园春 其二 寿淮东制置","p":"","d":"宋代","a":"洪咨夔","c":["饮马咸池，总辔昆崙，横骛九州。庆中兴机会，天生山甫，非常事业，天授留侯。", "左搏龙蛇，右驯虎兕，万里中原谈笑收。功名早，便貂蝉猎猎，飞出兜牟。", "新氓无限欢讴。尽卖剑卖刀归买牛。正麦摇熏吹，黄迷断垄，秧涵朝雨，绿遍平畴。", "眼底太平，不图再见，罗拜焚香青海头。从今去，愿君王万岁，元帅千秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次华使张承宪公游汉江","p":"","d":"明代","a":"申光汉","c":["天上河源落五台，楼前澄影隔尘埃。", "杨花春尽帆归远，楮岛烟消雁影来。", "物色不随游子去，芳樽今为使君开。", "三韩胜地皆方丈，更借仙风倾一杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"食鱼","p":"","d":"宋代","a":"穆修","c":["南有嘉鱼异，常趋四月期。", "江天专伺至，烟网密争垂。", "乍戏汀苹末，初循水荇湄。", "竞摇轻舴艋，宽罩碧涟漪。", "占浦搜深藻，空波出素髭。", "数头馀赤质，二色类银姿。", "货鬻斯为切，鲜腴敢暇知。", "青钱邀价直，华屋市新奇。", "珠沫缘条煦，霜鳞逐刃堕。", "扣颅琼聚骨，剖腋锦分肌。", "味佐芳菘惬，香参苦笋宜。", "羹瓯融腻玉，脍助罥寒丝。", "湘鱓非吾偶，河鲂孰与夷。", "薦新奚尚鲔，稔毒即殊{左鱼右几}。", "鲈讶休官易，鲭嫌醒酒迟。", "自当频佐膳，所惜易过时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过桃川万寿宫二首","p":"","d":"宋代","a":"王阮","c":["翁子洞头魂黯黯，桃川山上目凄凄。", "自怜终失邯郸步，不是重来旧路迷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早春寄周致尧","p":"","d":"元代","a":"陈雷","c":["百年身世浑如寄，何处他乡是故乡。柳态正须春弄色，梅花自与雪生香。", "扬雄寂寞玄犹白，贺监风流醉亦狂。倘许胜缘同晚岁，梨林风致即柴桑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和孙端叟寺丞农具十五 其六 钱镈","p":"","d":"宋代","a":"梅尧臣","c":["诗称庤钱镈，南亩兴农作。宁唯务芟薙，岂不在刈穫。", "收功向嘉谷，托用随芒屩。太平兹所重，坐见销锋锷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋得揽察草木犹未得示诸子五首 其三","p":"","d":"明代","a":"谢元汴","c":["勿将死玉匹生刍，义竹春深咒老梧。种得兔丘为媚草，化成婺女作桑弧。", "人才信已同蜍志，燕市今当访狗屠。龙比负尸徒往事，倚天长剑客星孤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题汪水云诗十首","p":"","d":"宋代","a":"罗志仁","c":["丰乐华楼已劫灰，涌金春色未尘埃。", "道人有道轩窗静，那处湖光不好来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南山","p":"","d":"宋代","a":"陈谠","c":["天造其山，在贵之阳。二十四峰，拔地峭刚。其山维何，如彼玉苍。", "宅位于离，火德之祥。南山何有，有方其岩。若堂甚夷，若门者三。", "穹者圆盖，植者羽参。石像天成，匪凿匪劖。陟彼山巅，有洞益奇。", "南北户通，千里頫窥。伊晋之洪，采荣于斯。丹飞井霤，木润草滋。", "昔我太宗，云章下贲。于皇仁庙，奎文狎至。岩处有辉，神护孔閟。", "丕昭圣朝，声化远暨。南山不骞，天子万年。南山不朽，天子万寿。", "无量惟寿，与天齐久。小臣作诗，永飏于后。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赏牡丹","p":"","d":"明代","a":"王弘诲","c":["朱明开令节，邀赏对名花。潋滟欺秾李，纷披夺丽华。", "天香横席满，国色倚阑斜。绿叶舍朝露，红英缀晚霞。", "迷蜂娇吐蕊，戏蝶绽分葩。幻字留仙种，凝脂出帝家。", "醉妆妃子妒，敛态洛神誇。名入骚坛重，根当锦障赊。", "洛阳春有价，金谷净无瑕。芍药堪成侍，芙蓉似失嘉。", "自缘生富贵，偏许事豪奢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和希颜","p":"","d":"金朝","a":"冯璧","c":["虎守天门未易通，庾尘无扇障西风。主人何负盗憎主，公论不明私害公。", "老伏固非千里骥，冥飞似是五噫鸿。纷纷往事渠知几，都付崧巅一笑中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南来好伴","p":"","d":"明代","a":"郭之奇","c":["四载依依几送迎，故山结色此能生。春情广覆千峰落，霞侣先开一壑盈。", "相过不移知我素，此中何有祇云清。南来好伴兹堪恋，去去江天日暮情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七月望后寄寒碧上人","p":"","d":"明代","a":"徐波","c":["楚鬼微吟上峡谣，中元法食可相招。凭师为譬兴亡恨，雨打秋坟骨亦销。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再次韵二首 其二","p":"","d":"元代","a":"袁桷","c":["阁道新平旧石摧，望乡使客意嵬嵬。犀牛坐见降王去，杜宇声随望帝来。", "三卯录成魂有燐，五丁神泣劫扬灰。推酾欲作乡邻会，挥手先催弩矢回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"释晓莹","c":["清泉槛外流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"摘园菊赠谢仆射举诗","p":"","d":"南北朝","a":"王筠","c":["灵茅挺三脊，神芝曜九明。菊花偏可憙，碧叶媚金英。", "重九惟嘉节，抱一应元贞。泛酌宜长主，聊荐野人诚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"为刘君符赋乐山诗","p":"","d":"宋代","a":"陆文圭","c":["山体本至静，仁体亦如之。", "乐者有深味，鲁论无费辞。", "目玩唯自得，心契若有期。", "逝川同一旨，妙理无容窥。", "刘公本好古，雅志非好奇。", "诸君为著语，殆类爱山诗。", "泉石涵清思，松柏媚幽姿。", "古来山中人，此道未必知。", "蜡屐张乃癖，拄笏殆成凝。", "独有首阳高，薇苦甘如饴。", "得仁即无怨，千载真吾师。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"听百舌鸟","p":"","d":"唐代","a":"王维","c":["上兰门外草萋萋，未央宫中花里栖。亦有相随过御苑，", "不知若个向金堤。入春解作千般语，拂曙能先百鸟啼。", "万户千门应觉晓，建章何必听鸣鸡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春残","p":"","d":"唐代","a":"唐彦谦","c":["景为春时短，愁随别夜长。暂棋宁号隐，轻醉不成乡。", "风雨曾通夕，莓苔有众芳。落花如便去，楼上即河梁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留题常熟顶山僧居","p":"","d":"宋代","a":"范仲淹","c":["平湖数百里，隐然一山起。", "中有白龙泉，可洗人间耳。", "吾师仁智心，爱兹山水音。", "结茅三十年，不道日月深。", "笑我名未已，来问无端理。", "却指岭边云，斯焉赠君子。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送童子敬赴省","p":"","d":"宋代","a":"姚勉","c":["满望飞腾几许年，一闻充赋喜如颠。金经炉冶锋方锐，木饱风霜节始坚。", "此去稳登云里路，定知荣冠籍中仙。近闻上蔡鸬洲合，一似前年锦水连。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花岭瞻史公遗像","p":"金缕曲","d":"清代","a":"魏元戴","c":["心共朝衫赤。岸乌纱、临淮空障，东南半壁。惨变先皇臣欲殉，眉宇久无人色。", "况肠断、高堂永诀。黯淡精神横泪眼，陡辛酸、动我心如铁。", "迟不去，日方昃。", "调停四镇真诚竭。枉整顿、朝廷小小，内奸牵掣。付与孤忠成结局，浩气沧溟应塞。", "又何必、钟山埋骨。精魄倘逢留后约，怅燕云、几洒忧时血。", "更莫问，扬州月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"无利无名","p":"满江红","d":"宋代","a":"张昪","c":["无利无名，无荣无辱，无烦无恼。夜灯前、独歌独酌，独吟独笑。况值群山初雪满，又兼明月交光好。便假饶百岁拟如何，从他老。", "知富贵，谁能保。知功业，何时了。算箪瓢金玉，所争多少。一瞬光阴何足道，便思行乐常不早。待春来携酒殢东风，眠芳草。"],"tags":["生活", "闲适", "抒情"],"z":"","y":"","s":"","k":"词"},
  {"t":"林和中家观画卷五首 其一 寒芦飞雁仍和子中修撰旧韵","p":"","d":"宋代","a":"郭祥正","c":["芦黄水落秋将暮，鼓翼各寻云外路。为问归飞归底处，我今亦向江南去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浪淘沙令 庐山即景","p":"","d":"近代","a":"林伯渠","c":["牯岭雨声喧，气象万千。爱听东谷水潺。日照香炉知何处？", "雾里云端。智慧何人先？卡尔开山。重峦叠嶂更新鲜。", "一二三四大手笔，宝藏兴焉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南史六首 其三 褚渊","p":"","d":"明代","a":"郑学醇","c":["翠屏金屋捲流苏，秉烛曾称伟丈夫。世族不更时事改，舅家宗祐倩谁扶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"艳秋新婚并画并蒂莲花并题","p":"","d":"清代","a":"曾习经","c":["孔翠鸳雏略费评，楼前红烛笑相迎。偶然拾得青羊句，并蒂莲花愿往生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送严十五郎之长安","p":"","d":"唐代","a":"戎昱","c":["送客身为客，思家怆别家。暂收双眼泪，遥想五陵花。", "路远征车迥，山回剑阁斜。长安君到日，春色未应赊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李致美之任云中","p":"","d":"金朝","a":"王寂","c":["宸衷简在付陪京，摩拊疲氓藉老成。金阙共瞻卿月出，野人相庆福星明。", "先声雷殷妫州路，和气春回魏帝城。想见郊迎笳鼓竞，吏民惊叹綵衣荣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题六江桥","p":"","d":"明代","a":"庄昶","c":["礼乐乾坤已备任，江山底处许孤襟。六江老眼吾真到，惠爱何人此最深。", "欲济无梁须尔是，买田为井亦如今。深山惟有区区在，得尽裁成万古心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菊花","p":"","d":"宋代","a":"潘牥","c":["露叶霜枝矮作团，淡黄残绿故瓓珊。柴门尽日无人到，独自栽花独自看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酬和杜五弟晴朝独坐见赠","p":"","d":"唐代","a":"李峤","c":["平明坐虚馆，旷望几悠哉。宿雾分空尽，朝光度隙来。", "影低藤架密，香动药阑开。未展山阳会，空留池上杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"顺风放舟","p":"","d":"清代","a":"胤禛","c":["长河风力驶，千里片帆轻。桨歇村频转，桡停岸自迎。", "野凫冲荇起，归雁拂云鸣。试问邮亭吏，何如驷马行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和陕州参军李通微首夏书怀呈同寮张裳段群二先辈","p":"","d":"唐代","a":"姚鹄","c":["公门何事更相牵，邵伯优贤任养闲。满院落花从覆地，", "半檐初日未开关。寻仙郑谷烟霞里，避暑柯亭树石间。", "独为高怀谁和继，掾曹同处桂同攀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词 其二十三","p":"","d":"宋代","a":"赵佶","c":["集英亲殿策才豪，盈庑纷纷尽雪袍。礼乐问题人罕记，就纡黼座继兰膏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重登庐山感怀","p":"","d":"未知","a":"陈香梅","c":["四十年来烟雨多，国恨家仇奈若何；英雄抗日征战死，天涯游子唱离歌。", "牯岭东西谷尚在，郎人士旧风波；庐山别业怀往事，好汉坡前望银河。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"依韵酬葛秋岩陶体四首","p":"","d":"宋代","a":"释文珦","c":["山林自多趣，况此晴和时。", "我友贲然来，相娱以琴诗。", "仓庚遗好音。薰风发清吹。", "悠然与心会，安能遽忘兹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初归同诸弟夜坐","p":"","d":"明代","a":"谢与思","c":["拂尘坐来久，轻飏生绤衣。半年几今夕，为客正东归。", "露裛竹梢润，萤穿书幌微。但愁城际月，清漏促光辉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"箱根玉泉楼","p":"","d":"清代","a":"林朝崧","c":["山拥楼前后，水随山短长。水声疑急雨，日色易斜阳。", "入浴灵泉煖，踏歌瑶草芳。烟云足供养，吾欲住仙乡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和李令扈从温泉宫赐游骊山韦侍郎别业","p":"","d":"唐代","a":"卢僎","c":["风后轩皇佐，云峰谢客居。承恩来翠岭，缔赏出丹除。", "飞盖松溪寂，清笳玉洞虚。窥岩详雾豹，过水略泉鱼。", "乡入无何有，时还上古初。伊皋羞过狭，魏丙服粗疏。", "白雪缘情降，青霞落卷舒。多惭郎署在，辄继国风馀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题四明张氏南园","p":"","d":"宋代","a":"魏汝贤","c":["修篁曲折绕墙东，风景辋川孰兴同。", "过雨凉生千树外，乱山青入一楼中。", "高人尔日联吟社，逐客当年作寓公。", "别后新诗又多少，双鱼应许寄邮筒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其二","p":"","d":"宋代","a":"方岳","c":["一钱太守今贪吏，五柳先生歙富民。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观祝少林所藏画三首 其一 米元晖画","p":"","d":"宋代","a":"赵蕃","c":["萧寺相从三十日，知君有画未曾窥。烟云过眼还收去，恰似凭栏立久时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙 其一 感怀次颖庐韵","p":"","d":"当代","a":"熊盛元","c":["翠鸟啼时晓梦回，罗浮影事漫惊猜。悔耽诗酒误生涯。", "蓬鬓初飘残腊尽，冰澌乍坼锦鳞来。一襟幽素为谁开？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"嫣然亭","p":"寄题周功父溪园三咏","d":"宋代","a":"张栻","c":["闻说亭花好，居然似蜀乡。", "色深姿不俗，香淡意能长。", "高烛留深夜，轻阴护晚芳。", "何心较桃李，只拟答春光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"溪桥散步","p":"","d":"明代","a":"秦奭","c":["老去观书兴易阑，绿阴清昼况多闲。杖藜扶我溪头步，看尽湖南十里山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋思四首 其一","p":"","d":"明代","a":"林章","c":["不知秋何如，明月照人寝。上照凤凰琴，下照鸳鸯枕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"效长吉体","p":"","d":"宋代","a":"刘有庆","c":["穷庐夜雪没驼脊，黄沙号风冰结石。", "燕姬二八髻垂漆，柔荑斜抱箜篌立。", "老羌踏歌歌勅勒，黄金流星酒杯窄。", "红氍毹暖春云湿。缕金团衣猩血滴，", "玉钗醉滑鹍弦急。角声满空霜裂骨，", "十万狞君掩襟泣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"武担山感事 其三","p":"","d":"宋代","a":"孙应时","c":["身不入莲社，意非同漆园。閒来阅风物，归去老山村。", "气味故相许，渊源须细论。灯前秋夜永，未可付忘言。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"隆乾间事","p":"念奴娇","d":"宋代","a":"刘克庄","c":["隆乾间事，两翁有、手泽遗编曾纪。余掌兰台修纂到，景定初开忠邸。坏起复麻，奋涂归笔，嚼碎张巡齿。德音犹在，非卿何足语此。", "老来兹事都休，问门前宾客，今朝来几。达汝空函，投伊大瓮内，谁曾提起。丹汞灰飞，黄粱炊熟，跳出槐宫里。儿童不识，秃翁定是谁子。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"方思道送西峰","p":"","d":"明代","a":"王守仁","c":["西峰隐真境，微境临通衢。行役空屡屡，过眼被尘迷。", "青林外延望，中閟何由窥？方子岩廊器，兼已云霞姿。", "每逢泉石处，必刻棠陵诗。兹山秀常玉，之子囊中锥。", "群峰灏秋气，乔木含凉吹。此行非佳饯，谁为发幽奇？", "奈何眷清赏，局促牵至期。悠悠伤绝学，之子亦如斯。", "为君指周道，直往勿复疑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七月十四日观虹","p":"","d":"明代","a":"赵完璧","c":["半天云雨半天晴，雌蜺连蜷斜照明。莫自巫阳归意倦，晚拖腰带背人横。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋月 其二","p":"","d":"宋代","a":"文同","c":["望外物容澄似水，坐中秋力凛如刀。此身直愿乘双翼，飞上三峰第一高。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大风起","p":"","d":"明代","a":"陶安","c":["大风起，大风起，扫荡烟尘净如洗。火龙吹燄成赤云，鼓铸乾坤又一新。", "鸾旗豹车过沛里，父老子弟争迎喜。向年离家才庶民，今日还乡是天子。", "酒酣情浓思故旧，慷慨悲嗟舞长袖。复除户户动欢声，千秋万岁君王寿。", "壮哉亲唱大风歌，金石铿轰奈乐何。君不见拔山盖世骨先朽，何在威加诧雄赳。", "又不见深室悬钟烹走狗，何用猛士为之守。大风起兮云飞扬，不如膏雨流滂滂。", "威加海内归故乡，不如帝德天下光。安得猛士守四方，不如王佐之才登庙堂，所以汉道不克承三王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"采莲曲","p":"","d":"元代","a":"郭翼","c":["莲子复莲子，苦心郎不尝。为郎剥莲子，莲子忆空房。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题湘灵鼓瑟","p":"","d":"元代","a":"马臻","c":["沅湘水阔风萧萧，水风敲佩天光摇。为弹宝瑟传幽愫，一点柔红泻香露。", "苍梧恨锁云欲流，湘花背日烘春愁。人间有梦到不得，仙山翠滑江浪黑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"青溪曲 其四","p":"","d":"明代","a":"景翩翩","c":["与欢深夜归，小妹调筝歇。并坐结同心，引到楼头月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"故仆射司马文正公挽词四首","p":"","d":"宋代","a":"张耒","c":["伊洛平生兴，园林独乐居。", "曾过郑公里，得御李膺车。", "华屋当年客，名山异代书。", "定知传不朽，埋玉自沾裾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风月堂夜饮","p":"","d":"宋代","a":"方岳","c":["霜洗横枝月上初，春彝更可共谈无。", "玉杯一一寒於雪，贮以诗肠渺似湖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"落魄","p":"","d":"宋代","a":"陆游","c":["落魄东吴莫笑侬，今年要不负春风。", "闲愁掷向乾坤外，永日移来歌吹中。", "酒浪欲争湖水绿，花光却妒舞衫红。", "公卿忧责如山重，肯信人间有放翁！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梁阮研宰相帖赞","p":"","d":"宋代","a":"岳珂","c":["巨济取帖，断于李唐。", "而予何人，波及于梁。", "然而考硬黄之流别，辨缃素之古香。", "并之以淳化秘阁之迹，印之以绍兴御府之章。", "於戏斯文，不忝厥藏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"释奠诗","p":"","d":"南北朝","a":"王僧达","c":["时泰道畅，礼备乐修。启痒选俊，博教深求。民人鳞萃，淑美云浮。", "师尊训浃，嘉敬载柔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵玉溪生春雨以应两圈诗会","p":"","d":"当代","a":"陈忠平","c":["春丝密密织纤衣，念汝衣单梦久违。偶尔帘开清影动，原来燕啄紫泥归。", "千山翠黛凝还叠，满院芳华落渐稀。庄蝶应怜双翅冷，窗前不见共于飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"徐寿仁","c":["放怀追许谢，洗耳笑巢由。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"村饮","p":"","d":"宋代","a":"陆游","c":["少年喜任侠，见酒气已吞，一饮但计日，斗斛何足论。", "绿草满雉场，红旗植球门，三叫落乌帻，倒泻黄金盆。", "银炉炽兽炭，狐兔纷炮燔。", "浩歌撼空云，壮志排帝阍。", "回首今几时，去日如车奔，朱颜辞晓镜，白发老孤村。", "邻翁劝黍酒，稚子供鱼飧。", "功名信已乎，万事付乾坤！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅影","p":"","d":"宋代","a":"王柏","c":["梅花已清绝，明月忽横窗。", "孤影知难并，群花已竖降。", "淡痕开画帐，皓色掩书缸。", "寂寞素娥冷，须臾拥去幢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虞美人","p":"","d":"宋代","a":"谢薖","c":["人间离合常相半。璧月宁长满。九秋风露又方阑。何日小窗相对、话悲欢。", "月华临夜宜人醉。老去嗟颜悴。君如玉树照清空。况有凝之道蕴、一尊同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绝句五首 其二","p":"","d":"明代","a":"黎贞","c":["谁怜客里病厌厌，自觉乡思日日添。从此无心爱良夜，任教花影过疏帘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天 其二 上巳日会饮卫生袭之家园","p":"","d":"金朝","a":"段成己","c":["殢酒偿春笑二豪。题诗品物愧时髦。心如幽鸟忘机静，身似虚舟到处漂。", "须富贵，是何朝。一杯聊慰楚人骚。逢花堪赏应须赏，座有嘉宾尊有醪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其四","p":"","d":"明代","a":"黎民表","c":["脱帽当松顶，移舟傍竹阴。岂知青琐客，还有绿萝心。", "思苦诗篇警，情忘酒盏深。寥寥山吏部，千载此知音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清明日同朱君华亭、姚君岫章踏青就李氏杏林小酌","p":"","d":"近代","a":"刘清漳","c":["佳节寻芳傍运河，神沙庙侧又重过。黄金染遍千章柳，绿水吹来万叠波。", "大地含生负景气，皇天造化寓冲和。杏林小酌花盈盏，醉卧春风尽忘它。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀昔吟八首 其二 张九云先生","p":"","d":"明代","a":"曹于汴","c":["清白信清白，日远扬辉光。片札世人珍，乞米帖同芳。", "堂堂八座尊，候俸制母裳。邻翁售以宅，昕夕为徬徨。", "流传聊彷佛，峙岳悬春旸。所叹文昭后，高丘柏已戕。", "天道不可问，人生惟允臧。孤凤鶱云汉，谁与之颉颃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又答林镇江","p":"","d":"明代","a":"邵宝","c":["麻姑山下石矶边，舣棹逢君是此年。", "落月梦长千里外，归云心远九峰前。", "东曹史牍忙中事，南国诗筒病后缘。", "公暇漫从江郭眺，沧浪歌起白鸥天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有赠 其二 刘峻","p":"","d":"当代","a":"刘斯奋","c":["飞名廿载杂文场，埋剑归来草树香。割断苍凉中岁感，东山菊影倚刘郎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"点绛唇 谷雏为作瑶山行役图，因题其上","p":"","d":"近代","a":"饶宗颐","c":["刺眼奇峰，当年曾是经行处。朔风如虎。山上斜阳舞。", "又向天涯，蓬转惊如故。心无住。漫劳缣素。觅取归时路。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题嘉州嘉望亭","p":"","d":"宋代","a":"韩琦","c":["欲知藩境得嘉名，试策筇枝上此亭。江色照城平似练，岚光堆槛活如屏。", "好遨民阜充衢乐，出品花奇袭坐馨。使驲暂来闲寓目，几多高意在鸿冥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟发长沙四首 其二","p":"","d":"明代","a":"薛瑄","c":["已觉长沙北，犹瞻岳麓西。天浮湘水阔，树入楚山低。", "岸芷馀香草，丛篁染旧啼。昔贤游览地，我亦为留题。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"孔雀吟寄国学保存社","p":"","d":"近代","a":"胡雪抱","c":["孔雀栖珠崖，餐香出南海。修翎时一舒，金气横空霭。", "珍禽动遥和，奇服垂璎彩。乘时各有耀，离合目精骇。", "似彼深心人，芳誉私相采。惺惺惜惺惺，结爱不能解。", "岂无俊鹦哥，鲫溜学雏婢。传语生飞谣，诵经妄忏悔。", "宁知清浊异，狐媚徒滋败。志洁寡所营，沉浸养云采。", "十年丰其羽，偶露神潇洒。饮啄自有真，焉在饫虾蟹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题史督师墨迹","p":"","d":"清代","a":"郑孝胥","c":["鸷鸟翻飞自有时，图功布局不妨迟。驽骀四镇终俱败，太息扬州史宪之。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水调歌头 为龚节孙题种橘图","p":"","d":"清代","a":"曹贞吉","c":["玉局昔年客，秃鬓老仙翁。思移林屋嘉树，饱啖洞庭红。", "疑作亭名楚颂，眷此素荣绿叶，惨淡比青枫。有志那能遂，遗迹大江东。", "仿瞻子，怀古意，画图中。雨蓑风笠，长镵白木苦匆匆。", "且自耕云半亩，转眼霜林千颗，一笑对山童。忘却生绡里，欲倩右军封。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂韵","p":"","d":"清代","a":"大宁","c":["峰顶屋三间，松边石一片。早晚云飞来，只有樵夫见。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"信丰江口乘小舟入雩都访友人罗","p":"","d":"明代","a":"张天赋","c":["琴剑路迢迢，春风袭客袍。雾开山骨现，风起浪头高。", "草色连坡绿，莺声隔岸遥。雩都门户远，分付梦先敲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"台阳笔记题词 其一","p":"","d":"清代","a":"包礼","c":["要从沧海涉风波，才算人间阅历多。剿寇奇功同大树，论文雄辩等长河。", "台阳德政苍生福，山左清名白雪歌。一自归来无个事，行踪到处寄吟哦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再登南楼怀元舆三首 其一","p":"","d":"宋代","a":"郭祥正","c":["欲上层楼足力微，世情尘事老方知。离骚一曲何人会，空使潇湘鬼物悲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百二十三首","p":"","d":"宋代","a":"释崇岳","c":["恁麽恁麽，牵犁拽杷。", "不恁麽不恁麽，泥多佛大。", "临济三玄，赵州勘破鼻孔大。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上谷歌八首上楚中丞","p":"","d":"明代","a":"尹耕","c":["新河洗马晚苍苍，风急城孤古膳房。", "分道往年频失利，筑垣今日见周防。", "转输几实饥人腹，锋镝新扶战士疮。", "乳哺庙谋应不后，坐看穷徼系苞桑。¤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春雨","p":"","d":"明代","a":"王缜","c":["黑云堆墨暗朝曦，甘澍当春正及时。细细蛛丝游碧落，森森银烛傍瑶池。", "太平有象三农乐，灌溉无私万物知。涸砚愿沾涓滴润，拟歌圣德被新诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金陵道中","p":"","d":"宋代","a":"郑獬","c":["六国相排一局棋，岸头百草野烟微。", "树深啼鸟自相失，山静晚云犹未归。", "濡口潮回残照满，石城春尽乱花飞。", "周郎屈指图天下，谁道江南玉鱠肥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓发辞夫矶时李泂溉之友先行","p":"","d":"元代","a":"何中","c":["荻暗鸡鸣村，平皋下残月。参差邻舫语，橹声带潮发。", "露华望中白，蓬阴散秋发。沙鸟知曙鸣，海云上空灭。", "念我前行友，青山已飞越。迟尔及相携，无嗟赏心歇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟行即事七首 其一","p":"","d":"宋代","a":"朱淑真","c":["帆高风顺疾如飞，天阔波平远又低。山色水光随地改，共谁裁剪入新诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"一络索二首 其二","p":"","d":"清代","a":"王时翔","c":["双扇题诗愁别意。碧筠新制。几年风雨泣湘江，染尽了、斑斑泪。", "误纳佳人袖里。怕添憔悴。索还未许但须藏，慎莫展、相思字。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉命视部篆岁除日履任奉呈桂翁少傅 其一","p":"","d":"明代","a":"严嵩","c":["亭玉张筵迥，袍绯拥绶新。丹霄通雨露，华省切星辰。", "拔擢惭非分，遭逢庆此身。所希阳道泰，明日万方春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登峨眉 其八","p":"","d":"清代","a":"毛澄","c":["澄碧古潭渺，落木号西崖。龙子三寸余，头角藏风雷。", "海水缩归钵，养此千岁孩。铁销南极垂，石扇中天开。", "琼楼十日出，花发金银台。玉女千余人，飘飖凌九垓。", "云璈辍灵响，贻我镂霞杯。蹑烟笑相语，汉武非仙才。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古三十六首 其十二","p":"","d":"宋代","a":"释惟一","c":["和尚尊位如何，突出日面月面。光艳烁破乾坤，五眼觑之不见。", "觑得见，何似寻常腊月扇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其五十四","p":"","d":"宋代","a":"晏殊","c":["遥想江南此时节，小梅黄熟子规啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闺怨四首","p":"","d":"宋代","a":"赵蕃","c":["辞少不尽意，辞多还尽纸。", "纸尽意无穷，相思似流水。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送鹌鸭腊龚养正二首 其二","p":"","d":"宋代","a":"陈造","c":["骚人茹粥耐支离，过眼风光不到诗。乡味慇勤劝开肉，未妨新句解人颐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西园春兴因赠雪庭上人兼简张公讲师","p":"","d":"元代","a":"耶律铸","c":["万丈虹霓络紫烟，笙歌清沸雨馀天。满庭芳草翠如积，一洞碧桃明欲然。", "流水引来梅坞底，春风吹到酒垆边。散花唤起毗邪梦，从此无心号谪仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初春","p":"","d":"明代","a":"释函是","c":["东风初拂月初弦，寂寞柴门送雁天。梦断梅花空见叶，望深杨柳未成烟。", "一声画角山城远，万里行人春树边。珍重白云啼鸟处，几回惆怅绿萝前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"访子威都事不遇","p":"","d":"元代","a":"黄清老","c":["清晓抱绿绮，来就夫君弹。", "夫君久已出，野水流花间。", "石涧度微雨，秋生湖上山。", "松阴坐永日，心与云俱闲。", "人事有离合，白鸥聊共还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"缺门遇王三兄师文","p":"","d":"宋代","a":"晁说之","c":["生民本羁旅，何以娱今朝。风雨崤渑道，离别秋冬交。", "忽复有好怀，故人道旁招。如狂语错乱，疑梦情飘飘。", "君须何尽白，我志则全消。忧患君恐可，图书兴尚豪。", "玷圭宜委土，良骥乃系匏。但愿不再辱，敢慕无久劳。", "马蹄分异县，朔吹结同袍。三年以为期，嵩少理居巢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"折杨柳","p":"","d":"明代","a":"朱成泳","c":["灵州城下柳，多被官军窃。", "犹余拂地条，更苦行人折。", "无复眼窥春，不见花飞雪。", "今君赴玉关，将何赠离别。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五月六日先为马蹶而伤左足自清漳千里舆归闽宪是日之夜坐占长句","p":"","d":"明代","a":"谢肃","c":["何幸蒙恩不自酬，此心宁敢为身谋。塞翁得马未为福，乐子下堂方有忧。", "难把股肱裨帝力，欲冯耳目赞皇猷。驰驱未效先成跛，绛烛华轩坐泪流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"建德溪涨大作感怀","p":"","d":"明代","a":"魏观","c":["久雨逢戊晴，戊日雨不止。羽气凄乘宫，土德沦不纪。", "晻晻阴晦凝，四野连蓄水。绝壁洄冲波，玄林渺中沚。", "下上鸥鹭驯，沈浮蜃蛟喜。田庐聚岑阿，渔艇系桑梓。", "官租欲谁徵，军乏且无已。爰𨋎昏垫情，罔究疏浚理。", "悠悠古圣人，惟日思复起。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"成帝","p":"咏史上","d":"宋代","a":"陈普","c":["元帝斋宫纳弁儿，阿娇金屋篡歌姬。", "披香博士多才学，刘氏家传有未知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朱鹭","p":"","d":"明代","a":"穆孔晖","c":["刷羽春塘寂，腾身碧落遥。碧鸡非我友，白雉任谁招。", "海僻丹霞满，嵓深绿树饶。沙岸曝朝日，蒲流戏晚潮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄留二君仪","p":"","d":"宋代","a":"郭祥正","c":["今岁看书眼觉昏，忆君待酒只销魂。临漳姑孰五千里，怀抱何时得再论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古梅","p":"","d":"宋代","a":"程炎子","c":["水边山脚友渔樵，梅欲窥人故故招。", "树剥龙鳞黏碧藓，枝翘鹤膝糁红椒。", "诗如老杜吟东阁，梦约逋仙过断桥。", "好待月窗清影瘦，传他神子上生绡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寒食行二首 其一","p":"","d":"明代","a":"胡奎","c":["江南三月梨花雨，寒食邻家哭儿女。阿爷战死长兄存，二十年来别乡土。", "存无信息死无归，胡蝶春风泪满衣。纸钱空挂枯杨树，存者不知埋骨处。", "一百五日年年来，天外游魂何不回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蒋中丞庭下芙蓉三首","p":"","d":"宋代","a":"滕岑","c":["菊与为朋竹与邻，闭门谁见晓妆新。", "不须多羡苏堤好，车马往来尘污人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和霜青韵","p":"鹧鸪天","d":"近代","a":"王韶生","c":["往事萦回寸寸心。流光弹指去来今。浮名渐觉焦中鹿，密意仍珍叶底禽。", "鲜荔子，熟林檎。两般情味一般深。云罗万里无消息，怪底樽前事苦吟。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"赠蔡内翰九逵","p":"","d":"明代","a":"金大车","c":["清朝散史鬓毛斑，江左词人数往还。彩笔调高追汉代，玉堂官冷压仙班。", "醉攀春柳晴看月，卧放晨衙早闭关。他日思君寻旧隐，荷衣冲雨洞庭山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王衢之任德之推官","p":"","d":"宋代","a":"魏野","c":["从军重叠继家声，雅称风流旧信灵。", "功业即看辉圣日，科名先已应台星。", "丝蚕地说连河朔，戎马尘闻近虜庭。", "正是穷秋雨多际，水堪回首向郊坰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"河中八咏 其七 杨惠之维摩像","p":"","d":"金朝","a":"赵秉文","c":["一默传心已失机，更求形似转成痴。至今遗像兀不语，犹似当初问法时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"槐","p":"","d":"明代","a":"李之世","c":["空翠摇阶云影凉，秋来槐叶几飘黄。种时人尚高于树，今过墙头如许长。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双声子 其二","p":"","d":"近代","a":"薛建吾","c":["浦滨萧国，白门燕市，堪怜南北奔劳。频年羁旅，萧斋岑寂，素娥屡伴无聊。", "金兰协好，倾别绪，曾共良宵。欢难再，境全改，茫茫幽恨难消。", "看长空，星静云幕卷，桂轮拥出重霄。金波扬彩，银蟾横影，多情未把人抛。", "奈孤帏独守，消瘦了，旧日丰标。开窗邀取，婵娟可愁，碧落风高。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪纱 题王蓉珊女士海沤集二阕 其一","p":"","d":"清代","a":"程颂万","c":["淡影于人画着螺。瘦蟾延想未成歌。忍抛诗思奈才何。", "妙迹黄初临洛浦，双栖白下誓明河。家山破后尽风波。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上元后南溪泛舟联句","p":"","d":"宋代","a":"韦骧","c":["野渡半篙水，春风一苇航。柳梢舒嫩绿，梅萼泛幽香。", "绣羽惊波起，翠鳞跳日光。环城得佳趣，清思满高塘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"月夜闻雁","p":"","d":"清代","a":"任丽金","c":["独坐南窗下，初晴月倍明。云中新雁唳，却作故乡声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"武夷山中四首","p":"","d":"宋代","a":"蔡沈","c":["余昔隐屏南，春风驻征骖。", "开门傍水面，结屋依山岚。", "千崖互纡郁，万象中浑涵。", "居然岁月深，寒花露毵毵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山家春晓","p":"","d":"明代","a":"李时勉","c":["日高照见松窗里，照人春眠犹未起。家僮洒扫及中堂，唤起客来供盥洗。", "披衣随步小窗外，杨柳依微莺细语。皆言昨夜风雨恶，绿树披离花满地。", "老父庭前扫落花，扫开春径莫教遮。怕有客来寻旧术，不妨竹里引轻车。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古墨篇寿韩大雅参议","p":"","d":"元代","a":"周伯琦","c":["苍松千岁姿，灵根伏琥珀。吐气结晴云，化作古玄璧。", "清芬㜶芝兰，坚质等金石。上进蓬莱宫，遂冠龙宾伯。", "磨研发春英，灿烂翻琼液。密传邹鲁心，仰写羲周画。", "风雷兴礼乐，日星耀方策。岂惟儒者功，实系斯文脉。", "君子坐庙堂，群臣赖滋泽。良辰持此寿，播誉永无斁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"灵洲醉中赋","p":"","d":"明代","a":"黄佐","c":["青林碧海环高台，孤根独立云之隈。神鳌跋浪远天动，老鹤警霜幽梦回。", "西川词翰出下土，南海衣冠朝上台。一尊如醉兀然坐，万里长风吹月来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋夜二首 其一","p":"","d":"明代","a":"欧大任","c":["秋风西北至，河汉横中天。他乡况久居，游子私自怜。", "蟪蛄鸣且凄，鸿雁何翩翩。叹息夜中起，揽衣白云前。", "故人一尺书，关山邈以绵。宁当如参商，别离多盛年。", "携手思行游，何时早归旋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂十四首 其一","p":"","d":"宋代","a":"释印肃","c":["雪人通身却吃骂，兔角拄杖三十下。龟毛索子钓虚空，道理本来非昼夜。", "元不借□□，宝所谁知价。一道常光即我心，逼塞虚空无缝罅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清华阁","p":"","d":"宋代","a":"邹浩","c":["泉石清华世岂知，萧然无是亦无非。二年于此陪鸥鹭，收得閒中勋业归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"村居即事","p":"","d":"宋代","a":"晁补之","c":["小麦青青大麦稀，蚕娘拾茧盈筐归。放牛薄暮古堤角，三四黄莺相趁飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莲花峰早起与印上人","p":"","d":"清代","a":"曹玘","c":["欲曙未曙候，空山无可名。但见鸟飞处，淡然秋云生。", "烟霞多变态，若与群峰争。涧响共趋壑，并作新泉声。", "即此旦暮气，将以移人情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二月二十日述怀","p":"","d":"明代","a":"刘崧","c":["别时曾赋落梅花，江上风寒燕子斜。过却清明三日雨，荼䕷亭上客思家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鄜台","p":"","d":"宋代","a":"杜纯佑","c":["两载低眉著小冠，一台高築地平宽。", "向阳花木齐教放，天下无春似此间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红 仙吕","p":"","d":"宋代","a":"周邦彦","c":["昼日移阴，揽衣起、春帷睡足。临宝鉴，绿云撩乱，未忺妆束。", "蝶粉蜂黄都褪了，枕痕一线红生肉。背画栏、脉脉悄无言，寻棋局。", "重会面，犹未卜。无限事，萦心曲。想秦筝依旧，尚鸣金屋。", "芳草连天迷远望，宝香熏被成孤宿。最苦是、蝴蝶满园飞，无人扑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙 其五","p":"","d":"近代","a":"赵尊岳","c":["懊恨当楼一抹山。为谁空翠约轻寒。杜鹃声里日长闲。", "芳约总随幽梦远，倦云莫误锦书还。半灰心字惜香残。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"即席点韵赋方砚","p":"","d":"宋代","a":"赵必象","c":["一片端溪云，至宝俗眼惊。", "体方而质刚，翰林叨宠荣。", "楮君同出处，松侯难弟兄。", "紫肝马肤润，绿晕鸲肯明。", "自笑谪仙狂，曾倩妃子擎。", "我爱清庙瑟，人吹高门笙。", "龙尾与凤咮，圆巧相逢迎。", "吾友管城公，奚假乎猩猩。", "留此镇山房，移文鸥鹭盟。", "好方已成癖，焉用圆为卿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄昭德兄弟","p":"","d":"宋代","a":"晁说之","c":["莫言无合亦何伤，旅雁卑飞怯稻梁。", "南亩荒芜嵩少远，却来楫口祭勾芒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和庞丞相","p":"","d":"宋代","a":"宋祁","c":["顾我支离甚，惟公念不才。", "朱颜为列郡，白发入中台。", "阁道通天禄，宫门拂斗魁。", "论班元后郑，作赋或延枚。", "病肘垂杨老，危心一橹摧。", "根愁江北变，叶喜洛阳来。", "自昔边州重，当年蜀驭催。", "烧烽看朔漠，扪井歷崔嵬。", "粗可繙前史，何能调禁财。", "流光成浩荡，孤宦易嫌猜。", "曲外悲絃剩，机头谤锦开。", "无功惭远志，有吏笑然灰。", "左辖真虚忝，仙曹复滥陪。", "门鶋愁眩转，轩鹤老毡毸。", "倾否知攸往，成章恧所裁。", "贾生空问卜，楚客但劳媒。", "特召依明主，生还揖上台。", "缇油观册府，巾履记翘材。", "长跪怀人句，徐传道旧杯。", "今兹宣父冶，终得铸颜回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"惜分飞 忆从二姑","p":"","d":"清代","a":"储慧","c":["欲别还期相聚首。记得叮咛时候。一去音沉久。病馀弱骨摧残否。", "匪石贞心终自守。荼毒怎生禁受。玉质应非旧。连宵梦见分明瘦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吊王勃用达此韵","p":"","d":"明代","a":"释函是","c":["高阁凌霄尚壮哉，何人风雨渡江来。影沈湖水秋烟冷，韵遏匡云碧嶂开。", "多艺如君应薄命，閒情似我亦怜才。遥知万古长天色，一度登临恨一回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上陈县尹二首","p":"","d":"宋代","a":"刘应李","c":["温公宅子富公池，并入尧夫户不知。", "百亩但添官里赋，一编惟说橐中诗。", "自怜老去无能役，正恐儿成不了痴。", "有口尚能夸尹在，莫教白发困行移。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"随咏绝句一组 其十","p":"","d":"当代","a":"添雪斋","c":["曩日海风初起时，梦中心外两难支。非非是是既如幻，怎地相离悲复悲？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄伯兄季质及诸弟 其三","p":"","d":"明代","a":"金幼孜","c":["金台为客动经年，北望乡山万里天。书札久无朋旧问，官居惟有老亲怜。", "白云渺渺西江外，归雁翩翩落日边。早晚淦头逢驿使，殷勤为我寄长篇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"相国清河王挽歌","p":"","d":"南北朝","a":"温子升","c":["高门讵改辙，曲沼尚馀波。何言吹楼下，翻成薤露歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郡中上元灯减旧例三之二而又迎送使客七首 其五","p":"","d":"宋代","a":"杨万里","c":["不是东风巧剪裁，如何春夜碧莲开。江城寂寞无歌舞，唤得梅花劝一杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和渊明饮酒二十首 其十八","p":"","d":"金朝","a":"赵秉文","c":["汉儒传注学，未为无所得。秦火少完书，岂免乌焉惑。", "后儒补罅漏，圣道稍开塞。俗士喜操戈，又一秦相国。", "且共欢一觞，多言不如默。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"海棠四首 其三","p":"","d":"宋代","a":"杨万里","c":["竞艳争娇最是他，教人嫌少不嫌多。初酣晓日红千滴，晚笑东风淡一涡。", "自是花中无国色，非关格外占春窠。开时悭为渠侬醉，却恨飘零可若何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄南浦谪官","p":"","d":"唐代","a":"郑谷","c":["多才翻得罪，天末抱穷忧。白首为迁客，青山绕万州。", "醉欹梅障晓，歌厌竹枝秋。望阙怀乡泪，荆江水共流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹤","p":"","d":"宋代","a":"张咏","c":["共怜洁白本天姿，纵在泥尘性不卑。", "况是稻梁厌足日，好寻烟月却归时。", "迹参诗雅何年尽，名击仙经四海知。", "应到昆丘指来历，曾陪鸳鹭浴华池。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"信士画真请赞 其一","p":"","d":"宋代","a":"释印肃","c":["非迷非悟，谁强名模。无相三昧，不受涂糊。越色超声无个事，连声不断念苏卢。", "眉芒动处千光含，自肯除非大丈夫。持心应不失，谋事便忘真。", "谁识元明宝，虚劳几度春。因见普庵老，示我体皆纯。", "但依无著性，性幻在逡巡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"以菊花饷恽薇孙学士诗来用渊明自拟作此答之 其七","p":"","d":"清代","a":"李希圣","c":["北伐经年走传车，刘生批答苦纷挐。閒情赋罢无馀事，来倚西风看菊花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小松","p":"","d":"唐代","a":"章孝标","c":["爪叶鳞条龙不盘，梳风幕翠一庭寒。", "莫言只是人长短，须作浮云向上看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和张二十五春日见寄五首 其一","p":"","d":"宋代","a":"范祖禹","c":["绰约花无语，间关鸟自吟。及时须赏玩，风雨不能禁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖西杂感诗 其十二","p":"","d":"宋代","a":"释智圆","c":["白犬宵行似有情，为防暴客到天明。近来守禦无功绩，不吠人形只吠声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杏花疏雨洒香堤","p":"阮郎归","d":"清代","a":"佟世南","c":["杏花疏雨洒香堤，高楼帘幕垂。远山映水夕阳低，春愁压翠眉。", "芳草句，碧云辞，低徊闲自思。流莺枝上不曾啼，知君肠断时。"],"tags":["婉约", "妇女", "春愁", "相思"],"z":"","y":"注释 翠眉：即翠黛。古代女子用螺黛（一种青黑色矿物颜料）画眉，故称眉为“翠黛”。","s":"","k":"词"},
  {"t":"金花叶 赠徐安神","p":"","d":"元代","a":"马钰","c":["欲要灵明莹彻。向心上、速宜解结。便莫受、家缘火＊弃妻男产业。逞俊宁如养拙。引龙虎、休教急切。自然悟、神仙妙诀。本来真难灭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋宵吟","p":"","d":"清代","a":"蒋敦复","c":["夜漫漫，月皎皎。小阁湘帘深悄。银河影、乍转向疏桐，乱雅惊晓。", "瘦罗衣，冷翠葆。坠叶纷飞林表。秋声起、感一片清商，暗蛩衰草。", "莫是欧阳，恨作赋、年华渐老。低围银烛，懒展瑶编，绣幕篆烟绕。", "玉漏三更早。画角沈沈，天际雁杳。者吟怀、写入琴丝，阶下红鹤又睡了。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东观读未见书","p":"","d":"宋代","a":"黄庭坚","c":["汉规群玉府，东观近宸居。", "诏许无双士，来观未见书。", "皇文开万卷，家学陋三馀。", "竹帛森延阁，星辰绕直庐。", "诸生起孤贱，天子自吹嘘。", "愿以多闻力，论思补帝裾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"朴景绰","c":["胜事年年传习久，盛观全属远方宾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"青原台","p":"","d":"宋代","a":"洪刍","c":["高台梯空上云烟，宴坐城郭窥山川。凫汀鹤渚江在前，青原入望山苍然，蓦波轻泛一叶船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿栎堂前小山峰凌霄花盛开葱茜如画因名之曰凌霄峰 其二","p":"","d":"宋代","a":"范成大","c":["山容花意各翔空，题作凌霄第一峰。门外轮蹄尘扑地，呼来借与一枝筇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄长卿","p":"","d":"宋代","a":"邹浩","c":["乌衔霁色朝迎马，蟾吐澄辉夜照眠。日月于君已如此，不须星历问行年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"倅教授判官皆为东湖有赋次韵","p":"","d":"宋代","a":"程公许","c":["逶迤三径带重肖，心眼经营念厥初。", "问俗只须无事治，僝工适际有年书。", "雪融趁急栽花柳，春到随宜辦果蔬。", "最喜城隅便来往，不嫌左走费台舆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居二首 其一","p":"","d":"元代","a":"行端","c":["山木交柯莎满庭，马蹄且不污岩扃。篝灯对雪坐吟偈，拥裓绕泉行课经。", "睡少每知茶有验，病多常怪药无灵。金园一岁一牢落，谁似孤松长自青。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宴琼林（上元）","p":"","d":"宋代","a":"黄裳","c":["霜月和银灯，乍送目楼台，星汉高下。爱东风、已暖绮罗香，竞走去来车马。红莲万斛，开尽处、长安一夜。少年郎、两两桃花面，有馀光相借。因甚灵山在此，是何人、能运神化。对景便作神仙会，恐云轩且驾。思曾待、龙楼俯览，笑声远、洞天飞斝。向东来、尤幸时如故，群芳未开谢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和元善郎中","p":"","d":"元代","a":"袁士元","c":["水馆春将晚，凭阑静自吟。蜂粘飞絮起，鱼噞落花沈。", "济世身无术，邻邦贼又侵。临风搔白首，空负读书心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酬刘员外月下见寄","p":"","d":"唐代","a":"章八元","c":["夜凉河汉白，卷箔出南轩。过月鸿争远，辞枝叶暗翻。", "独谣闻丽曲，缓步接清言。宣室思前席，行看拜主恩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶作","p":"","d":"宋代","a":"吕本中","c":["去年芳草又萋萋，休叹王孙犹未归。更见春深送春雁，三三两两傍云飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"失题十七首 其六","p":"","d":"明代","a":"张弼","c":["都门长啸拂尘衣，乡思迢迢宦况微。桃李门墙新进满，桑麻墟里旧交稀。", "霞城卧听金鸡唱，雨洞吟看玉蝠飞。只恐平生著书手，未容持钓老渔矶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄鹄篇","p":"","d":"明代","a":"薛蕙","c":["飞飞者鹄，于彼苍天。大风阻斯，羽沉于渊。有松有柏，其枝嶟嶟。", "雨雪迨斯，化为枯薪。烈烈冬日，萧萧北风。虽有神龙，宛彼地中。", "天命有假，人谋有仍。嗟哉士人，曰予无能。舟利于川，弗利于陆。", "君子于行，维颠之速。相彼哲人，爰得我匹。且以啸歌，且以永日。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李参政","p":"","d":"宋代","a":"魏了翁","c":["黄云冉冉晓苍苍，閒倚平湖只自香。较似寒枝虽未至，依然风韵挟冰霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同闰师宿三门开化院二首 其一","p":"","d":"宋代","a":"魏野","c":["白莲社主碧溪人，同宿三门寺里云。四面涛声秋更怒，并床犹恐话难闻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"皖江","p":"","d":"明代","a":"李先芳","c":["皖江阴乍晴，鳞鳞秋浪生。", "岸回村树隐，潮落海云平。", "鱼米舟中市，人烟水上城。", "不须遥问渡，前路是浮萍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又五言","p":"","d":"唐代","a":"徐铉","c":["彩仗映花鞯，春庭散曙烟。", "毬飞皆应手，马骏不须鞭。", "仙乐飘云外，祥风近日边。", "筹多不虚发，制生在机先。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"示医卜逢松崖","p":"","d":"宋代","a":"朱继芳","c":["我生八月十五夜，清浅斜河浸月华。顾兔捣残千岁药，牵牛引动半天槎。", "自抛蓬海传方处，曾过成都卖卜家。今日相逢圆昨梦，一杯松下醉流霞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"青草湖","p":"","d":"宋代","a":"蒋之奇","c":["地无一勺水，安得有湖名。世事果如此，风波平地生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮 前题","p":"","d":"清代","a":"奭良","c":["春光明媚红窗晓。春风袅娜催啼鸟。灵鹊借填桥。一双金步摇。", "枣花帘子捲。云想衣裳暖。菱镜被人窥。翠螺深浅眉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新凉理故书有感二首 其二","p":"","d":"宋代","a":"刘克庄","c":["空花瞥过似浮荣，海水难湔是恶名。功比禹轲真学者，罪浮桀纣亦书生。", "国师族覆惭家训，太尉朝危悔宦情。束起陈编呼伯雅，胸中磊磈暂浇平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶兴","p":"","d":"清代","a":"弘历","c":["埙篪兰茝自人伦，衅梗交尤叹葛巾。蜀道易难若反掌，达夫太白总痴人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寒夜与家人坐语忆客中时","p":"","d":"明代","a":"高启","c":["茅屋夜灯青，竹庭寒雪白。", "不对室中人，依然去年客。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽国史侍读李公仁父","p":"","d":"宋代","a":"喻良能","c":["大名垂宇宙，秀气发岷峨。", "学比渊云赡，才方贾马过。", "九朝资直笔，二子振贤科。", "已矣流芳在，千秋保不磨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有客","p":"周颂","d":"先秦","a":"佚名","c":["有客有客，亦白其马。有萋有且，敦琢其旅。有客宿宿，有客信信。", "言授之絷，以絷其马。薄言追之，左右绥之。既有淫威，降福孔夷。"],"tags":["诗经", "宴会", "乐歌"],"z":"客：指宋微子。周既灭商，封微子于宋，以祀其先王，微子来朝祖庙，周以客礼待之，故称为客。\n亦白其马：亦，语助词。白为纯洁之色，殷商尚白，以白马为美，故来朝作客也乘白马。一说白马是客人带来的礼物。\n有萋有且（jū）：即“萋萋且且”，形容随从众多的样子。\n敦琢：意为雕琢，有选择美好之意。雕琢本为治玉之名，这里形容其随从众臣都是贤者。旅：通“侣”，指伴随微子的宋国大夫。\n宿宿：住一夜谓之“宿”，宿而又宿，则是两夜。\n信信：住两夜（再宿）谓之“信”。或谓宿宿为再宿，信信为再信，亦可通。\n言：语助词。授之絷（zhí）：给他绳索。絷，绳索。\n絷：本义为绳索，用作动词。此处是说给他绳索，绊住马足，表示要留住客人。\n薄言：发语词。追：意为饯行，也可以解为追送。\n左右：指天子之左右群臣。绥之：安抚客人。\n淫：盛，大。威：德。淫威，意谓大德，含厚待之义。\n孔：甚，很。夷：大。","y":"远方客人来造访，驾车白马真健壮。随从人员众且多，个个品德都贤良。客人已经住两天，多住几天增感情。给他拿条绊马索，斑竹马儿不让行。客人走时远远送，左右热情慰劳他。既用大德来待客，上天降福多又大。","s":"","k":"诗"},
  {"t":"六一堂","p":"","d":"宋代","a":"范令闻","c":["□□□□法，□□□□□。", "□□□□□，□□□雪人。", "□□□□照，□□江汉炳。", "灵□□物□，生五色虎□。", "□山□长□，唁□□□□。", "□简三□秩。满□中□□。", "然囊衣度云，栈□□□与。", "七贤□襁负，中□□金产。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再游灵隐寺","p":"","d":"明代","a":"张宁","c":["三月春深日日晴，桃花未落柳阴清。素罗衣薄松风淡，斑竹兜轻石路平。", "盛世多才惭独往，客游无处写閒情。倦来更欲缘溪步，为借寒流一濯缨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词 其七十七","p":"","d":"宋代","a":"赵佶","c":["戎裘殊丽学弯弓，十指纤柔力未充。多被朋侪齐谑笑，强颜无奈脸莲红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过许金声瓢所","p":"","d":"明代","a":"周瑛","c":["绿树深中白日迟，小瓢收得许多诗。百年天地藏形器，万状风云入笑嗤。", "沈宋每思传正印，许姚会见树降旗。双旌偶上临川道，重倚阑干有所思。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"听凯三首 其二","p":"","d":"明代","a":"陶益","c":["跃马阑街卸铁衣，屠牛倒酒耀兵威。凯歌莫踏城头月，犹有同仇逐梦归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"四时田园杂兴四首 其二","p":"","d":"清代","a":"曹家达","c":["散发当微凉，林木暧朝景。流连溪上花，忽见青山影。", "何处求黄虞，结念在庐井。邻翁日夕过，为言当习静。", "有田付孙子，租税出半顷。卧听水车声，俟此清昼永。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"官池即事","p":"","d":"宋代","a":"赵蕃","c":["偃薄虽兹驿，相羊赖此亭。鸟飞微破縠，鱼动暗冲萍。", "岂但忧怀惬，还能倦眼醒。独馀春草梦，才尽不能灵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"百一诗 其二十四","p":"","d":"魏晋","a":"应璩","c":["小儿抚尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙","p":"","d":"清代","a":"浦梦珠","c":["记得伤春经病起，日长慵下妆楼。慧因悔向隔生修。", "草偏栽独活，花未折忘忧。", "一幅生绡窗下展，亲将小影双钩。画成未肯寄牵牛。", "只缘描不出，心上一痕秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同石元规讲鹍鹏偶书","p":"","d":"宋代","a":"张继先","c":["翱翱数仞间，何异九万里。", "大道荡无名，无彼亦无此。", "倬哉元规翁，斯言迨尽矣。", "一物自太极，志士摽高拎。", "鹏乎与蜩鸠，涉辩非至理。", "有形相变化，不出六合里。", "飞跃涉程途，底用嘲远迩。", "乃识逍遥游，潀远发玄旨。", "讲罢四窗闲，忘言空隐几。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鸳鸯湖棹歌 其四十一","p":"","d":"清代","a":"朱彝尊","c":["秋灯无焰剪刀停，冷露浓浓桂树青。伯解罗衣种罂粟，月明如水浸中庭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋","p":"","d":"元代","a":"李裕","c":["待月滦水上，天寒月无魄。重云委城隅，秋色连径白。", "北邻有嫠妇，南邻足愁客。昏灯照梦魂，风雨满沙碛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题朱四郊墅","p":"","d":"宋代","a":"宋祁","c":["菌阁平窥倚杵天，绮塍鳞隰逗春泉。", "谁将六国黄金印，拟换东周二顷田。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋夜思家","p":"","d":"清代","a":"杨自牧","c":["故园归计惜蹉跎，残暑初消白露过。清角孤城知夜寂，寒蛩四壁觉秋多。", "愁中短梦悲难就，客里流光奈促何。卧起张镫还独坐，空将《九辨》数吟哦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初夏湖山 其二","p":"","d":"宋代","a":"张埴","c":["今朝二供亦相宜，眼底忘忧粲是诗。有恨春风不相待，山林著在日长时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"木瓜铺短歌","p":"","d":"宋代","a":"陆游","c":["鼓楼坡前木瓜铺，岁晚悲辛利州路。当车礧礧石如屋，百里夷途无十步。", "溪桥缺断水齧沙，崖腹崩颓风拔树。虎狼妥尾择肉食，狐狸竖毛啼日莫。", "冢丘短草声窸窣，往往精灵与人遇。我生胡为忽在此，正坐一饥忘百虑。", "五更出门寒裂面，半夜燎衣泥满裤。妻孥八月离夔州，寄书未到今何处。", "馀年有几百忧集，日夜朱颜不如故。即今台省盛诸贤，细思宁是儒冠误。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留别芜湖旧友","p":"","d":"清代","a":"黄辂","c":["于湖久住忽思家，胜侣分飞雁影斜。惜别一尊将进酒，含情两朵未开花。", "残年南陌无芳迹，旧迹东京有《梦华》。不待登程始惆怅，锦屏风外即天涯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五位颂 其一","p":"","d":"宋代","a":"释慧晖","c":["正中偏，混沌初分半夜天。转侧木人惊梦破，雪芦满眼不成眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋江八景 其四 落雁汀","p":"","d":"明代","a":"张宁","c":["云衢千里路漫漫，水碧沙明夜满滩。何事黄昏尚凝睇，伴人孤影隔江寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过荒村四绝 其二","p":"","d":"明代","a":"张家玉","c":["缥缈前途路欲迷，黑云留雨四村低。山灵似笑征人马，何事劳劳不住蹄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠王司谏文哲奉使北还兼柬吴世美司谏","p":"","d":"明代","a":"张诩","c":["李泌当年一献身，岂无高楫济长津。观风夷夏诗多采，补阙朝廷疏屡陈。", "阿阁九苞回彩凤，急风千丈挺霜筠。因君却忆吴司谏，曾以龙光射钓纶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"松隐坐上寄钱大参","p":"","d":"宋代","a":"曹勋","c":["闲里光阴不记名，曲勤宏度访公荣。", "五云洒翰情文厚，九节浮香琖色轻。", "宝箑含风清致爽，彩丝萦臂眼增明。", "团栾每得佳时醉，却恐宣麻下帝城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有美一人行","p":"","d":"宋代","a":"释文珦","c":["有美一人闲且都，天然自与常人殊。", "奔逸绝尘遗步趋，宛在大海之东隅。", "珠宫贝阙非凡居，鲛绡被体云霞裾。", "朝乘一鹤暮双凫，往来圆峤仍方壶。", "所交皆古真仙徒，赤松羡门及麻姑。", "共论妙道得道枢，天地万物指马如。", "人间岁月良易徂，别来眼暗齿发疎。", "山可泐兮海可枯，相思之念无时无。", "示好亦有明月珠，藏之怀袖不敢沽。", "屡欲致之乏飞鱼，侧身东望空踌躇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"曹提举荣上","p":"","d":"宋代","a":"释居简","c":["乡也才聆謦咳声，暗中摸索认轮囷。故家大雅元戎老，词学清流使节新。", "直指大门标俗子，莫嫌高贾著山人。紫荷琳馆君诸父，说项斯贤不厌频。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏清闲自在","p":"","d":"近代","a":"王瑞甫","c":["七夕优游避世哗，琴棋书画酒诗花。有时知己闲来往，听唱好歌效谢茶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿启宇兄花甲之庆","p":"","d":"当代","a":"陈仁德","c":["堂堂自是出群雄，独立苍茫唱大风。不尽波澜生笔底，无穷宇宙在胸中。", "壮图未已头颅白，噩梦曾经劫火红。蜀水巴山君共我，照人肝胆总相同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"出嘉峪关感赋","p":"","d":"清代","a":"林则徐","c":["严关百尺界天西，", "万里征人驻马蹄。", "飞阁遥连秦树直，", "缭垣斜压陇云低。", "天山巉[1]削摩肩立，", "瀚海苍茫入望迷。", "谁道崤函千古险？", "回看只见一丸泥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪","p":"","d":"清代","a":"弘历","c":["同云未肯放冬晴，冻雨均沾继瑞霙。著地消融无定态，随风飘舞可怜生。", "鸳楼有玉皆垂佩，鸡树非春率斗荣。卜麦慰馀饶韵事，竹垆文火煮三清。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和李相公早朝于中书候传点偶书所怀奉呈门下…郑相公","p":"","d":"唐代","a":"吕温","c":["禁门留骑吹，内省正衣冠。稍辨旂常色，尚闻钟漏残。", "九天炉气暖，六月玉声寒。宿雾开霞观，晨光泛露盘。", "致君期反朴，求友得如兰。政自同归理，言成共不刊。", "准绳临百度，领袖映千官。卧鼓流沙静，飞航涨海安。", "尽规酬主意，偕赋代交欢。雅韵人间满，多惭窃和难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南康元夕二首 其二","p":"","d":"明代","a":"李梦阳","c":["嘈嘈市鼓动，松月静吾门。灯火思今夜，风光满故园。", "天明淹舞袖，尘暗失游轩。老鬓江山异，愁看旌旆繁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百四十一首 其七十三","p":"","d":"宋代","a":"释师范","c":["克期取證，系缚盲驴。休夏自陈，且莫鬼语。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清明日余与诸友游招隐山寺酌酒宋氏园亭谒苏才翁墓而归","p":"","d":"宋代","a":"周孚","c":["小雨冥冥欲作泥，晨光不负老人期。绿阴苍藓初分坐，白石清泉共赋诗。", "酌醴焚鱼谩今日，卖刀买犊定何时。伤心紫阁飞杨老，千载茫茫只断碑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题海盐南馆","p":"","d":"唐代","a":"张祜","c":["故人营此地，台馆尚依依。黑夜山魈语，黄昏海燕归。", "旧阴杨叶在，残雨槿花稀。无复南亭赏，高檐红烛辉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"解嘲十绝呈浩西堂","p":"","d":"宋代","a":"释绍嵩","c":["江湖放浪未宁居，处世真同逐队鱼。", "但愿一生长若此，时清不问命何如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次甬川东阁书怀 其二","p":"","d":"明代","a":"霍韬","c":["云窦漏光锦碎铺，厂楼长夏寱鸿都。侧身左顾浅鹏窟，醒梦前柯笑蚁图。", "静水蒹葭闲豢鹤，趁时粱稻惯搂凫。秃翁握网支矶立，嫚问鱼多孰与湖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"𨻧隍舟行纪事二十韵","p":"","d":"明代","a":"林熙春","c":["愧予之才匪济川，徒怀击楫发垂肩。一岁两移何忝窃，盟心欲报丹扆前。", "四月望日携琴剑，凤城三朝始发船。沿江狎客勤杯酒，迟迟始达𨻧隍滨。", "𨻧隍为别二方伯，孝廉亦多列肆筵。筵上飞蛾为兆雨，雨剧天与水相连。", "须臾摧裂山陵变，农人何处问桑田。牛羊比屋浮江下，沉灶产蛙突少烟。", "此时觅夫夫避水，邮吏犹且减夫钱。强觅数夫先眷属，眷属乘风似有缘。", "岂期敝舟犹留滞，相违两日不相联。稚儿稚女啼饥切，相对呼爷眼望穿。", "只得贾勇追前去，无奈登矶若登天。缘木攀藤声震地，游水牵绳苦万千。", "中流得寸犹失尺，一篙无计可周旋。舟中惊怖念菩萨，榜人失色詈长年。", "一朝雨歇风涛息，眷属聚首北溪边。北溪庄人具鸡黍，相与持醪并击鲜。", "自是呼童为刻烛，率尔长歌独扣舷。但愿修途长迪吉，五云指日丹心然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自勉","p":"","d":"宋代","a":"陆游","c":["归老宁常逸，时时学荷鉏。", "室蜼无长物，圃尚有余蔬。", "壮志诚衰矣，贫居亦晏如。", "为农当世业，安用筑门闾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游海珠寺 其一","p":"","d":"明代","a":"伦以诜","c":["神人驱石立，涌出水晶宫。弱水无人到，蓬山有路通。", "潮声喧极浦，海色净遥空。解障颓澜势，江流一柱中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"灾怪","p":"","d":"宋代","a":"晁说之","c":["几岁庙堂生物怪，一朝胡虏应天灾。颇闻北斗光芒见，未见东京消息来。", "志士此时忧国泪，将军他日望乡台。世间如有严夫子，时命应须更可哀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"独吟二首 其二","p":"","d":"明代","a":"胡俨","c":["樗栎材虚拱，桑榆景已残。天涯春色远，窗下雨声寒。", "独自空玄守，何人问字难。蔷薇花又发，却笑酒杯干。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"昼夜乐","p":"","d":"清代","a":"袁克文","c":["弄花人在云飞处。扑香尘、英英舞。丹涡细透新霞，素睐轻横宿露。", "薄薄娇羞留不住。算分明、握云揉雨。红影落鲛绡，记鸳鸯帘幕。", "五更月褪纤纤树。断肠时、重凝伫。云天不见眉痕，绿蜡尽摇愁缕。", "无那微春随梦去，怨西风、未团欢聚。何计问星娥，占银河旧渡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和鲁望晓起回文","p":"","d":"唐代","a":"皮日休","c":["孤烟晓起初原曲，碎树微分半浪中。湖后钓筒移夜雨，", "竹傍眠几侧晨风。图梅带润轻沾墨，画藓经蒸半失红。", "无事有杯持永日，共君惟好隐墙东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春光好 其六","p":"","d":"唐代","a":"欧阳炯","c":["芳丛绣，绿筵张，两心狂。空遣横波传意绪，对笙簧。", "虽似安仁掷果，未闻韩寿分香。流水桃花情不已，待刘郎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和刘后村梅花百咏","p":"","d":"宋代","a":"方蒙仲","c":["扫空习气尚余狂，岂不怀思拾众芳。", "花里素王真足贵，橘中皓叟更无香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别林和卿 其一","p":"","d":"宋代","a":"曾丰","c":["夜榻无高枕，秋灯有短檠。嗜书如女色，敲赋若金声。", "岂是长贪者，何其太瘦生。功名犹欠子，子不欠功名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"百字令 和厚庄前辈灵峰摩岩石拓原韵","p":"","d":"近代","a":"夏承焘","c":["巨灵孤擘。问何年推出，撑空岩壁。劫火烧残山骨冷，丹篆犹摩拳石。", "云护精灵，天开图画，奇句江山辟。银笺重拓，墨花还绣苔碧。", "我羡老去刘晨，朅来丘壑，爱着寻幽屐。断碣残碑闲送日，何似岣嵝邹峄。", "胜地神游，故山春到，梦境迷仙迹。何时鸾背，和公云外吹笛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"妾薄命六首 其一","p":"","d":"宋代","a":"林景熙","c":["盈盈梁家姝，奕奕晋朝使。斛珠不论赀，得备巾栉侍。", "一笑金谷春，列屋俱敛避。岂知锦步温，巳复为愁地。", "念主惠妾深，缘妾为主累。楼头风雨深，残花抱春坠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"经冶城忆亡友盛仲交","p":"","d":"明代","a":"欧大任","c":["苍润轩犹故，斯人不可招。如何西序客，老作大城樵。", "书带秋零落，床琴夜寂寥。一编封禅草，谁奏圣明朝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秀州夜泊","p":"","d":"明代","a":"胡奎","c":["回舻泊晚渚，暂息嘉树阴。清飙散狂澜，纤月生远岑。", "悠悠归岫云，交交度水禽。同舟遂幽赏，玄谈惬素心。", "况兹水凉夕，觞至时一斟。道合理无忤，怡然澹冲襟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶","p":"","d":"宋代","a":"葛天民","c":["黛拂双粉衬毫，翅烘晴日伴相遭。", "戏勾穉子从花远，恐惹游丝莫斩高。", "栩栩倏来仍易散，深深交舞为谁劳。", "吴王花草腾王笔，千载风流敌楚骚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"龙门","p":"","d":"元代","a":"袁桷","c":["瀚海双龙铁鳞甲，卷壑挐云蹲冀阙。千泉百道凑东南，急雨翻空迸晴雪。", "古言神禹功最多，导山凿石疏九河。幽都之地不复顾，乃使双龙下地成盘涡。", "阴风何飕飕，磅礴太古秋。崩崖落车炮，怪木森戈矛。", "碎沙晴日铺金麸，云是昔日当关挽劲之仆姑。寒泉组练结九曲，亭午赫日光模糊。", "车声何辚辚，昨宵急水迷无津。垂堂之言犹在耳，游子商人行不已。", "子规彻天呼我归，翠华北幸那得辞。龙门之石高不磨，泚笔书我龙门歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洗心亭","p":"","d":"明代","a":"罗伦","c":["一片灵台百染污，天将明月与君孤。源头活水依然在，洗得汤铭一字无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用前人韵招山行以春为期","p":"","d":"宋代","a":"文天祥","c":["扫残竹径随人坐，凿破苔矶到处棋。", "一水楼台开晓镜，万山花木领先春闱。", "雪中便有回舟兴，林下岂无烧笋时。", "莫待东风吹柳絮，眼穿笼鹤绕湖飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵别王止仲 其二","p":"","d":"元代","a":"徐贲","c":["风风雨雨暗消春，杨柳官桥夜掩津。不是子规啼欲倦，扁舟知有未归人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六十 其二","p":"","d":"近代","a":"聂绀弩","c":["缘何除夕作生日，定为迎春来世间。渴饮中苏千里雪，饱看南北两朝山。", "西风瘦马追前梦，明月梅花忆故寒。此六十年无限事，最难诗要自家删。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵仇仁近暑中二首 其一","p":"","d":"宋代","a":"方回","c":["初减官河几许深，向来惟恐百城沈。晴阶近喜收檐滴，暑屋殊嫌乏树阴。", "妾妇齿牙工斗阋，比邻疟疠厌呻吟。悬知壮士无颜色，赖有同心可断金。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别张子言（四首）","p":"","d":"明代","a":"王廷陈","c":["我友驾言迈，去去之朔方。", "晨起趋中厨，为我具酒浆。", "长别在须臾，且愿尽杯觞。", "昔为骨肉亲，比翼云中翔。", "今当承乖违，邈若参与商。", "出门异乡县，居世如朝霜。", "世途转倾侧，良会安可常。", "羸马感人情，哀鸣衢路傍。", "悲风振乔林，瑟瑟伤肝肠。", "执手不能辞，泪下沾衣裳。", "恨无凌风翰，送子还故乡。¤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"出山逢耿湋","p":"","d":"唐代","a":"卢纶","c":["云雪离披山万里，别来曾住最高峰。", "暂到人间归不得，长安陌上又相逢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有赠四首 其四","p":"","d":"明代","a":"王彦泓","c":["秋风长簟恨三年，续命曾闻唤小怜。已向绿珠称弟子，倘容张硕伴神仙。", "筵前笑顾樱桃掷，烛下偷分茉莉穿。端似悼亡唐后主，见伊枝叶又情牵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"己亥杂诗 其二六三","p":"","d":"清代","a":"龚自珍","c":["道韫谈锋不落诠，耳根何福受清圆？自知语乏烟霞气，枉负才名三十年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"避暑山庄三十六景诗 其十九 暖溜暄波","p":"","d":"清代","a":"弘历","c":["遥源苍峤中，暖溜早称功。涤荡蒸云似，灵奇仙药同。", "醴泉闻建武，温谷艳新丰。利物天然泽，无誇辟沼宫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"永王东巡歌十一首 其八","p":"","d":"唐代","a":"李白","c":["长风挂席势难回，海动山倾古月摧。君看帝子浮江日，何似龙骧出峡来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和乐周弟寄韵 其七","p":"","d":"明代","a":"郭棐","c":["百粤山川第几层，重来有约漫追寻。满台花雨飘僧梵，两岸岚光拥翠岑。", "贝叶捲时猿献玉，老僧禅罢客弹琴。登临欲上和光洞，踏破苍苔发浩吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"烟波即事","p":"","d":"宋代","a":"陆游","c":["落雁沙边艇子斜，分明清梦上三巴。", "眼明一点炊烟起，不是渔家即酒家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"度凤凰岭次董叔重韵","p":"","d":"宋代","a":"程洵","c":["连山翳寒云，孤松秀巍岭。松吟石漱水，山露髻撑顶。", "我行亦何事，岁晏苦凄冷。频有同心人，哦诗味隽永。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宝鼎现（上元上江西刘枢密）","p":"","d":"宋代","a":"石孝友","c":["雪梅清瘦，月桂圆冷，天街新霁。想帝辇、三朝薄暮，催促烛龙开扇雉。正拜舞、捧玉卮为寿，花满香铺凤髓。罄禹穴、胥涛万顷，春入南山声里。", "鼎轴元老诗书帅。体宸衷、双奉亲意。勤色养、行春惜花，夜欢宴、瑶池衣彩戏。鼓淑气、遍湖山千里。惊破慳红涩翠。笑那个痴儿无赖。", "打得金鱼坠地。休念太守当年，曾手把青藜照字。对珠帘云栋，收拾太平歌舞辍。庆母爱、小宽王事。余沥□肠，看不日、归步沙堤，又赞重华孝治。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苦热","p":"","d":"明代","a":"穆孔晖","c":["赤日长天昼掩扉，冰纨碧簟起炎威。病馀未爱强加饭，客至还愁暂着衣。", "案上青蝇难寂寞，阶前瑶草失芳菲。拟从禦寇乘风去，却向山阴理棹归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂兴 其二","p":"","d":"宋代","a":"利登","c":["我昔游蓬莱，道过昆崙山。青壁峭千仞，中分两径前。", "上径险且难，行可求神仙。下径极夷易，蛇虺交蜿蜒。", "毫釐一殊轨，安危异千年。弃之从上征，高步追飞鸾。", "勿谓下途易，下途前更艰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南山罗汉赞十六首","p":"","d":"宋代","a":"黄庭坚","c":["四十九年大教主，波旬请故入涅盘。", "佛身常寻法界住，非其境界故不见。", "未法众生蒶福田，众魔染衣汗戒律。", "稽首那迦住世间，令我常生遇佛想。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"除夕","p":"","d":"清代","a":"陈曾寿","c":["沉阴飞大雪，万里接龙庭。惨黩兼幽显，情怀兀醉醒。", "星光隐辰极，花影淡湘灵。欲说心中事，悲凉不可听。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题邹一桂写生卷九首 其八 秋葵","p":"","d":"清代","a":"弘历","c":["秋风閒砌发幽花，处士图珍驸马家。直笔不惭瓶史处，倾阳曾未逞春华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"客怀六首 其四","p":"","d":"明代","a":"边贡","c":["鬓丝端为别兄皤，魂梦真如道路何。滇海万峰秋雁少，楚江千里月明多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和昌言官舍十题 其八 甘菊","p":"","d":"宋代","a":"司马光","c":["野菊细琐物，篱间私自全。徒因气味殊，不为庖人捐。", "采升白玉堂，荐以黄金盘。愿若南阳守，永扶君子年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨","p":"","d":"清代","a":"弘历","c":["宵旦阴云酝酿佳，沛然灵澍落辰牌。不徐不疾溜垂细，过午过申潦积皆。", "继泽还欣胜前此，流膏所喜达根荄。稻塍黍陇芃生意，慰矣惟饶敬畏怀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"御阁","p":"端午词","d":"宋代","a":"晏殊","c":["献寿竞为长命缕，迎祥还佩赤灵符。", "端门漏永晨曦上，飒飒薰风绕帝梧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽钱祖耄姑丈二首 其二","p":"","d":"近代","a":"孙保圻","c":["少日从姑分最亲，履綦泯绝隔音尘。神方未验陶宏景，占貌空怀杜子春。", "悲恋龙髯心上事，崚嶒犀角眼中人。年来旧德多凋丧，愧剩飘零不肖身。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王太博 其二","p":"","d":"宋代","a":"林希逸","c":["以赋鸣虽早，襟怀实似虚。出弹齐士铗，归读乐轩书。", "丹桂攀殊苦，黄粱梦不如。在时同手足，入念每沾衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟古","p":"","d":"明代","a":"钟芳","c":["志士委荣宠，抗节清霄岑。繁英掇零露，栖息谐素心。", "夷随有前期，遐风谅斯寻。何为风中絮，飘飘堕春阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻东轩讣 其二","p":"","d":"宋代","a":"刘克庄","c":["位逼将求说，书来欲铸颜。柰何化鹤去，不见珥貂还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟权龙褒体赠鄠县李令及寄朝右（李令因之休官）","p":"","d":"唐代","a":"郑愚","c":["鄠县李长官，横琴膝上弄。不闻有政声，但见手子动。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沁园春 其二 再和韵","p":"","d":"宋代","a":"方岳","c":["客有谓予，野眺何如，予曰可哉。乃携酒怀鱼，共寻秋径，乘风化鹤，感慨荒台。", "能几重阳，已无老子，人世何妨笑口开。苍崖下，有二犁膏雨，十亩汗莱。", "掉头只么低回。彼轩冕时来自傥来。夜半饭牛，无心扣角，霜前擘蟹，有手持杯。", "野屋云深，帝城书断，坚卧三年一砚埃。赢得底是，唐诗晋帖，潜菊逋梅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"记杂画 尝醋图","p":"","d":"宋代","a":"刘克庄","c":["酿者不沾唇，旁观吸者颦。翁真堪宰相，妪亦可夫人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题墨桃","p":"","d":"明代","a":"程本立","c":["天台美人红雪肌，玉洞春深曾见之。今日风沙吹面黑，出山不似在山时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鱼樵图","p":"","d":"明代","a":"孙绪","c":["抱膝余长吟，息肩君赏音。歌罢解携去，山高江水深。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陶斋招为柬坡生日节庵新至信宿即归陶斋有诗索和","p":"","d":"清代","a":"陈宝琛","c":["谪仙非谪乃其游，坡公故是仙者流。谷神出世八百秋，禁网所脱声画留。", "陶斋好古苏斋侔，梁髯新来趣命俦。图书色香逾荐羞，陈以飨客餍客求。", "嗟公于世生何雠？死作奎宿谗始休。已灰之木不系舟，孰者龟鹤孰蜉蝣？", "往来人海髯如鸥，此会欻若风中沤。主人诗好难为酬，雪大能上西山不？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈五首","p":"","d":"宋代","a":"释弥光","c":["一九与二九，相逢不出手。", "冻得鸱吻头，面南看北斗。", "诸禅人，晓不晓，", "地炉火冷莫嫌寒，更有樵夫赤脚走。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"李寿朋","c":["十日醉如何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自仙人岩至梓树坑","p":"","d":"清代","a":"姚燮","c":["玉女搴水帘，睨我过云峤。瘦石随吟肩，撑空竞苍峭。", "瑶林鹤振虚，兰门日衔照。山气清霏花，潭光静生缟。", "松梦猿独知，藓迹马谁到？旷象高溢秋，寂籁下缄妙。", "洞焉豁古天，森然伟灵造。自此千奇投，愿持一筇报。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登郁孤台 其二","p":"","d":"宋代","a":"韦骧","c":["去年秋宿洞庭湖，今日登临在郁孤。两处风流皆胜绝，一身奔走亦崎岖。", "光摇二水看云断，翠滴千山爱日晡。吏役不容清兴足，放船回首望城隅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岁丁丑曾步韵寿一如王君七十，意有未尽，复成五古一首","p":"","d":"清代","a":"赵廷赓","c":["我续古稀吟，不尚谀词贡。先生松鹤姿，秉质尤厚重。", "肇锡鸿逵爻，爰居为粪巷。老宿仰经师，文史殊足用。", "桃李盈门墙，济济英才众。衣钵盛流传，群钦铸颜孔。", "清况谱茶经，旗枪分雅供。优游乐天真，知己日过从。", "忆昔小蓬莱，叨陪鲤对共。五十馀载间，仆未解尘鞚。", "羡君乐齐眉，更有谢家凤。兰玉森庭前，含饴孙载弄。", "天伦乐事多，颐养福天种。即此卜遐龄，聊代椒花颂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"头陀僧","p":"","d":"唐代","a":"陆龟蒙","c":["万峰围绕一峰深，向此长修苦行心。", "自扫雪中归鹿迹，天明恐被猎人寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王守生辰七月十四日","p":"","d":"宋代","a":"廖刚","c":["月华浑似十分圆，玉露金风处暑天。虎节端光凌碧汉，龙台佳气满晴川。", "扬鞭省闼声名籍，拥旆侯籓福禄骈。会看黑头丹衮贵，伊周勋业老彭年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"示龟山平老 其二","p":"","d":"宋代","a":"韩驹","c":["水横绝浦曾争渡，浪打船头又少留。安得一舟淮上钓，水生水落任沉浮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"以螃蟹寄高紫微践约侑以雪醅时犹在黄冈","p":"","d":"宋代","a":"岳珂","c":["前朝无蟹惟有诗，亦复无酒供一郗。", "今朝有蟹仍有酒，极目征帆更搔首。", "古为乐事夸持螯，赤琼酿髓玄玉膏。", "菊花吹英好时节，况是九日钭登高。", "旌旗半江笳鼓发，不作诗人淡生活。", "待君净洗沙漠尘，归趁看灯更奇绝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠一上人","p":"","d":"宋代","a":"吕本中","c":["细褥纱幮卧软绫，岂知秋色到襄陵。饥乌乍定门门树，宝塔新晴夜夜灯。", "晚菜聊充肉一脔，残林才当饭三升。平生积懒成骄惰，惭愧空房独坐僧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题陈藏一水月梅扇","p":"极相思","d":"宋代","a":"吴文英","c":["玉纤风透秋痕。凉与素怀分。乘鸾归后，生绡净翦，一片冰云。", "心事孤山春梦在，到思量、犹断诗魂。水清月冷，香消影瘦，人立黄昏。"],"tags":["咏物"],"z":"","y":"首词的上片写女主人及其扇的特点。下片写扇上的水月梅图画。本词是咏女主人的扇，但女主人是谁？杨铁夫《吴梦窗词笺释》认为是去姬，他说：“此扇必去姬所遗物，为陈藏一所绘者。”俞陛云《唐五代两宋词选释》认为此词“为道女题扇而作”。吴文英词中是有为道女题扇之作的，如《朝中措·题阑室道女扇》。从本词内容来看，这是题陈藏一所藏或所绘的道女扇的一首词。\n\n  这首词的主旨是题扇，主要是歌咏扇上的“水月梅”图画。全词在描写扇的主人、扇的质料以及扇的图画时，都强调了它的清白、纯洁的特点。陈廷焯《白雨斋词话》说：“梦窗精于造句，超逸处，则仙骨珊珊，洗脱凡艳。”这首词正是具备这种超逸风格，词","s":"","k":"诗"},
  {"t":"忆帝京","p":"","d":"近代","a":"顾随","c":["木绵袍子君休换。毕竟眷深春浅。听说杏花开，却在深深院。", "可惜太深深，开了无人见。", "一阵阵、风儿回旋。几点点、雨儿萧散。长怪当年，道君皇帝，见了红杏肝肠断。", "不怨杏花红，却怨双双燕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙 其五 过分水河，和王仔园韵","p":"","d":"清代","a":"董元恺","c":["终古灵奇恢禹绩，中流河渎平分。云沙浩浩水粼粼。", "黄牛如断岸，白马暗通痕。", "南北维舟争报赛，九州万派知遵。安澜直自到天津。", "河清应献颂，海若尽称臣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送赵司空致政","p":"","d":"明代","a":"严嵩","c":["嶷然冠剑汉司空，出入三朝操履同。事忤贵人知节槩，心忧王室见清忠。", "俞章赐允皇仁大，荐剡留贤物论公。遥羡高踪去尘网，云霄万里一冥鸿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄许伯玉","p":"","d":"明代","a":"陈恭尹","c":["文章先代是宗工，君有无双国士风。百战功多沧海外，一官身老岭云东。", "越庭诗礼皆能学，爱客壶觞不说穷。凤峤松阴石湖月，至今人想许中戎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郊外","p":"","d":"宋代","a":"文同","c":["城市压压土，高原聊振衣。", "晚云多浅碧，秋树半深绯。", "江气杂轻霭，山光明落晖。", "因成求好景，更就野桥归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感遇诗三十八首 其四","p":"","d":"唐代","a":"陈子昂","c":["乐羊为魏将，食子殉军功。骨肉且相薄，他人安得忠。", "吾闻中山相，乃属放麑翁。孤兽犹不忍，况以奉君终。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词 其二十五","p":"","d":"唐代","a":"花蕊夫人徐氏","c":["新秋女伴各相逢，罨画船飞别浦中。旋折荷花伴歌舞，夕阳斜照满衣红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂咏十首 其六","p":"","d":"宋代","a":"方凤","c":["瑞世凤鸣阳，司晨鸡鸣丑。呶呶取人憎，乱蝉合缄口。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"醉公子","p":"","d":"清代","a":"秦昙","c":["香囊垂绣凤。是妾儿时弄。微物何足珍。怜他伴妾身。", "红绵著在里。扣上同心缕。一缕一相思。数来千万丝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"焦山寺","p":"","d":"明代","a":"陈琏","c":["江上焦山寺，匆匆未暇登。水环青一簇，树拥翠千层。", "两岸闻斋磬，中流见佛灯。昔人有遗迹，瘗鹤尚留铭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读史 其三","p":"","d":"元代","a":"吴当","c":["受命趋关定约时，鄛翁多算竟何为。可怜空碎鸿门玉，天下雄雌亦易知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟古四十一首 其十四","p":"","d":"明代","a":"薛瑄","c":["木腐虫蠹出，气乖疣赘生。曜灵一薄蚀，阴曀郁然兴。", "道术裂周季，纵横乱秦嬴。青牛既夙驾，白马亦时征。", "汜滥自涓滴，熺赫兆星星。多谢宋诸老，万古开昏冥。", "如何阳光发，尚自爝火明。寄语行路人，勿迷棘与荆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山中怀友 其五","p":"","d":"元代","a":"萨都剌","c":["卓荦恒山秀，相逢几抱琴。五年风雨别，四海弟兄心。", "岭外梅花远，山中桂叶深。定知嵇叔夜，高兴满云林。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东皋十首","p":"","d":"宋代","a":"晁补之","c":["城市何妨亦隐沦，贾君无意向红尘。", "东皋瓜豆如云处，慊我幽栖不卜邻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居五戒一戒讲学","p":"","d":"明代","a":"唐伯元","c":["我曰予贤，人曰予圣。果圣且贤，相悦而静。况汝之德，未满乡里。", "况汝之道，未行妻子。呶呶哓哓，盖不知耻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄燕中友人六首 其一 岭南黎惟敬","p":"","d":"明代","a":"胡应麟","c":["谁向风尘问谪仙，相逢贺监自飘然。青春画省追游地，白首金门侍从年。", "柳色乍分燕塞底，梅花长忆岭云前。佳期惨淡琼瑶隔，愁对孤城落日悬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南康邂逅江西吴运判 其二","p":"","d":"宋代","a":"刘过","c":["万里西征一叶舟，谁怜天地此生浮。初征秋浦雁飞处，又泊江南霜叶洲。", "贫困尽从归后见，雄豪半为病来休。十年心事閒搔首，荻雨芦风总是愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"刘兴祖","c":["谁能制长笛，当为玉龙吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠周山人 其一","p":"","d":"宋代","a":"陈深","c":["床头曾不置黄金，野褐纶巾善陆沉。七十康强疑有道，一毫荣辱不惊心。", "草根露冷沾芒屦，柏子烟清暖布衾。时启青囊看山水，行歌行入白云深。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王运同 其一","p":"","d":"明代","a":"郑真","c":["万里东流鲸海波，朝家盐赋有常科。草窝气湿苍烟暗，花𨢑光寒白雪多。", "已见神功回造化，还闻宽政蔼声歌。煌煌使阃看归骑，缥缈天风响佩珂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"接家书","p":"","d":"清代","a":"赵佩湘","c":["家书未到频先盼，乍接家书怯细看。莫道纸长嫌话短，客乡幸喜报平安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"原隰荑绿柳","p":"","d":"唐代","a":"温庭筠","c":["迥野韶光早，晴川柳满堤。", "拂尘生嫩绿，披雪见柔荑。", "碧玉牙犹短，黄金缕未齐。", "腰肢弄寒吹，眉意入春闺。", "预恐狂夫折，迎牵逸客迷。", "新莺将出谷，应借一枝栖。"],"tags":["柳树", "写景", "愿望"],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏舞诗","p":"","d":"南北朝","a":"何敬容","c":["因风且一顾，扬袂隐双蛾。曲终情未已，含睇目增波。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"竹","p":"","d":"宋代","a":"陈元晋","c":["吾敬王子猷，傲俗独爱竹。行止必与俱，情义均骨肉。", "云龙求友心，上下亦相逐。彼哉绝彝伦，乃戒桑下宿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"简熊松云","p":"","d":"元代","a":"瞿智","c":["西冈无奈景纯何，陶写新诗日渐多。宜似兰苕飞翡翠，每嗟荆棘长铜驼。", "日曛山崦收黄雾，秋入江风动白波。复忆松云老文学，醉乘箫凤肯相过。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄曹子方","p":"","d":"宋代","a":"韦骧","c":["度溪踰岭一何劳，霜鬓鬅鬙首屡搔。自愧晚年空碌碌，唯逢佳境且陶陶。", "会仙古观风流远，馆节新堂气象豪。不得与君同啸傲，强抽荒思引吟毫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"青县赠潘茂硕","p":"","d":"明代","a":"袁宏道","c":["竹叶遮人吏，公移只坐销。", "印床生木耳，廨含长蔬苗。", "贫邑多诗料，闲官有醉僚。", "一城不数武，容得几科条。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵和李根香","p":"","d":"清代","a":"吴妍因","c":["江城玉笛董生笳，古调高吟属李家。睹物不胜怀故国，悲凉又咏刺桐花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寒食访僧","p":"","d":"宋代","a":"郑文宝","c":["客舍愁经百五春，雨余溪寺绿无尘。", "金花开处鞦韆鼓，粉颊谁家斗草人。", "水上碧桃流片段，梁间新燕语逡巡。", "高僧不饮客携酒，来劝先朝放逐臣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"画 其二","p":"","d":"元代","a":"凌云翰","c":["扁舟与客共游遨，风月无边入彩毫。长为江山增感慨，后前两赋类庄骚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"介翁见示诞孙志喜之作次韵三首 其一","p":"","d":"明代","a":"王立道","c":["抱孙六十应非晚，裁得新诗续旧欢。宠埒金张开世胄，词高屈宋比衙官。", "宾筵胜拟金钱会，宫禁荣分襁褓完。台阁已传韦氏业，芝兰频向谢庭看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月抵京二首 其二","p":"","d":"明代","a":"卢龙云","c":["尚及三春候，重来万里人。辞家方在远，观国屡为宾。", "宦业难书竹，时情任积薪。长安真似奕，往事不须颦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟古七十首 其八 刘文学桢陪宴","p":"","d":"明代","a":"王世贞","c":["公子富令德，穷乐在清时。卜昼启初筵，丙夜犹未疲。", "丛篁夹文馆，碧萼缀丹梯。潜月青林端，万颖射金池。", "澄露滴华桐，薰风穆然吹。炮炙参差进，觞醴纵横飞。", "伎士慕新端，肉奋丝竹驰。渊鳞中踊跃，宿鸟无宁枝。", "冉冉东方曙，欢唱掩鸣鸡。冠盖散交衢，粉泽有馀施。", "畸客誇殊遇，叹息不可追。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"踏莎行","p":"","d":"宋代","a":"侯彭老","c":["十二封章，三千里路。当年走遍东西府。时人莫讶出都忙，官家送我归乡去。", "三诏出山，一言悟主。古人料得皆虚语。太平朝野总多欢，江湖幸有宽闲处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"恽道生画山水歌","p":"","d":"清代","a":"朱景英","c":["毗陵恽氏工作画，正叔本在道生后。正叔写生妙入神，何似道生挥毫如运帚。", "胸中邱壑蟠几许，落手寻丈等粒黍。笔底已无高房山，眼边不数米家虎。", "由来大巧无纤辞，讵有大力肯事轻描淡写为。窠臼尽脱笔墨外，不施皴染艺更奇。", "多君论画兼论文，读书读画同所云。愚意读画仍自读书始，俗工院体徒纷纷。", "世人但爱南田子，花叶工为没骨体。边徐而后叹独绝，寸缣尺素珍莫比。", "我获此幅赏其大落墨，是用作歌表奇伟。噫嚱吁，读画录中传久矣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"【中吕】满庭芳_寄友香笼锦","p":"","d":"元代","a":"任昱","c":["寄友", "香笼锦帏，歌讴白苎，人比红梅。风流杜牧新诗意，字字珠玑。桑落酒朝开绮席，杜陵花夜宿春衣。陶然醉，金勒马嘶，归路柳边迷。", "春暮", "云扃睡起，香销宝鼎，暖试罗衣。甫能宴罢兰亭会，又见春归。花片片翻成燕泥，柳依依也锁蛾眉。重门闭，绿阴树底，怕听杜鹃啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闽中郑君炎南仲两魁乡赋比自霅教为昌化簿","p":"","d":"宋代","a":"方回","c":["三山鹄袍十万众，两纪知名郑南仲。", "妙年官赋甲秋闱，一发辄中仍再中。", "岂知天地大变革，原夫八韵竟无用。", "虽然改尔亦得力，斗南斗北声价哄。", "黄金台降中书敕，水晶宫请博士俸。", "得人岂必泥古法，省场舍选同乡贡。", "儒风未尽弃端章，学徒尚多习弦诵。", "但苦官冷饭不足，三载诳腹虀百瓮。", "终更受代颇已久，始闻巨轴以诗送。", "定是弟子多贤才，吴兴先生实梁栋。", "即今佐邑号为簿，尹丞不殊权任重。", "况乃唐昌风俗淳，山深岁稔少争讼。", "丈夫讵皆作卿相，一命关系民疾痛。", "偏见私意勿力竞，潜转密移但微讽。", "方册频窥身尽贫，苞苴不纳心奚恐。", "崇卑有无置度外，时一极目天宇空。", "江东接壤异西浙，桑蚕春忙田晚种。", "樽俎盘馔极俭啬，无大牲脔及乳湩。", "吾闻易彖识时义，未妨枳棘栖鸾凤。", "聊复亦耳磨岁月，慎勿轻为棺粪梦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百二十三首 其七十一","p":"","d":"宋代","a":"释普度","c":["老瞿昙，眼孔小。一星半星容不得，说迷说悟何时了。", "衲僧分上那有许多般，雪晴海阔千峰晓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东城","p":"","d":"宋代","a":"滕塛","c":["东城有高楼，峨峨冠城阙。", "我来属昏暮，见此初上月。", "遥天罗江山，极目如霁雪。", "江山秀如此，岂不生豪杰。", "临风一高歌，达曙何由歇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同刘朔斋洲蒲涧谒菊坡祠","p":"","d":"宋代","a":"李昴英","c":["晓随丝辔饭僧坊，丞相祠堂一瓣香。", "试问神仙蒲九节，何如名德菊孤芳。", "高山仰止堪模楷，百世闻之尚激昂。", "我辈此来深有意，岂专泉石癖膏肓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"隐潭","p":"","d":"宋代","a":"楼钥","c":["灵潭深入白云堆，带雨春云为我开。", "乳石半空浑欲堕，瀑泉千尺正中来。", "两军酣战鼓鼙急，一雨生寒霹雳催。", "中有卧龙君勿狎，有时平地起风雷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岁暮雪中","p":"","d":"明代","a":"释函可","c":["四十风光一抹收，故乡望断岁如流。料因诃佛填冰狱，岂为修文上玉楼。", "雪尽埋时偏得句，天当崩后更无忧。当年六载行难满，殃及儿孙冷不休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"素尚斋","p":"","d":"清代","a":"弘历","c":["太古山中室，高秋时节天。有怀惟淡泊，无物不神仙。", "候暖林犹翠，露繁花益鲜。却嗤芥蒂者，动说俗尘蠲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"采桑子","p":"","d":"近代","a":"顾随","c":["水边点点光明灭，拾似春灯。恰似繁星。恰似游魂自在行。", "细思三十年间事，如此凄清。一个流萤。自放微光暗处明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中吕从野水部邀不赴赋谢","p":"","d":"明代","a":"王慎中","c":["宫云晓度湿晴沙，退食烟齐省树鸦。燕阙春回催玉羽，凤墀日暖映金花。", "文园不起茂陵卧，朔雪虚回剡曲槎。绮席瑶觞违命赏，露兰风草惜年华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"熏蚊效宛陵先生体","p":"","d":"宋代","a":"陆游","c":["泽国故多蚊，乘夜吁可怪。", "举扇不能却，燔艾取一快。", "不如小忍之，驱逐吾已隘。", "宁闻大度士，变色为蜂虿？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈","p":"","d":"宋代","a":"释怀祥","c":["南山高，北出低，日出东方夜落西。", "白牛上树觅不得，鸟鸡入水大家知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游胶山即赋长句","p":"","d":"清代","a":"安全","c":["胶山流览兴何如，曾访山中旧景无。料想纪游诗必富，敢掬胜迹效吴歈。", "两峰耸时恰相对，白云飞去黄云在。东湾萋萋草际天，西瞻磊磊石应拜。", "蜿蜒龙腿接凤凰，凤凰常伏龙亦藏。红叶满山飘不定，龙凤遍体呈文章。", "山行自北得幽胜，古木疏篁绕石蹬。桥锁香花供冶游，坞藏碎石足持赠。", "梵王宫殿忆当年，唐宋名流吟咏传。环翠上方两不见，一丛榛莽敛残烟。", "秋老青梧翠叶亸，黄菊欺霜野香播。金牛有迹牧童眠，石马无声樵叟坐。", "俯仰岩阿感古今，流连光景漫沉吟。侍郎废墓寒云聚，丞相荒祠夕照阴。", "窦乳涓涓注石罅，色清味美人争讶。宋时翁挺尝品之，九龙中泠乃其亚。", "枫叶芦花飘暮秋，幽崖潭水碧于油。当年砺剑人何在，今日临池石尚留。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戊寅八月送弟铣受室于笋峰宪长伍宋诸婿会于前溪里第菊节寿辰予以事先别敬赋此章","p":"","d":"明代","a":"符锡","c":["丈人才硕古人看，翻为明时爱惜难。豸历秋山澄月霁，舟横春雨酿溪寒。", "文章世济兰阶美，昼锦筵开菊露团。珍重百年才六□，乘鸾有客醉先拚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨后观瀑","p":"和靖州判官陈子从山水图十韵","d":"宋代","a":"魏了翁","c":["泽气蒸前山，起自肤寸微。", "竞看千丈瀑，不悟片云飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浩气吟 其三","p":"","d":"明代","a":"瞿式耜","c":["正襟危坐待天光，两鬓依然劲似霜。愿仰须臾阶下鬼，何愁慷慨殿中狂。", "须知榜辱神无变，旋与衣冠语益庄。莫笑老夫轻一死，汗青留取姓名香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"见月落秋空云敛波出悠然有感","p":"","d":"明代","a":"郭之奇","c":["从来不识汉江秋，湛湛枫林寄古愁。落日扁舟依绿屿，清宵万壑抱沧流。", "月方一见思其满，云自初生看及收。遂有波光迎夜色，因之凄绪发蘋洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹤林仙坛寺","p":"","d":"宋代","a":"黄庚","c":["古坛归鹤杳，野鹿自成群。", "岚气浮清晓，钟声出白云。", "树穿僧屋老，水到寺门分。", "人世无穷事，山中了不闻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"红梨","p":"","d":"清代","a":"弘历","c":["女夷侈神权，万卉争一日。娈彼红梨花，芳姿岂容閟。", "英英粲晓风，裳裳映书室。昨来珊网撑，今看银云栉。", "无香良已佳，侔色真难匹。静观悟梦华，兴会蜚吟笔。", "底须惜流阴，流阴不因厄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绝句六十四首","p":"","d":"宋代","a":"张伯端","c":["始之有作无人见，及至无为众始知。", "但见无为为要道，岂知有作是根基。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十二月二十七日大雪中过吉水小盘渡西归三首","p":"","d":"宋代","a":"杨万里","c":["雪吹醉面不知寒，信脚千山与万山。", "天甃琼街三十里，更飞柳絮与君看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"去年闻载扬在武林及余至而载扬","p":"","d":"宋代","a":"周紫芝","c":["与君一别几经秋，忽作脩文地下游。诗忆向来云态度，人今何在柳风流。", "西湖烟月生前恨，客路风霜晚岁愁。胜日交流半零落，数行老泪倩谁收。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金山","p":"","d":"宋代","a":"张蕴","c":["江身台殿切空云，夜月鱼龙影不分。", "八十老僧相引说，潮痕不上郭公坟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居杂诗九十首","p":"","d":"宋代","a":"曹勋","c":["下邑常寂寞，细履寒溪头。", "鱼鰕腥断岸，橘柚明晚秋。", "山色俨晴碧，溪光泛澄流。", "相思故人远，应过回雁洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"桃村寄题三首 其一","p":"","d":"宋代","a":"钱时","c":["春入桃村烂熳红，纷纷来觅武陵踪。武陵不在千山外，只在先生一笑中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中谢亲友四首 其四","p":"","d":"宋代","a":"俞德邻","c":["一病连三月，肥甘宁得知。医复戒食盐，盐食非所宜。", "素餐幸无刺，餐素将何疑。因思丧乱际，黎民多阻饥。", "朝餐乃木叶，暮食乃树皮。我今食无盐，早晚白玉炊。", "稽首谢苍天，揆分忱过之。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题扇示俞生","p":"","d":"明代","a":"胡奎","c":["荷叶圆时初见汝，木犀落后便相疏。秋声只在庭前树，分寸阴中好看书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄公望秋峰耸秀小幅","p":"","d":"清代","a":"弘历","c":["峰峻水潺湲，精蓝树欲殷。津涂银峡口，磴道白云间。", "四序原无住，山僧只自閒。香光正法眼，粉本认虞山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿卓水二首 其一","p":"","d":"元代","a":"许衡","c":["寒釭挑尽火重生，竹有清声月自明。一夜客窗眠不稳，却听山犬吠柴荆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望梅","p":"","d":"清代","a":"龚翔麟","c":["横斜孕蕊。过春竿候月，冷葩慵试。记年年、小白蔫红，斗点点星毬，綵棚檐底。", "听说寒轻，最好是、今年天气。步莎阶渐软，竹外旧枝，暗苔愁倚。", "东垞石门深闭。忆梨花砚雨，斋在山背。定半窗、横幅依然，奈千里槎程，香魂迢递。", "梦也都寻，醒便隔、重重烟水。想花风到迟，有约待招燕子。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西江月","p":"","d":"元代","a":"白朴","c":["天上灵椿未老，月中丹桂初花。充闾佳庆尽堪夸。", "圣善元来姓贾。", "广座平分玉果，绛颅剩拂丹砂。从今人说细侯家。", "自有青衫竹马。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄唐惟良","p":"","d":"明代","a":"黎民表","c":["莫道分符不暂閒，五更无吏唤追班。尊前岭树连宫阁，门外春涛喷雪山。", "万里身为迁播客，几人名在是非间。长杨羽猎还今日，应遣词臣入汉关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次王安行韵","p":"","d":"元代","a":"卞思义","c":["杖策来寻隐者居，闭门重著绝交书。入城无事不骑马，临水有时看钓鱼。", "未羡渊明开菊径，拟从诸葛住茅庐。清时羽翼知多少，肯散黄金学二疏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天（西湖）","p":"","d":"宋代","a":"林淳","c":["天近祅知雨露浓。湖山无日不春风。闲花野草皆掀舞，曾在君王愿盼中。", "时易得，会难逢。朝为逆旅暮三公。蛟龙得雨飞无便，鸡犬腾云夙有功。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗十首 其八","p":"","d":"明代","a":"王汝玉","c":["弱水不容涉，蓬莱焉得游。生时被珠玉，死后归山邱。", "一身非我有，此外定足求。君子顺时命，小人行险谋。", "荣华能取辱，贫贱可忘忧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"燕子图三首 其三","p":"","d":"金朝","a":"赵秉文","c":["交亲消息两何如，满眼兵戈不得书。为问南来新燕子，衔泥曾复到吾庐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"白莲寺次韵杜进士喜予见过话旧之作","p":"","d":"明代","a":"高启","c":["不辞鸣棹远相寻，欲向江斋伴旅吟。", "百事未成年已长，几时才别夏将深。", "萱留倦蝶连池绿，树带残莺满寺阴。", "恐被老僧嫌滞碍，旧游休说更伤心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"承旨乐山唐公八月十二日宴于其第以诗奉呈","p":"","d":"元代","a":"陈孚","c":["圣代开皇极，恩波雨露沾。笃生嵩岳佐，载叶渭川占。", "社稷千龄会，衣冠五福兼。朱弦新律吕，黄石旧韬钤。", "德望三朝眷，仪刑四海瞻。摛词追贾马，励学探羲炎。", "宇宙归青照，风云奋紫髯。议如唐陆贽，诗似晋陶潜。", "践履刚而毅，精神智以恬。一区杨子宅，万轴邺侯签。", "山色秋凝璧，烟光昼捲帘。金銮辞秉烛，玉铉待调盐。", "大匠规模远，宗公号令严。王臣躬蹇蹇，君子德谦谦。", "此日鸣朝凤，清秋近夜蟾。瑶簪环杖履，宝墨出湘缣。", "北海宾长满，东山屐未厌。车声阗绣户，花影舞朱檐。", "乐幸追灵运，忧当后仲淹。愿施经济具，天下待针砭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十一月十四日有感寄江州太守李子威 其一","p":"","d":"元代","a":"成廷圭","c":["清朝如此盛公卿，何以摅忠答圣明。数月未收蕲水贼，一时谁散武昌兵。", "朱门旧邸空文藻，黑夜归舟有哭声。独使状元贤太守，至今犹捍九江城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居杂诗 其二","p":"","d":"明代","a":"罗万杰","c":["灌畦日暮荷锄归，满目蓬蒿夕照微。黄叶乍冲鸟语落，白云时绕磬声飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"述怀","p":"","d":"现代","a":"洪传经","c":["疏狂无意逐功名，舞舌川湘又楚秦。", "学汇中西空自许，言非理则不相因。", "那知以此遘忧患，竟为多言犯要津。", "甚矣书生无一用，未能权变且谋生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"立春","p":"","d":"当代","a":"姚佳","c":["鱼陟负冰应不禁，蜇虫始振几消沉。东风解冻还依旧，上界无生直至今。", "宰臣以下皆称贺，咫尺之间可鉴临。万世梧桐存祖殿，漫从枝叶感春心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送曹同椅","p":"","d":"唐代","a":"司空曙","c":["青春三十馀，众艺尽无如。中散诗传画，将军扇续书。", "楚田晴下雁，江日暖游鱼。惆怅空相送，欢游自此疏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"扈跸词三十二首 其二十一","p":"","d":"明代","a":"陆深","c":["板轿棕舆渡碧山，涧花岩树影龙颜。云中别有通陵路，䟎过前驱插大班。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓妆","p":"","d":"清代","a":"孙原湘","c":["水晶帘射日曈昽，茜子裈裆八尺红。羞对熟人呈晕月，笑持雏婢作屏风。", "梳头惯学轻云立，靧面才将艳雪融。偷描珠兰笼袖底，觑人方便掷奁中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅仙祠","p":"","d":"宋代","a":"赵公豫","c":["汉尉垂纶处，遗风事可传。林深飞鸟入，水隔小桥连。", "道室幽如许，山花晚倍妍。到来心志静，不复有尘缘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送森知客","p":"","d":"宋代","a":"释普度","c":["清远溪边劄寨时，春风簇簇露枪旗。", "谁知唤客吃茶处，万别千差一道归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"淮阳路","p":"","d":"唐代","a":"李商隐","c":["荒村倚废营，投宿旅魂惊。断雁高仍急，寒溪晓更清。", "昔年尝聚盗，此日颇分兵。猜贰谁先致，三朝事始平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乙丑孟秋下旬四日杨中丞绝命诏狱是夜初昏时有气如白练起尾箕间扫紫微掩天枢五星时在燕邸目睹感赋二首 其一","p":"","d":"明代","a":"顾大武","c":["满地苌弘血染衣，补天功业竟安归。犹余万丈长虹气，此夕骖箕叩紫微。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二怀诗 其一 玄真子张志和","p":"","d":"明代","a":"胡应麟","c":["有唐迄元和，畸流尚不乏。翩翩玄真子，百代恣渔猎。", "雅志游松乔，奇踪轨庄列。嗒尔柱下言，超然谢津筏。", "富贵轻鸿毛，轩冕等澌沫。一辞世主聘，浮家老苕霅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜王巩承事北归","p":"","d":"宋代","a":"苏辙","c":["同罪南迁惊最远，乘流北下喜先归。", "谓言一笑秋风后，却顾千山驿路非。", "岭外云烟随梦远，江边鱼蟹为人肥。", "还家嫁女都无事，卧读诗书尽掩扉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠钟道士","p":"","d":"宋代","a":"范仲淹","c":["人间无复动机心，挂了儒冠岁已深。惟有诗家风味在，一坛松月伴秋吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南柯子 秋夜","p":"","d":"明代","a":"叶小鸾","c":["门掩瑶琴静，窗消画卷闲。半庭香雾绕阑干。一带澹烟红树、隔楼看。", "云散青天瘦，风来翠袖寒。嫦娥眉又小檀弯。照得满阶花影、只难攀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 其一","p":"","d":"近代","a":"庞俊","c":["蜜炬围春帘不卷。依旧东风，款款飞双燕。看煞羊车人婉娈，熟人却是初相见。", "入手翠尊休待劝。不道中年，争信春宵短。叠鼓垂灯新句练，落梅天气深深院。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小舟晚归","p":"","d":"宋代","a":"陆游","c":["扶病寻溪友，忘忧泛钓槎。", "渚寒无宿鹭，月白有啼鸦。", "败壁青灯暗，幽窗稚子哗。", "无生未暇说，且复议桑麻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"诉衷情（濡溪悼旧）","p":"","d":"宋代","a":"黎廷瑞","c":["曲屏深院赴幽期。心事梦云知。佩环零乱何处，江上草离离。", "日平西，天似幕，月如眉。依稀还记，两岸杨花，送上船时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将至桂林戒弗作诗饮酒","p":"","d":"宋代","a":"李曾伯","c":["误领元戎太乙旗，提封四履镇南篱。", "旄倪争向道涂看，名姓亦为蛮徼知。", "时务下地毋事酒，春光虽好莫言诗。", "经营都了家山去，此是从穷容觞咏时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东坡赤壁图","p":"","d":"元代","a":"曹之谦","c":["先生矫矫人中龙，京尘千丈不可容。五年一梦落江海，翩然野鹤开囚笼。", "雪堂闭户读书史，兴来飘然弄云水。黄泥坂下醉三更，赤壁矶头航一苇。", "明月清风共一江，迈往之气无由降。酒酣作赋记清赏，袖有巨笔如长杠。", "一朝骑鲸寻李白，人间俯仰成今昔。续弦无处觅鸾胶，见画思公空叹息。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江夏寓兴二首之二","p":"","d":"宋代","a":"贺铸","c":["陂湖蹙坊市，江汉复纵横。", "沮洳莎城阽，晴阳竹瓦鸣。", "新文添鹏赋，异味识鼋羹。", "岂复悲流落，官粮寓此生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙","p":"","d":"宋代","a":"赵长卿","c":["远岫螺头湿翠，流霞赪尾疏明。断虹斜界雨新晴。烟村灯火晚，江浦画难成。", "我向其间泛叶，终朝露渚风汀。老来心事最关情。不堪三弄笛，吹作断肠声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其一○三","p":"","d":"宋代","a":"谌祜","c":["地上有钱流，冥閒无半字。自作槁木看，静阅沧江流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢池春","p":"","d":"宋代","a":"李石","c":["烟雨池塘，绿野乍添春涨。凤楼高、珠帘卷上。金柔玉困，舞腰肢相向。似玉人、瘦时模样。", "离亭别后，试问阳关谁唱。对青春、翻成怅望。重门静院，度香风屏障。吐飞花、伴人来往。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长安道三首 其一","p":"","d":"明代","a":"沈鍊","c":["来往都城道，探知朝士心。若闻身世事，定肯却黄金。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"北山道人栽松","p":"","d":"宋代","a":"王安石","c":["阳坡风暖雪初融，度谷遥看积翠重。", "磊砢拂天吾所爱，他生来此听楼钟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九月初四日大风雨近重阳无酒夜成二首","p":"","d":"宋代","a":"方回","c":["秋霖欲洗庾公尘，不管楼头客恨新。", "塞雁又为江左客，菊花曾识晋时人。", "百年虚谷先生老，一纪严州太守贫。", "几向客右度重九。苦无佳句答良辰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻征四处士","p":"","d":"唐代","a":"贯休","c":["一诏群公起，移山四海闻。因知丈夫事，须佐圣明君。", "白酒全倾瓮，蒲轮半载云。从兹居谏署，笔砚几人焚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辰江杂兴 其二","p":"","d":"明代","a":"符锡","c":["有路沿云断，无人但鸟呼。半山御落日，始觉客怀孤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舍人崔公挽词 其一","p":"","d":"宋代","a":"黄定","c":["昭代培英俊，皇天独不仁。儒林埋鸑鷟，翰苑失麒麟。", "青史空遗字，黄麻半掩尘。惟馀忠荩语，分付义方人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"伯兄自山中来夜话山居之胜因忆去秋省兄未及十日而别诗以志感得二十韵","p":"","d":"清代","a":"吴敬梓","c":["地本烟霞窟，兄为巢许伦。百年歌帝力，十亩乐天真。", "抱阜宜营室，还汀许结邻。绿回芳草长，黛染远峰匀。", "社鼓乌江庙，灵旗牛渚津。山川馀质朴，习俗尚清淳。", "野老嬉游共，村翁来往频。藤萝阴漏月，桑柘影随身。", "美酒盈杯劝，良苗几棱新。饧箫花外市，牧笛雨中春。", "幸免家人谪，偏馀稚子亲。摊书消永夜，高枕卧清晨。", "自著潜夫论，宁辞原宪贫。昨秋过故里，留我住弥旬。", "薜荔依门巷，蒹葭变水滨。圆沙知雁聚，曲港见鸥驯。", "蟹簖缘溪富，鱼罾罥树均。嘉肴仍速舅，肥牡定娱宾。", "愿得长相倚，须完未了因。寄声劳扰客，此是武陵人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梓于鳞集有感八绝句 其四","p":"","d":"明代","a":"王世贞","c":["雪楼高傍㟙湖濆，消渴频年卧白云。问得儿驹留草在，教人翻恨卓文君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陪陶尚书宋太史夜宿斋宫分韵得万字","p":"","d":"明代","a":"刘崧","c":["鸣鸾莅阳郊，陪祀服明宪。旂常拥圆壝，幕帟蔽脩甸。", "天高风泠泠，露白星烂烂。尊罍秩斯举，簴业枞以建。", "凝神向澄肃，秉德方恪愿。调笙思肄三，振羽将舞万。", "张筵盛布设，陈币昭奠献。听漏促晨兴，严衣戒宵偃。", "骏奔尚齐遫，慎简惭硕曼。感孚岂殊徵，恭事式同劝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沙河主人后园枣实甚繁感而有述","p":"","d":"明代","a":"顾清","c":["牡丹红径尺，一败即空枝。枣花大于米，结实反累累。", "世途争外骛，衒巧复矜奇。仪衍雄辩说，潘陆姱文辞。", "华藻炫缃素，声名倾一时。终然木强子，铭功汉鼎彝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满庭芳 七首满庭芳藏头字句不一，疑有误","p":"","d":"元代","a":"王哲","c":["黄邑于公乞修行论修行，翁甚喜，津堪作琼浆。清火赫，颠倒吉还昌。显金乌甚朗。中现、玉兔精详。谈正，处暑气变成霜。当。内宝，珍珠璧，一一收藏。尤良善善，性烛施张。现灵明愈耀，中土、本有真光。冥点，烟散尽，堪庆满庭芳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"托吴僧乞石田画","p":"","d":"明代","a":"杭淮","c":["缅怀高人今白头，秋风未放沧江舸。叹息人间常见画，白水丹山无不可。", "有时更出双梧桐，柯如碧玉参青空。下有閒翁曳杖屦，萧然意气来清风。", "自是君身有仙骨，放笔尘寰看超忽。且知画者乃馀事，君有声名非汩没。", "吾亦平生颇好画，逢人不爱千金求。安得生绡出东壁，白云为我生沧洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖上怀同少野","p":"","d":"宋代","a":"释行海","c":["衰柳残阳泊钓船，白鸥零落画桥边。", "咸平处士梅花树，不得同看又两年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归田乐","p":"","d":"宋代","a":"蔡伸","c":["风生苹末莲香细。新浴晚凉天气。犹自倚朱阑，波面双双彩鸳戏。鸾钗委坠云堆髻。谁会此时情意。冰簟玉琴横，还是月明人千里。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"铙歌 其十五 上邪","p":"","d":"明代","a":"李攀龙","c":["上邪。我欲与君同心，乐以不可禁。相思绍缭，谗言罔极，大驾六龙处天侧。", "日月出入沧海中，妒人之子难为工。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题画四首 其二 题扇","p":"","d":"明代","a":"梁兰","c":["钿合收残黛，香风吹绿衣。閒来消永昼，非是效班姬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花一首","p":"","d":"宋代","a":"刘克庄","c":["造化生尤物，居然冠众芳。", "东家傅粉白，西域返魂香。", "真可婿芍药，未妨妃海棠。", "平生恨欧九，极口说姚黄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"河中戏作绝句","p":"","d":"宋代","a":"晁说之","c":["人物英雄异姓王，山河生气尚光鋩。", "可怜只解夸佳丽，花落春空更断肠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"避地寒食","p":"","d":"明代","a":"易翀","c":["插柳才惊寒食逢，弟兄奔走各西东。落花有恨随风舞，芳草无情泣露浓。", "白发暗添沦落里，青春已过乱离中。寥寥先陇南山外，谁为持觞一扫松。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中环海旁道漫步","p":"","d":"当代","a":"伯昏子","c":["鳌池片屿挟云奔，蜃影蓬莱荡帝阍。蔽日楼摇鱼鸟出，排空浪鼓蚁车喧。", "依前古道名酋督，不复洋行树鬼幡。钟鼎嫌伤尘俗气，争趋山半筑华轩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠傅与砺","p":"","d":"元代","a":"虞集","c":["水玉空青不易求，兰苕翡翠擅清秋。才情岂是人间少，不到高唐梦未休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过波罗二首 其二","p":"","d":"明代","a":"湛若水","c":["举手望飞云，鸣桡过黄木。舣舟江上亭，虚空观日浴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五月十二日晚登平云亭得平字齐字","p":"","d":"宋代","a":"郭印","c":["磴道穿乔木，危亭喜杖藜。", "郊原春树暗，井邑暮烟低。", "日没牛羊下，山空鸟雀啼。", "超然尘世外，身与白云齐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六月雨十一首","p":"","d":"宋代","a":"许月卿","c":["今岁无时不御寇，每年此际去防秋。", "琴散广陵今叔夜，笳声出室古刘畴。", "启沃欣承霖雨楫，流离安乐雁鸿洲。", "我自清时幸民着，茅柴薄晚妇能篘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚晴落照","p":"","d":"清代","a":"弘历","c":["急雨驱殢云，晚晴辉落照。入波翻画楼，挂树明烟峤。", "助之西北风，寥寥鸣万窍。迟日方立秋，气机已先到。", "鸣蝉惜景光，嘒嘒枝头噪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠童子久住侍父入京","p":"","d":"明代","a":"陈献章","c":["还著小坡随长公，天葩未吐孝经通。青襟谁不羡童子，白发我徒成老翁。", "曝日家声从此大，凌云气魄盖人雄。曲江清献乡先达，敢道后来无此风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"素琼表妹示和其师华西洲先生消夏十八首次韵和之 其五","p":"","d":"近代","a":"温倩华","c":["花外人来唱采莲，冰绡新染水痕鲜。一声欸乃幽篁里，惊起鸳鸯破碧烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和松石舍人秋夜不寐","p":"","d":"元代","a":"袁士元","c":["抛书欲卧意迟迟，坐听秋声思惨悽。萤火独飞侵幔小，星河斜落压城低。", "牙筹历历随更转，燐鬼啾啾隔水啼。更为挑灯移近榻，与僧相对话曹溪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓登沅州北山顶","p":"","d":"明代","a":"薛瑄","c":["岚霭氤氲重，溪行咫尺迷。渐登层巘上，始觉众山低。", "远近天无际，参差树不齐。川云平似海，石磴峻如梯。", "日出寒烟外，风生碧涧倪。异禽和露宿，快马度空嘶。", "远目回三蜀，高怀遍五溪。归朝誇胜槩，沅水有新题。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"癸丑春闱试毕次韵知举倪侍郎先生二首 其二","p":"","d":"明代","a":"李东阳","c":["夜灯人静不成眠，亲听王褒颂得贤。圣代文章真盛矣，少时情兴转翻然。", "麟凰遍薮元多瑞，奎壁分宫亦并躔。南省东堂嘉话里，几人同事复同年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题山水图二首 其一","p":"","d":"明代","a":"萧镃","c":["青山何岧峣，下有嘉树林。高亭昼闲敞，窗户含层阴。", "前村夜来雨，石濑张素琴。好鸟鸣檐间，始知春意深。", "迥无外物累，嘿处抱冲襟。对此案上书，悠悠千载心。", "安得谢尘羁，扁舟谐远寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"于安城答灵运诗 其四","p":"","d":"南北朝","a":"谢瞻","c":["肇允虽同规，翻飞各异概。迢递封畿外，窈窕承明内。", "寻途之既暌，即理理已对。丝路有恒悲，矧乃在吾爱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送草伯镇知湖州","p":"","d":"宋代","a":"司马光","c":["江外饶佳郡，吴兴天下稀。", "蓴羹紫丝滑，鲈脍雪花以。", "星斗寒相照，烟波碧四围。", "柳侯还作牧，草树转清辉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冬暮村居杂咏，寄叔白七首 其七","p":"","d":"清代","a":"李宪噩","c":["孤吟知兴远，闲坐亦深更。僮睡呼不醒，镫昏挑暂明。", "夜寒如有悟，钟尽即无声。晓寄城中客，还能识此情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十月十二日奉诏以玉德殿西室为宫学大宿卫官等二十五人行弟子礼作","p":"","d":"元代","a":"周伯琦","c":["学校尊崇盛典扬，诏迁玉德殿西廊。大官供帐调珍膳，内相传宣饮御觞。", "授业惭无师道立，明伦喜见国家昌。皇风即日还三代，杞梓楩楠尽栋梁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"屏山老人诗用李宾之韵","p":"","d":"明代","a":"张泰","c":["岁晚开园傍玉屏，朝朝仙屿眼中青。九峰分秀来空翠，森木团烟隐鹤汀。", "东老自为仙隐地，南山宜作寿藏铭。有生期与人同乐，不饮常防客共醒。", "文屦长年盈我户，惠风迟日散邻扃。并荣华萼知春足，连秀芝兰觉地灵。", "雅望满乡称长者，德言康俗胜官刑。义声津口垂虹石，仁术囊中本草经。", "载悦凤毛晞杲杲，坐忘乌帽裹星星。屏山有叟增光价，千载应看似敬亭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜泊永乐有怀","p":"","d":"唐代","a":"许浑","c":["莲渚愁红荡碧波，吴娃齐唱采莲歌。", "横塘一别已千里，芦苇萧萧风雨多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新开小轩晁子西有诗以韵答之二首","p":"","d":"宋代","a":"郭印","c":["我无先世英，敢望燕台筑。", "譬如坎井蛙，拘虚徒窘束。", "又如鹪鹩巢，所寄一枝足。", "名不闻公卿，迹非侣樵牧。", "眼花鬓毛霜，黾勉作侯服。", "吏才固不高，民事亦稍熟。", "每欲思寡过，岂敢求多福。", "君公迟风云，行矣龙起陆。", "佳篇杂沓来，文绣被土木。", "坐令北窗下，不知有穷独。", "相逢一笑粲，语妙席自促。", "凭谁觅仙方，造酒逡巡速。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"思母","p":"","d":"明代","a":"唐宙","c":["冷落莆阳掷却杯，梦魂频绕粤王台。身无著处官为累，事不如人口懒开。", "碧水丹山殊驿路，疏灯细雨各天台。慈亲跂望无虚日，拟卜明春拂袖回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"肺病","p":"","d":"宋代","a":"周行己","c":["吾生与静侔，早无适俗器。失身挂尘网，道心日已替。", "今兹得肺病，自可绝人事。默观悟生理，是身同一蜕。", "代马无南蹄，越鸟无北翅。物各归其本，我何有于世。", "冠冕且罢休，养痾山水际。藉石看白云，临流鼓兰枻。", "百种绝念虑，优游聊卒岁。谁云病疾苦，邂逅即良计。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"得湖州崔十八使君书喜与杭越邻郡因成长句代贺兼寄微之","p":"","d":"唐代","a":"白居易","c":["三郡何因此结缘，贞元科第忝同年。故情欢喜开书后，", "旧事思量在眼前。越国封疆吞碧海，杭城楼閤入青烟。", "吴兴卑小君应屈，为是蓬莱最后仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋闺 其三","p":"","d":"明代","a":"谢榛","c":["寒蛩兼夜雨，并作枕边愁。天涯有苦乐，两地一般秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哭金秀才","p":"","d":"明代","a":"郭谏臣","c":["月落江湖夜已阑，故人别后见应难。西风吹散清宵梦，肠断霜天雁影寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"今岁梅花春中犹未开因思三衢冬月之盛作长句","p":"","d":"宋代","a":"李正民","c":["前年柯山芳意早，肯使寒梅例枯槁。溪边几树发偏繁，墙角数枝看更好。", "玉颜冒雪不奈寒，香心怯雨尤相恼。南枝烂漫北枝催，空惜飘零缀芳草。", "朅来海角风景迟，经冬不见端可疑。红萼涉春才似染，青苞映日未全披。", "千山隔兮万山阻，想见瑶英讵如许。一枝谁与寄相思，回首旧游心独苦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜意","p":"","d":"宋代","a":"陆游","c":["幌外灯青见鼠行，林梢月黑有枭鸣。", "只言中夏夜偏短，万里梦回天未明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"樟树镇舟中作","p":"","d":"明代","a":"杨基","c":["侬是吴淞钓鱼叟，全家生长吴江口。", "迟钝长飞众鸟先，迂疏每落诸人后。", "城中父老少相知，乡里儿童亦见欺。", "几上细抄《高士传》，壁间大篆《考槃》诗。", "春风百草承膏沐，强掷渔蓑亲案牍。", "胥史犹嘲吏事疏，妻孥欲笑形容俗。", "羸马长途恐不堪，君恩何日许投簪。", "半篷秋雨烟笼水，数点寒星月满潭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"昆山慧聚寺集句","p":"","d":"宋代","a":"葛次仲","c":["全吴临巨溟，青山天一隅。静境林麓好，胜槩凌方壶。", "泓泓野泉洁，暧暧烟谷虚。攀云造禅扃，跻险筑幽居。", "道人刺猛虎，复来薙榛芜。咄嗟檀施开，以有此屋庐。", "侧叠万古石，功就岂斯须。磥砢成广殿，鬼工不可图。", "有穷者孟郊，过此亦踌躇。赋诗留岩屏，词律响琼琚。", "我访岑寂境，幸与高士俱。时升翠微上，凉阁对红蕖。", "岸帻偃东斋，果药杂纷敷。上方风景清，华敞绰有馀。", "高窗瞰远郊，万壑明晴初。赏爱未能去，赪霞照桑榆。", "老僧道机熟，闲持贝叶书。秉心识本源，高谈出有无。", "茗酌待幽客，顿令烦抱舒。儒道虽异门，意合不为殊。", "抖擞垢秽衣，惟有牟尼珠。馀生愿休止，投策谢归涂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚泊石头城下明旦发龙江","p":"","d":"明代","a":"张以宁","c":["江口帆开五两飞，海门遥望树依微。若为得似千年鹤，东向三神岛上归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏史二十四首 其十三","p":"","d":"明代","a":"黄淳耀","c":["威兽未入汉，郅支方挽强。子公仗剑怒，一战殪其王。", "捷书才视草，劾奏已成章。大臣衡与显，摇笔侍岩廊。", "臂诎妨射虎，声颓坐贪狼。何人泣李广，永毒壮士肠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高邮湖阻风时虽开夹湖未能行舟","p":"","d":"明代","a":"程敏政","c":["一阵狂飙入地垠，客舟如叶浪如轮。凭谁上诉由风伯，任尔抛香拜水神。", "阿岸稍卑思跃马，夹湖虽好未通人。南来北去皆行役，篷底从容莫漫嗔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吴中大水有负郭田在常州云已漂溃作一首示公仪","p":"","d":"宋代","a":"刘敞","c":["百谷驰东南，三江浇吴会。积阴漏云汉，涌水翻积块。", "斯民既昏垫，我稼堕颠沛。鱼鳖有馀粮，郊原靡遗穗。", "糊口窃自恕，矜寡将何赖。天道有盈虚，吾宁罪于岁。", "救饥苦谋拙，禹稷不可待。行矣帆长风，因之浮海外。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上元前一夜童都督席上观灯 其二","p":"","d":"明代","a":"游朴","c":["严更柝静不闻喧，火队星车次第奔。杨柳无根莺并宿，梅花欲落蝶双翻。", "楼船飞鹢行平陆，卉服驯师舞戟门。熢燧时平无用处，化为银烛照金尊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吊邹汝愚谪石城 其二","p":"","d":"明代","a":"陈献章","c":["江月无光江水寒，角声杳杳夜漫漫。孤儿岁月初离乳，夫子风流尽盖棺。", "身后岂知名可贵，世间长苦路行难。鸱夷不乱当年计，还得云门枕上看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄大司马王公度","p":"","d":"明代","a":"韩雍","c":["大才不易得，时艰良可忧。所以古圣贤，治世怀远猷。", "召公欲致政，周公勉相留。二公心德同，俪美匡成周。", "芳声播千古，人皆仰前修。堂堂王司马，当代第一流。", "以身徇国家，才气谁可俦。方兹任经济，整顿多事秋。", "如何在告中，遽尔得退休。不知诸同列，亦曾勉留不。", "昨简掌邦政，朝廷广询谋。黄门御史言，称职惟君优。", "上允即超拜，四方动欢讴。兹闻勇退归，物议皆啾啾。", "嗟予忝知己，痛惜不自由。所惜为天下，匪为君身谋。", "四方水旱多，贼盗方且稠。须起出群才，同心运良筹。", "渊衷必有在，士论终当收。君其善养年，予未歌四愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莼二绝 其二","p":"","d":"宋代","a":"张侃","c":["达人胸次与天宽，到处浮家得细看。满盌莼丝浮碧色，不妨邀客话儒酸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"祥符寺","p":"","d":"宋代","a":"聂致尧","c":["诸峰回合处，古木抱松林。", "月占秋廊静，云侵昼殿阴。", "有泉通石眼，不火沸池心。", "洗净多生垢，天风更梵音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"合宫歌（皇佑二年飨明堂）","p":"","d":"宋代","a":"赵祯","c":["缵重明。端拱保凝命。广大孝休德，永锡四海有庆。觚坛寓礼正典名。幔室雅奏，彩仗崇制定。五位仿古甚盛。蒿宫光符辰星。高秋嘉时款芎灵。交累圣。上下来顾，寅畏歆纯诚。三阶平。金气肃，转和景。翠葆御双观，异风兑泽布令。脂茶划荡墨索清。远迩响附，动植咸遂性。表里穆悦，庶政醇醲，熙然胥庭。唐舜华封祝，如南山寿永。愿今广怀宁延，昌基扃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岳阳晚兴（四首）","p":"","d":"明代","a":"叶子奇","c":["长天秋水一色，落日青山半衔。", "雁浦烟波渔笛，龙阳风雨归帆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长夏无事避暑山园景事所会即成微吟得二十绝句 其十","p":"","d":"明代","a":"王世贞","c":["北风高枕便羲皇，佳景无多畏景长。争似侬家祗树苑，六时何处不清凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂三十八首","p":"","d":"宋代","a":"释如净","c":["黄金殿上一转语，烜爀红轮照万方，", "草木丛林成正觉，砖头瓦砾放毫光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莲花篇","p":"","d":"清代","a":"周馨桂","c":["莲花何灼灼，灼灼花莫比。淤泥中濯濯，濯濯出清水。", "把酒对莲花，莲花笑欲语。生憎荡舟人，允矣吾与汝。", "觅句对莲花，莲花宛可则。不见太白诗，天然去雕饰。", "每当初日际，起我先公思。先公爱莲花，高怀契清姿。", "清姿与高怀，千秋常若斯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题吴氏社仓","p":"","d":"宋代","a":"项安世","c":["淹剧无悰易怆神，社仓新记重关心。", "前朝诏在恩沦骨，遗老书存泪满襟。", "永念君仁多善稼，肯因师死下乔林。", "皇天老眼明于镜，勉植书楼万桂阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋胡行四首 其四","p":"","d":"明代","a":"李孙宸","c":["毁誉何常，权势易为名。毁誉何常，权势易为名。乘风呼长，非疾其声。", "窈国侯门，仁义所并。兰生幽谷，孰扬其馨。歌以言之，权势易为名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"缘识","p":"","d":"宋代","a":"宋太宗","c":["群生宗法界，秘密十方尊。", "大教缘心识，周通一念存。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"步西湖次韵徐南卿 其五","p":"","d":"宋代","a":"陈造","c":["徐子学诗苦，砚池宁暂临。课功初赑屃，著语遽精深。", "更积岁月力，傥陪英俊林。人生才业地，渠辈分平沈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"毛虞卿见过","p":"","d":"宋代","a":"王十朋","c":["故人访吾庐，况是清和节。高槐绿成阴，芳草碧未歇。", "携手山间行，清兴浩然发。呼童具鸡黍，浊酒醅初泼。", "贫居愧荒凉，野蔌草罗列。盘实饤梅豆，蔬餐荐薇蕨。", "主礼虽甚微，客色未尝觖。醉翁山水意，不为壶觞设。", "蟹眼煎新汲，雀舌烹春撷。浇君文字肠，掉我清谈舌。", "人生会面难，岁月易飘忽。君姑为我留，匆匆莫言别。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和竹士晓游邓尉作","p":"","d":"清代","a":"金逸","c":["一声笛破晴空烟，欲明不明五更天。树头残月白堕水，湖上晓山青入船。", "风梵飘香落云外，波光拥棹来门前。四围皆雪失大地，徜徉绝顶疑游仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"台湾竹枝词 其三十","p":"","d":"清代","a":"丘逢甲","c":["好吟应是太痴生，笔墨因缘记不清。谁把四弦弹夜月，新词唱遍赤嵌城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书寄陈昼卿书尾","p":"","d":"清代","a":"陈寿祺","c":["欲归还小住，杯酒许重斟。信宿分离后，相思直到今。", "大江流远梦，小雅托哀音。记否中山夜，绳床听雨心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答吴献臣大尹 其四","p":"","d":"明代","a":"祁顺","c":["云霄未竟忠勤志，江海空怜濩落身。便欲乘风问真宰，赐环何日起孤臣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"度灵羊峡望崧台","p":"","d":"明代","a":"郭棐","c":["西江西峡郁嵯峨，南客南来几啸歌。旭日映空翻翠壁，飞云当岫袅青萝。", "能将华发逢秋色，欲把青竿侣钓蓑。野兴狂吟予不浅，崧台携手思如何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"妻为儿买龟种于瓦盆今携至护国寺放生戏题一首","p":"","d":"当代","a":"李达","c":["兰若放尔去，瓦盆曾久留。归池仍缩壳，顾我肯回头？", "莲净巢堪寄，饭香僧为投。小男犹不舍，欲捉更无由。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"枕上偶成三首 其二","p":"","d":"宋代","a":"杜范","c":["春动边声虏计狂，淮流据断架浮梁。雨师怒烈风云阵，定报惊奔尽犬羊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和钟漕汝强四首","p":"","d":"宋代","a":"胡寅","c":["雾豹成文不厌深，喧卑何事竞翰音。", "为言墨客夸三赋，那似仙翁振八吟。", "欲继高踪其敢后，下看浮世岂须临。", "何时蜡屐携筇杖，来拨衡云一万寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古兴","p":"","d":"宋代","a":"李新","c":["倮葬畏礼法，厚葬索衣衾。", "金缕与玉柙，五陵非不深。", "万宝埋幽光，苦为群盗寻。", "上古莫封植，弃之中野林。", "上以饱飞鸟，下从蝼蚁侵。", "人情远臭腐，焉知孝子心。", "死者或有知，自亦畏奢淫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"涵碧亭八咏 其二 石鼓浮岚","p":"","d":"明代","a":"程敏政","c":["小山本幽绝，晴岚湿衣裾。谁能琢崖藓，正作岐阳书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与陶生","p":"","d":"明代","a":"释妙声","c":["我有青山一片霞，倩君为我制加沙。明朝天上讲经去，吹落满身优钵华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和文与可洋川园池三十首 披锦亭","p":"","d":"宋代","a":"苏轼","c":["烟红露绿晓风香，燕舞莺啼春日长。", "谁道使君贫且老，绣屏锦帐咽笙簧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"柳梢青","p":"","d":"清代","a":"陆求可","c":["云外天香，月中桂子，又做中秋。一曲霓裳，三声玉笛，两度嬉游。", "披衣不用登楼。但花下、诗筒酒筹。恐似前番，金钱散落，醉里谁收。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过秀野亭观赵昌花","p":"","d":"宋代","a":"朱翌","c":["牡丹酴醾送春归，南风亦复吹戎葵。", "青女不瘦芙蓉肌，雪中山茶火争辉。", "此开彼落相背驰，安得坐隅皆见之。", "剑南老人来解衣，好手不免如徐熙。", "萧然四幅十二枝，规模一出众史卑。", "妙处天授非人为，右军字画少陵诗。", "后来纵好难并驰，传观左右识者谁。", "爱画入骨一痴，惜哉不犹坡谷题。", "何妨扰扰俗眼疑，秀野前后花成帷，", "按图求之君自知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"邹一桂菊华秋实","p":"","d":"清代","a":"弘历","c":["都云秋实胜春华，畦径今看别一家。也祗金英方合称，兜罗绵手恰拈花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂述 其七","p":"","d":"宋代","a":"林泳","c":["一念重来如祖忍，三生尽见有图澄。虎虽化女心常在，鹰已为鸠眼可憎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游武夷山二首 其一","p":"","d":"宋代","a":"韦骧","c":["一溪秋水碧溶溶，逆掉扁舟溯晚风。卧看峰峦耸奇势，心疑造化炫殊功。", "宾云曲断笙箫远，机石苔荒组织空。仙理冥冥难究诘，抽簪归隐羡刘公。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠真头陀","p":"","d":"明代","a":"胡应麟","c":["南州来赋客，北苑问高僧。佛土穷三界，人天度七陵。", "孤云晨拓钵，大雪夜传灯。便欲逃禅去，风幡證惠能。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓霁发顺河","p":"","d":"清代","a":"姚燮","c":["天光浩荡晨曦开，断云片片鱼鳞吹。好风习习东南来，拂人衣袂清无埃。", "高原郁润欲下滴，远山隐秀难平窥。新茭芽短水出没，晚麰花小烟萦回。", "蝉声乍停蛙语接，塘燕侧逐林鸠飞。夏中气候等春晚，天宇四溢皆灵机。", "适行八日达山左，凭辕蒿目增惨凄。赤阳槁土万生暍，村户荒落人烟稀。", "夜来云气汹西北，沛作甘澍连青徐。淮堤泗闸各流活，塍沟如绠通凫鹥。", "孳荣不虑禾有耳，大禳可卜秋无饥。茧足尘帽路行客，对此亦觉清心脾。", "桃源傥容移宅隐，吾将袯襫从扶犁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自吕堰趋襄阳","p":"","d":"清代","a":"傅应台","c":["望望章台道，遥遥岘首亭。云生三户白，日落万山青。", "远雁来衡岳，孤帆下洞庭。相思何处是，烟树夕冥冥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吸江亭下望烟霞洞口梅花","p":"","d":"近代","a":"黄浚","c":["梅花即烟霞，岁久心化铁。绛宵谢轩轩，寂寞见高节。", "斜看自然好，俯看更奇绝。此亭谁云稳，吸江才一瞥。", "林间缟衣人，笑我肠内热。仙云翩在下，令我天眼缬。", "十年两相见，万事那可说。细雨满关山，相逢忍攀折。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"生查子 其一 不贰适","p":"","d":"当代","a":"黄绮","c":["白纸有清真，以墨添图字。纸亦愿牺牲，代答人间意。", "烈火总燃烧，高热思吞水。水下就深渊，宁自身焚毁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"婆罗门六首 其一","p":"","d":"元代","a":"耶律铸","c":["热海气蒸为喜雨，冻城寒结就愁阴。中心甚欲期真宰，教使人知造物心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"通鉴","p":"","d":"明代","a":"薛瑄","c":["千二年来治乱机，只从理欲辨安危。若将此鉴为心鉴，三五如何不并归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"漫兴二首","p":"","d":"明代","a":"邓渼","c":["花县常三仕，台乌偶一枝。", "不能执虎子，须效牧羊儿。", "兰摧终异艾，豆落仅存萁。", "共说长沙傅，生当盛汉时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送盛孔赴淄川丞二首 其二","p":"","d":"明代","a":"贝琼","c":["魏有径寸珠，守境无檀子。照车十二乘，何如照千里。", "世乏威王贤，孰知天下士。所以饭牛儿，商歌中夜起。", "徒求南海产，半触蛟龙死。异才何代无，纠纷今可理。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李昭象书堂","p":"","d":"宋代","a":"释希坦","c":["废兴生死妄安名，山水何曾改旧清。孰谓堂空人已往，溪声还作读书声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戏示邻友三章 其一","p":"","d":"清代","a":"姚燮","c":["终朝咄咄当讴歌，束手看君计奈何？灌釜甘浆烹大芋，蜷门病狗恋重蓑。", "大江日落潮未落，老屋风多湿更多。巢父掉头许由笑，兔毫秃尽换无鹅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和麟老韵五绝","p":"","d":"宋代","a":"王炎","c":["白雪蒙头卧佛庐，笔端亦解世间书。", "无情安用诗陶写，有病何须药破除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次翰林都事拜住春日见寄韵","p":"","d":"明代","a":"张以宁","c":["日高睡起小窗明，飞絮游丝弄昼晴。", "忽忆金河年少梦，柳阴骑马听流莺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和姜总管归途","p":"","d":"宋代","a":"虞俦","c":["城郭迎车骑，溪山展画图。", "归鸦翻落叶，宿雁集寒芜。", "酒里倾肝胆，吟边识步趋。", "佳人来底暮，心傒碧云苏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和陈仲邦野步城西","p":"","d":"宋代","a":"谢逸","c":["寺近仙坛西复西，醉中信足路应迷。鸣条风劲凋蒲柳，掠岸云低乱鹄鹥。", "檐外檀栾森翠巘，门前略彴跨清溪。葛巾藜杖真潇散，何必狨鞍鞚月题。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用大名诸公唱和韵送别少逸 其四","p":"","d":"宋代","a":"王安中","c":["迩来走笔吟，别后随手散。收拾亦安用，半是谐谑间。", "不能所作工，要解风水涣。莫以人废言，遂忽博士谩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游安乐山","p":"","d":"宋代","a":"任伋","c":["安乐溪上峰，万木森翠羽。", "孤撑切天心，横拓压刊股。", "气势西吞夷，光芒南定楚。", "云泉出石窦，淋漓洒玉宇。", "烟萝缠林梢，摇拽垂翠组。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"集禧观池上咏野鹅","p":"","d":"宋代","a":"王安石","c":["池上野鹅无数好，晴天镜里雪毰毸。", "似怜喧暖鸣相逐，疑恋宽闲去却回。", "京洛尘沙工点污，江湖矰弋饱惊猿。", "羽毛的的人难近，嗟此谋身或有才。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋得剑并送汤宪副","p":"","d":"明代","a":"童佩","c":["宝剑曾留此，千年尚有名。星辰片云识，风雨半江生。", "炼想古人迹，功知烈士成。张华在当路，宁使久延平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨中花","p":"","d":"清代","a":"李雯","c":["漫说海榴开遍了，怎无缘、玉山一倒。写破狼毫，题残蚕纸，总为愁人道。", "庭院深深晴昼好，奈相思、梦儿不到。反插牙签，倾倒花里，只是闲烦恼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠王弇州先生 其七","p":"","d":"明代","a":"佘翔","c":["神如秋水映芙蓉，懒著朝衣听晓钟。笑问仙风谁得似，茅家兄弟跨双龙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"正月十四春寒招无为县友人宴集卧牛山麓，马春女史有诗相赠，次韵答之","p":"","d":"当代","a":"潘乐乐","c":["能招嵇阮嵚崎子，来坐溪山料峭春。槛外沙寒窥射蜮，樽前雨迸泣郊麟。", "滔滔自堕谁相惜，脉脉香微世欲新。吾道陵夷天未绝，残宵可待海扬尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"儿子岷自维扬还至金陵得朱县尹仲文手书且云荷接引良厚二绝寄谢时仲文将调官京师假馆维扬 其一","p":"","d":"元代","a":"梁寅","c":["木犀香里设离筵，建业西风八月天。一骑仍留大江北，双凫何日五云边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游烂柯山","p":"","d":"唐代","a":"谢勮","c":["独凌清景出，下视众山中。云日遥相对，川原无不通。", "自致高标末，何心待驭风。", "宛演横半规，穹崇翠微上。云扃掩苔石，千古无人赏。", "宁知后贤心，登此共来往。", "仙弈示樵夫，能言忘归路。因看斧柯烂，孙子发已素。", "孰云遗迹久，举意如旦暮。", "仙僧会真要，应物常渊默。惟将无住理，转与信人说。", "月影清江中，可观不可得。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中代书奉寄圣俞二十五兄","p":"","d":"宋代","a":"欧阳修","c":["忆君去年来自越，值我传车催去阙。", "是时新秋蟹正肥，恨不一醉与君别。", "今年得疾因酒作，一春不饮气弥劣。", "饥肠未惯饱甘脆，九虫寸白争为孽。", "一饱犹能致身患，宠禄岂无神所罚。", "乃知赋予分有涯，适分自然无夭阏。", "昔在洛阳年少时，春思每先花乱发。", "萌芽不待杨柳动，探春马蹄常踏雪。", "到今年才三十九，怕见新花羞白发。", "颜侵塞下风霜色，病过镇阳桃李月。", "兵闲事简居可乐，心意自衰非屑屑。", "日长天暖惟欲睡，睡美尤厌春鸠聒。", "北潭去城无百步，渌水冰销鱼拨刺。", "经时曾未著脚到，好景但听游人说。", "官荣虽厚世味薄，始信衣缨乃羁绁。", "故人有几独思君。安得见君忧暂豁。", "公厨酒美远莫致，念君贳饮衣屡脱。", "郭生书来犹未到，想见新诗甚饥汤。", "少年事事今已去，惟有爱诗心未歇。", "君闲可能为我作，莫辞自书藤纸滑。", "少低笔力容我和，无使难追韵高绝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哭辛霁","p":"","d":"唐代","a":"钱起","c":["流水辞山花别枝，随风一去绝还期。昨夜故人泉下宿，", "今朝白发镜中垂。音徽寂寂空成梦，容范朝朝无见时。", "旦暮馀生几息在，不应存没未尝悲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶有感 其五","p":"","d":"明代","a":"杨爵","c":["当年祗抱素餐羞，一日疏狂七载囚。安得此时廊庙上，有人聊为我皇忧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天津","p":"","d":"明代","a":"区大相","c":["御河三百里，南下作天津。堤似饮牛畔，船如驾鹊滨。", "荣光元瑞洛，德水故溁秦。赴海仙瀛接，经天帝泽新。", "水香花近苑，沙碧柳藏春。今夕乘槎使，谁知问渡人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吉祥寺旧名永寿初李昪为徐温养子徐知训不能容置酒欲杀之行酒吏刁彦能以手爪昪悟而逃伏此寺山谷作记无咎书","p":"","d":"宋代","a":"李吕","c":["招提一径入垂杨，翠竹千竿粉箨香。正要银丝好看客，不须雪乳苦搜肠。", "兴亡徐李一弹指，文字晁黄两擅场。八十老僧无个事，犹将经卷佞空王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"燕卷情丝","p":"高阳台","d":"宋代","a":"蒋捷","c":["燕卷情丝，蜂黏落絮，天教绾住闲愁。闲里清明，匆匆粉涩红羞。灯摇缥晕茸窗冷，语未阑、蛾影分收。好伤情，春也难留，人也难留。芳尘满目悠悠。问萦云佩响，还绕谁楼。别酒才斟，从前心事都休。飞莺纵有风吹转，奈旧家、苑已成秋。莫思量，杨柳湾西，且棹吟舟。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"为志学聘君题惠麓秋晴图","p":"","d":"明代","a":"朱芾","c":["第二泉头坐晚晴，满林松籁杂溪声。涤烦老去卢鸿一，谢俗归来卫叔卿。", "未必《茶经》随火化，拟寻茅屋待春耕。卧游画里违清赏，裹茗它年石上烹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉使辞朝赐酒饭","p":"","d":"明代","a":"祁顺","c":["陛辞天咫尺，赐食励忠勤。翠釜仙庖具，黄封玉液分。", "深恩同湛露，高宴叶需云。使事惭迂拙，何由答圣君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠司徒兼侍中宋宣献挽词四首","p":"","d":"宋代","a":"宋庠","c":["一世文为伯，三階象有光。", "何言隆栋吉，忽叹夜舟藏。", "襚礼朝颁册，哀音路过丧。", "善人今不与，神理太茫茫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游春十二首 其九","p":"","d":"唐代","a":"姚合","c":["朝朝看春色，春色似相怜。酒醒莺啼里，诗成蝶舞前。", "摘花盈手露，折竹满庭烟。亲故多相笑，疏狂似少年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵答李孟宣","p":"","d":"清代","a":"曾广钧","c":["三年踪迹太支离，水转花逢偶在斯。自古孙阳轻骏骨，不为混沌画蛾眉。", "南园新记吾知免，东阁前恩泪尚垂。自笑平生如意少，已曾孤负度辽师。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怕春归 秋山道中，中夜闻落叶声有作","p":"","d":"金朝","a":"蔡松年","c":["老去心情，乐在故园生处。客愁如隋堤乱絮。秋岚照水度黄衣，微雨。记篷窗、旧年吴楚。飘萧鬓绿，日日西风吹去。梦频频、萧闲风土。橙黄蟹紫醉琴书，容与。向他年、尚堪接武。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杨柳","p":"","d":"宋代","a":"宋自适","c":["丝丝烟雨弄轻柔，偏称黄鹂与白鸥。", "才著一蝉嘶晚日，西风容易便成秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鳌峰草堂歌十首 其七","p":"","d":"明代","a":"陆深","c":["新裁道服绿罗寒，别有乌霞制作冠。后夜相思长琐月，酒徒诗伴满长安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重阳太守招登东山以腹疾不能赴","p":"","d":"宋代","a":"郑刚中","c":["卧对佳辰两鬓斑，幽忧深闲屋三间。", "芎能去湿方摩腹，菊可延龄少慰颜。", "骨瘦免教先落帽，酒行无分作颓山。", "遥知太守登高处，座客诗成烛影闲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆江南 其二","p":"","d":"当代","a":"王蛰堪","c":["湖山约，何日共兰舟。水面风荷人面似，梦边骚屑砚边收。", "能不忆龙湫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天命三首 其二","p":"","d":"近代","a":"吴未淳","c":["自乏驱穷术，谁传却老方。烦忧来故故，岁月去堂堂。", "贫觉亲朋远，衰令道业荒。无端身外事，未死讵能忘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"待月桥","p":"","d":"清代","a":"梅庚","c":["石梁横谷口，花片逐残春。风响应茶臼，岚光下葛巾。", "几时鹧鸪月，已照虎溪人。此是峰头路，潺湲好问津。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又题卓锡泉","p":"","d":"宋代","a":"留元崇","c":["吾师知地脉，杖锡此间卓。", "分占神仙囿，敲出清泠玉。", "锡飞已乘龙，泉洁可饮鹤。", "林下几寒暑，池中不盈涸。", "木石常借润，瓶罂随量足。", "池无汲绠线，逗引走修竹。", "渴心生尘埃，对此惬所欲。", "洗耳听松音，漱齿汲山绿。", "更携一壶归，为浣众生浊。", "遥愧山中人，四时自斟酌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵徐子礼提举莺花亭 其六","p":"","d":"宋代","a":"范成大","c":["古藤阴下醉中休，谁与低眉唱此愁。团扇他年书好句，平生知已识儋州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"祝英台近 九秋望日访卞玉京墓，同人分咏得影字，墓在慧山祁陀寺锦树林","p":"","d":"清代","a":"杨抡","c":["碧云窝，黄叶径。古寺一声磬。秋满空山，愁绪暗相引。", "可堪蔓草凄迷，香魂何处，添多少、雨昏花暝。", "万千恨，只恨地老天荒，惊鸿杳无影。玉已成烟，春梦几曾醒。", "试看半壁斜阳，霜林似锦，怕凤子、归来难认。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和杨公济钱塘西湖百题 其三十七 九师堂","p":"","d":"宋代","a":"郭祥正","c":["尔学五古子，缘何绘九师。堂高秋月淡，日用少人知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"幽居奉借遁庵尊兄严韵呈隐之润之二英弟一粲 其一","p":"","d":"金朝","a":"段成己","c":["解鞍借榻避风埃，净拂风轩待我开。诗句堕前还忘却，聊书岁月记曾来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"某氏挽辞二首 其二","p":"","d":"宋代","a":"李昭玘","c":["主馈齐家道，羞蘩肃妇功。疏封秦大国，致养汉三公。", "世事哀荣极，人生梦幻空。慈颜不可望，彤史有遗风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"百花洲梅","p":"","d":"宋代","a":"蒲寿宬","c":["孤根宁不在栽培，枝北枝南春一回。", "尽道游鱼是佳谶，不知洲上有花魁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"诉衷情令","p":"","d":"元代","a":"丘处机","c":["孤城寒角韵悠扬。风送入斜阳。池塘菡萏无色，兰畹有馀香。", "秋日短，暮天长。月华昌。空空寂照，荡荡虚心，一片清凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"壶中天 万顷堂","p":"","d":"近代","a":"凌学攽","c":["踏青随处，趁芳草香轮。耸身飞步。一步桑畦斜岭脚，梯接松坪杉圃。", "希隐杨园，寻春管社，但问渔樵侣。岑楼凌阁，几人猿鸟同住。", "袖携词稿狂吟，层波岸尾，花竹掩亭午。坐啸群峰横翠里，暂傲作湖山主。", "向背吟情，去来帆影，水柳依依舞。可能忘倦，群觅醉，徐巷去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"波斯短歌行译笺 其一○○","p":"","d":"当代","a":"钟锦","c":["明月寻人夜夜来，盈虚不改此追陪。凄凉知有谁相遇？只向空园照冷杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂书示陈国佐胡元茂四首 其四","p":"","d":"宋代","a":"陈与义","c":["昔吾同年友，壮志各南溟。十年风雨过，见此落落星。", "秀者吾元茂，众器见鼎铏。许身稷契间，不但醉六经。", "时逢下车揖，慰我两眼青。勿忧事不理，伯始在朝廷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鸳鸯湖棹歌　之十四","p":"","d":"清代","a":"朱彝尊","c":["堤外湖光堤内池，露荷珠缀夜凉时。", "阿谁月底修萧谱，更按《东堂》旧日词。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"声声慢 立秋日同诸生过城南荒园，予三十年前与碧琴栖息于此","p":"","d":"清代","a":"何振岱","c":["烟深林罅，路转城湾，暑天晴久苔黄。亭榭高低重来，换尽风光。", "当年招游佳境，剩蛙声、一水都荒。石坪上，有锦棚、横晒半桁斜阳。", "今日也偕吟侣，共卷帘、小坐领受茶香。旧曾吟处，寒云占断琴床。", "追想故人仙去，燕飞来、空话雕梁。倚栏久，剩松风吹过新凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其十九","p":"","d":"宋代","a":"丁谓","c":["遥闻甘似醴，不特在金茎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵盘隐陆别驾先贤堂下月夜见寄","p":"","d":"宋代","a":"释居简","c":["自与先贤分不生，酒船隙地鹤随行。桥阑架碧疑虹跨，葑畛围香拟岸横。", "凉度绿云花不寐，尽馀红泪烛须更。明朝秋思谁先得，笑听蘋花与蓼争。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀二首 其二","p":"","d":"明代","a":"卢龙云","c":["草木渐黄落，春华乃变衰。旅雁先霜至，寒蛩傍砌悲。", "栖栖怜在远，税驾渺难期。纡怀何所托，飞蓬愁鬓丝。", "恨无凌风羽，徘徊将安之。沉吟以朝夕，百感良在兹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"飞云洞景十二首 其五 绿野耕云","p":"","d":"明代","a":"卢龙云","c":["春来日上课农亭，满壑云含雨气青。东作易成耕犊健，居閒能诵兔园经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六歌 其六","p":"","d":"宋代","a":"文天祥","c":["我生我生何不辰，孤根不识桃李春。天寒日短重愁人，北风随我铁马尘。", "初怜骨肉钟奇祸，而今骨肉相怜我。汝在北兮婴我怀，我死谁当收我骸。", "人生百年何丑好，黄粱得丧俱草草。呜呼六歌兮勿复道，出门一笑天地老。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"息耕草堂冬日即事杂诗五章与黄太守丈安涛 其三","p":"","d":"清代","a":"姚燮","c":["流水当门过客稀，独依古木看斜晖。大江云雁书应到，白发霜灯子未归。", "海雹夜来犹打屋，园蕉秋后已无衣。鹿卢在手生尘色，起唱朱驎泪一挥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早起","p":"","d":"宋代","a":"郑獬","c":["头疼宿酒未能解，独怕晓寒帘捲迟。懊恨桃花爱飘荡，夜来压折海棠枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天","p":"","d":"近代","a":"汪玢","c":["不为多情解怆情，西风扬起暮云平。庙堂箫管金如土，饿莩兵戈道路横。", "趋枥食，傍垣行，可堪今日作书生。待将一骑冲尘去，踏碎关河古月明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杏花十首为林子赋林子有美膢名杏者别嫁而懊思不已情见乎词而邓子和之 其三","p":"","d":"明代","a":"邓云霄","c":["珍重曾围七宝栏，犹张锦幄护春寒。天香已触花王妒，墙外遥从隔幕看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"述怀五十三首 其二十六","p":"","d":"明代","a":"周是修","c":["昔人多爱酒，为会酒之真。不饮愁万结，饮之愁自伸。", "醉醒醒复醉，恍然忘此身。八仙本高士，七贤岂众伦。", "囊括经济术，觞咏日逡巡。穷通付天命，富贵等浮云。", "九原今可作，愿尔与为群。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓起长安道中","p":"","d":"清代","a":"金孝槐","c":["野店杂声唱晓寒，一钩残月堕林端。红楼梦里何曾识，付与行人马上看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"权知文州刘公","p":"","d":"元代","a":"刘麟瑞","c":["江流移浚向南山，渴死全城胆亦寒。叛将踰城机尽泄，娇儿饮药泪空潸。", "封疆事去君臣在，忠孝名存父子难。五万军民同日尽，可怜巷战尚间关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次山房韵古意四首","p":"","d":"宋代","a":"何梦桂","c":["夜舟不藏壑，川流无回波。", "百年逐忧乐，昼夜相戛摩。", "逝者不复来，皓首成蹉跎。", "谁欤伤凤衰，毋乃楚狂歌。", "兹世固难免，纵有朝与鮀。", "猗兰曲易弹，只恐听者讹。", "折杨杂黄荂，每与俚耳和。", "感此歌晨风，忘我将如何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留别折子明丈二首 其一","p":"","d":"宋代","a":"赵蕃","c":["久作湘中客，数从林下游。契繇先世叙，谊向古人求。", "我敢逃黄绶，公宁卧白头。庙堂有北客，人物想中州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"画眉笔","p":"","d":"清代","a":"刘献池","c":["卧蚕细扫浅深分，堪笑中书陋不文。新月鼠须描更巧，远山螺黛饰成纹。", "毛锥一管蛾添色，柳叶双弯麝有芬。最爱十眉图画肖，挥毫落纸墨缤纷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄亨父（二首）","p":"","d":"明代","a":"陆容","c":["金马门深昼漏迟，石渠新草汉文辞。", "丝纶世掌多君在，竹帛名传为尔期。", "匏叶鋋墙风起处，土花生砌雨晴时。", "革除旧恨成新乐，木榻清樽颇费诗。¤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"榕城八景 其二 绕窖棉阴","p":"","d":"明代","a":"郭之奇","c":["玉川如带绕城阴，入眼丛青翠影侵。已淈污泥从水出，遥参碧汉倩云禁。", "连翩各有扶疏质，独立犹馀萧飒心。不信松寒非可并，多年海国挺孤森。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感寓 其四十五","p":"","d":"明代","a":"朱诚泳","c":["吁嗟兹世人，居官多老饕。孜孜慕名位，焉知奔竞劳。", "权门炙手热，冰山与天高。绥绥乞昏夜，白日矜所遭。", "相君喜松寿，凉州博葡萄。好官我自为，笑骂空嘲嘈。", "君看柄臣第，车马何滔滔。幽人方寂寞，闭门读离骚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏史三十一首 其九","p":"","d":"清代","a":"黄毓祺","c":["梅福弃妻子，吴市变姓名。逢萌客辽海，冠挂东都门。", "偃卧不出户，蒋诩暨郭钦。薛方慕巢由，笑却安车迎。", "陈咸用汉腊，不忍污先人。或远或近间，要归洁其身。", "自惭年老矣，无以报汉恩。谊岂事二姓，印绶徒纷纷。", "杜口十日馀，龚胜真死臣。嗟彼莽大夫，何颜对忠魂。", "附莽亦非一，吾尤恨刘歆。其父最先见，国祚移近亲。", "歆也官国师，进封曰嘉新。何以陈尚书，三子皆同心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早朝十绝","p":"","d":"宋代","a":"赵子潚","c":["廿载承恩侍九重，泰阶玉烛喜遭逢。", "嘉禾瑞协当年兆，伫看远夷贡献同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和吴翁晋梅花诗十三首 其十","p":"","d":"明代","a":"邓云霄","c":["东阁栽来大几围，古今清梦眼中稀。应怜国色羞红粉，始信山人是白衣。", "旷野萧疏幽兴发，闲堂寂静宦情微。五陵年少如相问，不用披裘更策肥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暑中北窗昼卧有作","p":"","d":"宋代","a":"陆游","c":["御疾如治河，但当导之东，下流既有归，自然行地中。", "养生如蓺木，培植要得宜，常使无夭伤，自有干云时。", "我少本多疾，屡亦频危殆，皇天实相之，警告意有在。", "中年弃嗜欲，晚岁节饮食，中坚却外慕，魔盛有定力。", "死生虽天命，人事常相参，茫茫九衢中，百祸起一贪。", "郊虚暑雨余，巾堕脚不袜。", "高卧北窗凉，超然寄疏豁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"醉落魄 其二 去邸","p":"","d":"清代","a":"丁澎","c":["子归可矣。十年不索长安米。掉头沧海成何事。屠狗从游，阅尽人间世。", "学成一敛胡为尔。酒酣不倚田鼢势。裂眦莫救荆卿死。", "挥手而来，浪迹于今始。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和谭云翔送双桂韵","p":"","d":"宋代","a":"王志道","c":["双柱婆娑天上花，殷勤分送士元家。", "捷钤果副联鞯祝，谒谢当期谷旦差。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"俯春亭","p":"郴江百咏并序","d":"宋代","a":"阮阅","c":["城上危亭可摘云，四边山色翠为邻。", "下窥城郭无余蕴，草色花光尽是春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄许澜伯","p":"","d":"明代","a":"张扆","c":["予与澜伯同客绮川，澜伯以禁烟先回扫墓，寓舍有怀，因", "诗以寄。", "水泊山栖分自甘，我留君去意何堪。", "几回雨雪三槎上，强半莺花五坞南。", "宰木空惭归远梦，扁舟犹忆载余酣。", "从今莫惜频相顾，灯火虚斋迟笑谈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杪秋同右史南山眺望","p":"","d":"明代","a":"李攀龙","c":["南山有幽意，驾言此徘徊。湖波荡寒城，四座清光开。", "金天澄素景，秋气何悲哉。繁阴递白日，浮云间往来。", "落木飒中林，流飙激岩隈。朝昏上烟火，原隰被楼台。", "故乡无滞淫，世路多尘埃。念我平生欢，离思壮难裁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"百字令","p":"","d":"清代","a":"龚自珍","c":["龙华劫换，问何人料理，断金零粉。五万春花如梦过，难遣些些春恨。", "帐亸春宵，枕敧红玉，中有沧桑影。定山堂畔，白头可照明镜。", "记得肠断江南，花飞两岸，老去才还尽。何不绛云楼下去，同礼空王钟磬。", "青史闲看，红妆浅拜，回护吾宗肯。漳江一传，心头蓦地来省。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"剑池","p":"","d":"明代","a":"谢肃","c":["巳闻神剑千年化，空俯灵池十丈宽。泉脉尚通江海润，龙光曾照斗牛寒。", "飞梁背负层楼重，老树根将堕石蟠。一啸苍崖回杀气，未容仙鬼咏悲酸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虞美人","p":"","d":"近代","a":"黄侃","c":["痴蚕作茧丝难绝。香烬炉灰热。如今相见已无缘。赢得一回追忆一悽然。", "惊风吹散琼楼梦。别恨伤鸾凤。彩云飞去更无踪。回首蓬山似隔几多重。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送观可道郎中祠南镇使淮府还京（二首）","p":"","d":"元代","a":"王逢","c":["亲奉天香祀会稽，黄封玉检烂金泥。", "地同南岳临朱鸟，祠俯名藩异碧鸡。", "三秀乘春沾雨露，五云披晓见端倪。", "好祈神化资神武，缥渺前旌举白霓。¤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"土番竹枝词 其七","p":"","d":"清代","a":"郁永河","c":["铝贝雕螺各尽功，陆离斑驳碧兼红。番儿项下重重绕，客至疑过绣领宫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"嵩山老人告行作六偈送之","p":"","d":"宋代","a":"释正觉","c":["应缘分影来池月，游世无心出岫云。", "适意归来尖屋底，蔬畦还与力鉏勤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赴召留题英德驿","p":"","d":"明代","a":"汪广洋","c":["英德县前多好山，山峰拥翠出云间。人家星散盗贼少，官舍日长文字閒。", "江水舂容涵夕景，岸花红白带春殷。愧无宋璟匡时策，也自交州奉召还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"除日","p":"","d":"明代","a":"孟洋","c":["边城除日至，犹自备戎机。马上惊残岁，河边对落晖。", "逢人空问讯，逾节始言归。回首年来事，徘徊一振衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"商子引谚","p":"","d":"先秦","a":"佚名","c":["蠹众而木折。", "隙大而墙坏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"石室","p":"","d":"宋代","a":"陈洵直","c":["琅玕蕊笈藏幽谷，唯见白云三五幅。", "昔日天师其姓吴，岩前遗下云中屋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和此阳先生感兴诗二十首","p":"","d":"宋代","a":"刘黻","c":["仙佛各有门，托言深入山。", "一探寂灭宗，一透船汞关。", "菩提司非树，刀圭诧灵丹。", "槁形付尘幻，蜕骨冲飞翰。", "咄咄亦奇事，讵惮力到难。", "儒先著有训，整辔皇路安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"甲午端阳即事","p":"","d":"明代","a":"徐熥","c":["满市贫民尽噪呼，谁家尊酒汎菖蒲。汉廷久已饥方朔，楚泽何人吊左徒。", "残喘厌看长命缕，空囊安用辟兵符。愁来试上孤城望，几处炊烟几处无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八月二十四日","p":"","d":"元代","a":"吴当","c":["丑夜城头烈炬红，数声笳起戍楼空。江山如旧豪华去，无食无衣一病翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月八日百五节林敬舆携酒约盛元仁戴帅初方万里访赵仲实宣慰于西湖第五桥之曲港南山书院五首 其四","p":"","d":"宋代","a":"方回","c":["生长西湖死葬湖，兴言舟子与农夫。全家衣食凭摇橹，历世儿孙学荷锄。", "布衲劣兼蓑笠有，齑汤恐并酱醯无。金盘玉箸环歌舞，午鬨昏空一任渠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"一岩","p":"","d":"宋代","a":"郑清之","c":["一岩洞空挂云山，巧印穹苍半璧环。", "只为广寒宫殿远，故留阙月在人间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一一二首 其四十四","p":"","d":"宋代","a":"释清远","c":["腊月扇子功勋绝，浩浩凉风动寥泬。岂止炎蒸六月天，暂时与君解烦热。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"贺新郎二十首 其四","p":"","d":"清代","a":"李慈铭","c":["看尔扬鞭去。正愁人、东风满目，扰花狂絮。故国苍茫天万里，不辨越山何处。", "更碣海、波涛汹怒。䝟兕磨牙鲛舐腭，但只身、掉臂游行过。", "最怜少日伤孤露。耐荒寒苧灯齑粥，半生难苦。赢得科名酬母教，衣锦暂时团聚。", "讵转足、便迷归路。薄宦未成家陷贼，负高堂、总被微名误。", "穿垒走，涕如雨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次刘五原见寄韵 其四","p":"","d":"明代","a":"释今■（艹黾）","c":["渴想青莲甚，每承阆苑诗。相期缘有待，先遣梦通知。", "应念三生石，曾开双镜池。荷花昨夜放，怀抱益悽其。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜王定国北归第五桥","p":"","d":"宋代","a":"苏轼","c":["白露凄风洗瘴烟，梦回相对两凄然。", "雀罗廷尉非当日，鸠杖先生愈少年。", "世事饱谙思缩手，主恩未报耻归田。", "谁怜第五桥东水，独照台州老郑虔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苦暑消夏二首 其一","p":"","d":"当代","a":"卢青山","c":["夏云如火扑晴栏，镇日尘埃养路蝉。可有清秋能到梦？常祈小病为疗闲。", "夜阑越觉山亲近，心澈才佳月淡寒。小屐单衫无定向，随萤踏尽百千湾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂咏下 野绿堂","p":"","d":"宋代","a":"洪适","c":["缘流排劲草，盈野鞠长芦。烟树高低见，如开平远图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚登广朗阁","p":"","d":"明代","a":"欧大任","c":["广朗坪前霁色鲜，丹梯一望总堪怜。云端曲接千重岭，阁上平开万里天。", "远树暝悬沧海日，空山秋卧鹿门烟。风泉细洒琅玕在，石上镌名不记年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽张云庄宗礼三首 其二","p":"","d":"元代","a":"陶宗仪","c":["嫁殃遭太守，簿录降将军。短景灯馀燄，繁华水上云。", "贤愚谁复辨，玉石竟俱焚。次第修言行，他时表墓文。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酬黄帝锡见和","p":"","d":"宋代","a":"张埴","c":["龙髯初一振，人尽息其机。", "池静朱华出，山凉白鸟归。", "洒能无已已，诗岂去非非。", "仰面楚天过，浮云似白衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"劝穑","p":"","d":"当代","a":"陈忠平","c":["麻鞭水响节时催，陌煖庆云团作堆。岸柳垂腰先好雨，池蛙鼓舌自春雷。", "新颁农政称咸善，旧凿山渠起积隤。劝穑原该专吏责，田家笑讶子胡来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"衡阳庞居士庵","p":"","d":"宋代","a":"释智愚","c":["居士当年错用心，浑家不睦到如今。", "摝篱柄短无人买，空自萧萧风满林。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江楼秋望","p":"","d":"明代","a":"朱高炽","c":["远碧接天涯，登临景自佳。", "蘋洲晴亦雪，枫岸昼常霞。", "落雁过前浦，浮鸥傍浅沙。", "竹篱高晒网，茅屋是渔家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"客邸书怀寄慈伽五羊 其三","p":"","d":"近代","a":"李洸","c":["一担黄卷一疲驱，两鬓飘萧酒一壶。为问乐天何所乐，出山还解在山无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题习编修梅坡卷","p":"","d":"明代","a":"金幼孜","c":["种得梅千树，盈盈雪满坡。捲帘疏影乱，拂席暗香多。", "东阁临风玩，西湖载酒过。高情政如许，赋罢一高歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄沈大本","p":"","d":"明代","a":"谢晋","c":["幕府门西初见时，一言投分即相知。几年别去身多难，今日归来鬓有丝。", "茂苑江山皆旧恨，小齐卮酒总新期。何缘蠲了遐方戍，长共吟窗计较诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽王柳州","p":"","d":"宋代","a":"程珌","c":["才华唐令君，名胜晋参军。", "善政流郴水，遗风袭缙云。", "宝钗当自合，神剑不中分。", "心折白岩路，猿吟日未曛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答李希淳屯田三首","p":"","d":"宋代","a":"邵雍","c":["竹间水际情怀好，月下风前意思多。", "洛社过从无事日，非吾数辈更谁何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽方君政","p":"","d":"明代","a":"陶安","c":["大化何茫茫，生死等朝暮。见面未几何，幽明已殊路。", "人皆劝君仕，况未年迫暮。哀哉万里行，朝命惜虚付。", "虽有善教才，不得一远布。六旬命非促，岂不见晞露。", "知命俭亦乐，闻道死乃安。平生嗜欲薄，既逝魂气完。", "念昔久缔交，文饮意屡欢。握手龙墀上，天风飒高寒。", "归来忽永诀，不复其杯盘。盖棺事始定，长夜嗟漫漫。", "云间九华秀，君心岂能忘。亲朋亦别久，终不返故乡。", "诸孤泣诉我，我亦泪浪浪。东风三月暮，送柩出泮庠。", "归舟驾言发，佳城在青阳。所期贤子孙，勉嗣先业光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风雨後","p":"谒金门","d":"宋代","a":"黄机","c":["风雨後。枝上绿肥红瘦。乐事参差团不就。一春如病酒。楼外暖烟杨柳。忆得年时携手。燕子双双来未久。颇知人意否。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂忆诗 其三","p":"","d":"明代","a":"凌义渠","c":["夏日初长最泥人，半瓯擎到强沾唇。年来守净诚何意，蔬笋无多引箸频。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送刘信之分教云阳","p":"","d":"明代","a":"萧显","c":["宫漏催残欲曙天，儒官辞阙向西川。过家白发怜亲老，分教青衿得士贤。", "舟出九江春见雁，道经三峡晓闻鹃。吾乡自昔多才俊，师席声华到日边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"棠溪宴集赠使君","p":"","d":"明代","a":"严嵩","c":["佳游历松郡，雅集过棠溪。碧筱临池净，垂藤入径迷。", "林香花代发，庭曙鸟先啼。画省班赏接，沧洲影独栖。", "行春人吏惬，听雨客怀悽。野沃饶粳稻，时平撤鼓鼙。", "文叨下客会，尊喜使君携。稍学泉上钓，言留竹下题。", "兴幽忘去棹，烟景在林西。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词 其七十五","p":"","d":"宋代","a":"张公庠","c":["太皞祠坛数级红，青旂摇曳日朦胧。人间未觉东风至，先入宜春小院中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和潞公游天章楚谏议园宅","p":"","d":"宋代","a":"司马光","c":["名卿新治第，上宰旧连墙。", "槐荫青青叶，星邻两两光。", "林花裂锦狭，门路筑沙长。", "共引庭间水，交生壁外篁。", "鱼窥芦琴石，萤散读书床。", "玉帐方怀远，松斋欲就荒。", "旌幢今少憩，兰惠不徒芳。", "早晚平狼望，同来举寿觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"平山堂杂言","p":"","d":"宋代","a":"梅尧臣","c":["芜城之北大明寺，辟堂高爽趣广而意厖。", "欧阳公经始曰平山，山之迤逦苍翠隔大江。", "天清日明了了见峰岭，已胜谢朓龊龊远视於一窗。", "亦笑炀帝造楼摘星放萤火，锦帆落樯旗建杠。", "我今乃来偶同二三友，得句欲霜锺撞。", "却思公之文字世莫双，举酒一使长咽慢肌高揭鼓笛腔，", "万古有作心胸降。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"佑国雄才","p":"满庭芳","d":"元代","a":"王丹桂","c":["佑国雄才，皇家贵戚，御恩守镇平山。一方安堵，何幸感怡颜。视众犹同赤子，宽刑宪、矜恤愚顽。无私曲，政声流美，应遍满人寰。公馀，重积德，投诚奉教，使保心闲。又远蒙见召，祗建灵坛。醮谢诸天圣众，仗青裙、开启阴关。从今后，高真降鉴，名系上仙班。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"芍药图","p":"","d":"元代","a":"凌云翰","c":["十载杨州锦怅遮，红红白白斗繁华。人生总被春瞒却，元是山中药草花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"经故洛城","p":"","d":"唐代","a":"王贞白","c":["卜世何久远，由来仰圣明。山河徒自壮，周召不长生。", "几主任奸谄，诸侯各战争。但馀崩垒在，今古共伤情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饯台倅王司令几叔参釐天府","p":"","d":"宋代","a":"林表民","c":["黼坐颁泥检，黄图驾玉星。自应摅学业，端不藉门庭。", "冻日湖梅白，春风院柳青。从今亨路去，台岭记曾经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"任德广通判拉游长松以诗见贻次其韵 其三","p":"","d":"宋代","a":"李流谦","c":["已成倦鸟不知还，碌碌无奇合抱关。五斗未供鸡鹜饱，一身长占簿书间。", "何妨使我留东阁，久自从公仰泰山。佳句传来浑舍喜，亟将病目洗斓斑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送仙游知县许延评","p":"","d":"宋代","a":"李觏","c":["策名曾未几，奋迅出埃尘。陋巷潜心久，亨衢得意新。", "君恩方责报，民业近多贫。莫学悠悠者，谋身不为人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戏题山庵二首 其二","p":"","d":"宋代","a":"刘克庄","c":["封高四尺宁从险，穴锢三泉岂不愚。客过唐陵悲石马，盗穿秦冢得金凫。", "蛩吟不必人歌挽，鸡絮那无客吊孤。自作铭诗差实录，免教人谤退之谀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠黄比部玉阶二章 其二","p":"","d":"清代","a":"姚燮","c":["峤疋文章守瓣香，颇多清怨匿潇湘。立身为鹤玉同洁，得气先兰春自芳。", "颇愿还山谋种溉，最难入世等潜藏。客中吾有南携秫，留待君閒静试尝。"],"tags":[],"z":"","y":"","s":"","k":"诗"}
];